insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 31/1995, de 8 de noviembre, de prevención de Riesgos Laborales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t07-prevencio-riscos-laborals', 'Tema 7. Llei 31/1995, de prevenció de riscos laborals') on conflict (slug) do nothing;
