insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Carta municipal de Barcelona: principis"},{"n":"2","title":"Organització: Consell Municipal, alcalde i Comissió de Govern"},{"n":"3","title":"Districtes i participació ciutadana"},{"n":"4","title":"Competències municipals en seguretat i convivència"},{"n":"5","title":"La Guàrdia Urbana a la Carta municipal"}]'::jsonb, '["Art. 133 Carta municipal: «La Guardia Urbana de Barcelona actúa como policía de autoridad, policía de seguridad y asistencial y policía judicial»","Art. 10.1 Carta municipal: «El Consejo Municipal es el órgano de máxima representación política de los ciudadanos en el gobierno de la ciudad.»","Art. 13.1 Carta municipal: «Ejercer la dirección superior de todo el personal de la Administración Municipal y la Jefatura de la Policía Municipal.»","Art. 135 Carta municipal: «Instruir atestados por accidentes de circulación dentro del término municipal.»","Art. 94.1 Carta municipal: «La sanción por infracciones a normas de circulación cometidas en vías urbanas corresponde al Alcalde o Alcaldesa.»","Art. 9 Carta municipal: «a) El Consejo Municipal. b) El Alcalde o Alcaldesa. c) La Comisión de Gobierno.»","Art. 8 Carta municipal: «El Gobierno Municipal actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación.»","Art. 11.1 Carta municipal: «d) Aprobar el escudo, la bandera y los demás símbolos distintivos de la ciudad.»","Art. 11.1 Carta municipal: «b) Aprobar el Código Ético de actuación de todo el personal al servicio del municipio.»","Art. 21.3 Carta municipal: «El presupuesto municipal debe garantizar que cada año el 15 por 100 de sus recursos ordinarios, como mínimo, sean gestionados por los distritos.»","Art. 22.1 Carta municipal: «El Presidente o Presidenta del Consejo de Distrito es nombrado y separado por el Alcalde o Alcaldesa de entre los Concejales, a propuesta del Consejo de Distrito»","Art. 128.2 Carta municipal: «Estas competencias y funciones municipales en materia de seguridad son desarrolladas por la Guardia Urbana de Barcelona»","Art. 132.1 Carta municipal: «El Alcalde o Alcaldesa de Barcelona tiene la condición de autoridad competente en materia de seguridad»","Art. 134 Carta municipal: «vela, a partir de las instrucciones generales y las órdenes emanadas de las autoridades municipales, especialmente del Alcalde o Alcaldesa, por el cumplimiento de las ordenanzas, bandos y otras disposiciones municipales»","Art. 96 Carta municipal: «El Ayuntamiento de Barcelona dispone de personal auxiliar de la Guardia Urbana para controlar la utilización adecuada de los aparcamientos en la vía pública»","Art. 131.1 Carta municipal: «Elaborar las políticas y planes de seguridad ciudadana y de prevención del delito, dentro del ámbito municipal.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El govern municipal: principis i òrgans","blocks":[{"text":"La Llei 22/1998, de 30 de desembre, de la Carta municipal de Barcelona, és la llei del Parlament de Catalunya que regula el règim especial de la ciutat. El govern municipal actua d''acord amb els principis d''eficàcia, jerarquia, descentralització, desconcentració i coordinació (art. 8), els mateixos de l''article 103 CE. Són criteris essencials de la seva organització separar les funcions deliberants (ordenació, programació i control) de les executives, desenvolupar la descentralització i desconcentració territorial i fomentar la participació ciutadana.","refs":[{"ref":"Art. 8 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Gobierno Municipal actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación. Deben ser criterios esenciales de su organización diferenciar las funciones deliberantes de ordenación, programación y control de las ejecutivas de gobierno y administración"}]},{"text":"El govern del municipi correspon a cinc òrgans (art. 9): el Consell Municipal, l''alcalde o alcaldessa, la Comissió de Govern, els presidents i regidors de districte, si escau, i els consells de districte. La Junta Local de Seguretat, per exemple, no hi figura com a òrgan de govern.","refs":[{"ref":"Art. 9 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a) El Consejo Municipal. b) El Alcalde o Alcaldesa. c) La Comisión de Gobierno. d) Los Presidentes y Concejales de Distrito, si procede. e) Los Consejos de Distrito."}]}]},{"n":"2","title":"El Consell Municipal","blocks":[{"text":"El Consell Municipal és l''òrgan de màxima representació política dels ciutadans en el govern de la ciutat; el formen els regidors i el presideix l''alcalde (art. 10.1). Els estrangers empadronats poden participar en referèndums i altres consultes que promogui l''Ajuntament (art. 10.5). Funciona en Plenari i en comissions (art. 17.1), i és obligatòria la Comissió d''Hisenda, Pressupostos i Comptes (art. 12.1).","refs":[{"ref":"Art. 10.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Consejo Municipal es el órgano de máxima representación política de los ciudadanos en el gobierno de la ciudad. Está formado por los Concejales y presidido por el Alcalde o Alcaldesa."},{"ref":"Art. 12.1 i 17.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"es obligatoria la existencia de la Comisión de Hacienda, Presupuestos y Cuentas. […] El Consejo Municipal funciona en Plenario y en comisiones."}]},{"text":"Entre les seves atribucions (art. 11.1) hi ha: impulsar, controlar i fiscalitzar els altres òrgans; aprovar el Codi ètic d''actuació de tot el personal al servei del municipi; exercir la iniciativa per alterar el terme municipal; aprovar l''escut, la bandera i els altres símbols de la ciutat; aprovar definitivament el Reglament orgànic i les ordenances; imposar tributs i aprovar pressupostos; aprovar la plantilla i la relació de llocs de treball; i votar la moció de censura i la qüestió de confiança.","refs":[{"ref":"Art. 11.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a) Impulsar, controlar y fiscalizar los demás órganos de gobierno. b) Aprobar el Código Ético de actuación de todo el personal al servicio del municipio. c) Ejercer la iniciativa para alterar el término municipal. d) Aprobar el escudo, la bandera y los demás símbolos distintivos de la ciudad."},{"ref":"Art. 11.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"e) Aprobar de forma definitiva el Reglamento Orgánico, las ordenanzas y cualquier otra norma local cuya aprobación no se atribuya a ningún otro órgano municipal."}]},{"text":"Cal majoria absoluta del nombre legal de membres per a acords com aprovar o modificar definitivament el Reglament orgànic, aprovar l''organització territorial en districtes o transferir funcions a altres administracions (art. 11.3). Les competències del Consell són indelegables en l''alcalde i en la Comissió de Govern (art. 11.4). Els portaveus dels grups formen la Junta de Portaveus, que adopta acords per vot ponderat (art. 18).","refs":[{"ref":"Art. 11.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Es necesario el voto favorable de la mayoría absoluta del número legal de miembros del Consejo Municipal para adoptar los siguientes acuerdos: a)\tAprobar y modificar con carácter definitivo el Reglamento Orgánico. b)\tAprobar la organización territorial en distritos"},{"ref":"Art. 11.4 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Las competencias del Consejo Municipal son indelegables en el Alcalde o Alcaldesa y en la Comisión de Gobierno"},{"ref":"Art. 18.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los acuerdos de la Junta de Portavoces deben adoptarse por voto ponderado."}]}]},{"n":"3","title":"L''alcalde o alcaldessa i els tinents d''alcalde","blocks":[{"text":"L''alcalde és el president de la corporació (art. 13.1). Dirigeix el govern i l''Administració municipals, representa l''Ajuntament, convoca i presideix el Plenari i la Comissió de Govern, organitza l''Administració executiva i nomena els tinents d''alcalde i els regidors de districte, i dicta decrets i bans. Per a aquest temari és clau la lletra h): exerceix la direcció superior de tot el personal i la prefectura de la policia municipal.","refs":[{"ref":"Art. 13.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Alcalde o Alcaldesa es el Presidente o Presidenta de la Corporación Municipal."},{"ref":"Art. 13.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"h)\tEjercer la dirección superior de todo el personal de la Administración Municipal y la Jefatura de la Policía Municipal."}]},{"text":"També li correspon adoptar personalment, sota la seva responsabilitat, en cas de catàstrofe o infortuni públic o de risc greu, les mesures necessàries, de les quals ha de donar compte immediatament al Plenari; i sancionar les faltes de desobediència a la seva autoritat i les infraccions de les ordenances (art. 13.1.l i m). Les atribucions d''organitzar l''Administració executiva i nomenar tinents i regidors de districte, i la de dictar decrets i bans, són indelegables; la resta es poden delegar o desconcentrar (art. 13.2).","refs":[{"ref":"Art. 13.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"l)\tAdoptar personalmente y bajo su responsabilidad, en caso de catástrofe o infortunio público, o de riesgo grave de éstos, las medidas necesarias y adecuadas"},{"ref":"Art. 13.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Las atribuciones del Alcalde o Alcaldesa enumeradas en las letras d) y e) del apartado 1 son indelegables."}]},{"text":"Els tinents d''alcalde els nomena l''alcalde d''entre els regidors i el substitueixen en cas d''absència, malaltia o vacant (art. 14).","refs":[{"ref":"Art. 14 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los Tenientes de Alcalde son nombrados por el Alcalde o Alcaldesa de entre los Concejales, y deben sustituirlo, en caso de ausencia, enfermedad o vacante"}]}]},{"n":"4","title":"La Comissió de Govern","blocks":[{"text":"La Comissió de Govern la integren l''alcalde, els tinents d''alcalde i els regidors que nomeni l''alcalde, que n''ha de donar compte al Consell; també en poden formar part els regidors de districte (art. 15). Exerceix la iniciativa del govern municipal aprovant els projectes de reglaments, ordenances, pressupost i Pla d''actuació municipal; aprova projectes d''urbanització, les formes de gestió dels serveis i els preus públics; autoritza o denega la compatibilitat del personal; i declara la lesivitat dels actes de l''Ajuntament (art. 16).","refs":[{"ref":"Art. 15.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La Comisión de Gobierno está integrada por el Alcalde o Alcaldesa, los Tenientes de Alcalde y los Concejales a los que nombre el Alcalde o Alcaldesa"},{"ref":"Art. 16 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"h)\tAutorizar o denegar la compatibilidad del personal al servicio del Ayuntamiento para el ejercicio de un segundo puesto de trabajo o actividad."}]}]},{"n":"5","title":"Els districtes: principis generals","blocks":[{"text":"Els districtes són òrgans territorials per a la desconcentració de la gestió i la descentralització de la participació ciutadana, i per aplicar una política municipal que corregeixi desequilibris i representi els interessos dels diferents barris (art. 20). Actuen segons els principis d''unitat de govern, eficàcia, coordinació i solidaritat.","refs":[{"ref":"Art. 20 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los distritos son órganos territoriales para la desconcentración de la gestión y descentralización de la participación ciudadana"},{"ref":"Art. 20 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La actuación de los distritos debe ajustarse a los principios de unidad de gobierno, eficacia, coordinación y solidaridad."}]},{"text":"Correspon al Consell Municipal establir els districtes i fixar-ne el nombre, els límits, l''organització i les funcions (art. 21.1). L''organització en districtes s''estén a tot el terme municipal, i el pressupost ha de garantir que cada any com a mínim el 15 per 100 dels recursos ordinaris els gestionin els districtes (art. 21.2 i 21.3).","refs":[{"ref":"Art. 21.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Corresponde al Consejo Municipal acordar el establecimiento de distritos, así como establecer su número y límites territoriales, organización y funciones."},{"ref":"Art. 21.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El presupuesto municipal debe garantizar que cada año el 15 por 100 de sus recursos ordinarios, como mínimo, sean gestionados por los distritos."}]}]},{"n":"6","title":"Organització i règim jurídic dels districtes","blocks":[{"text":"El president o presidenta del Consell de Districte el nomena i el separa l''alcalde d''entre els regidors, a proposta del Consell de Districte (art. 22.1). Representa l''Ajuntament i el districte en la seva demarcació, convoca i presideix el Consell de Districte i el Consell d''Entitats i Associacions, i fomenta la relació amb les entitats (art. 22.2).","refs":[{"ref":"Art. 22.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Presidente o Presidenta del Consejo de Distrito es nombrado y separado por el Alcalde o Alcaldesa de entre los Concejales, a propuesta del Consejo de Distrito"}]},{"text":"El Consell de Districte aprova el seu reglament intern i el programa d''actuació del districte, proposa assumptes als òrgans de govern, emet informe preceptiu (per exemple, sobre el Programa d''actuació municipal, els equipaments del districte o els pressupostos) i controla els òrgans que actuen en el seu àmbit (art. 23.2).","refs":[{"ref":"Art. 23.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tAprobar el Programa de Actuación del distrito y someterlo al Consejo Municipal."}]},{"text":"L''alcalde ha de delegar en un regidor o regidora de districte les seves atribucions en l''àmbit del districte (art. 24). Aquest dirigeix l''administració i el personal del districte i, en cas d''emergència, ha de vetllar per la protecció ciutadana i adoptar les mesures urgents per a la seguretat de persones i béns, donant-ne compte a l''Alcaldia i coordinant-se segons les directrius de la Junta Local de Seguretat. Els acords dels òrgans col·legiats del districte s''adopten per majoria simple, i contra els actes definitius dels òrgans del districte es pot recórrer davant l''alcalde (art. 25).","refs":[{"ref":"Art. 24 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"e)\tVelar por la protección ciudadana al distrito y adoptar, en caso de emergencia, las medidas necesarias de carácter urgente para la seguridad de las personas y bienes, de las que debe dar cuenta inmediatamente a la Alcaldía"},{"ref":"Art. 25 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los acuerdos de los órganos colegiados del distrito deben adoptarse por mayoría simple de sus miembros […] Se puede recurrir ante el Alcalde o Alcaldesa contra los actos de los órganos del distrito que sean definitivos"}]}]},{"n":"7","title":"L''organització municipal executiva i el personal","blocks":[{"text":"Els serveis municipals s''han de gestionar de la manera més sostenible i eficient, per gestió directa (indiferenciada, desconcentrada o funcionalment descentralitzada: organisme autònom local, entitat pública empresarial local o societat mercantil municipal) o per gestió indirecta (art. 45). El Consell, l''alcalde i la Comissió de Govern poden desconcentrar i descentralitzar les seves competències; els centres gestors són òrgans amb autonomia funcional i pressupostària sense personalitat jurídica (art. 46).","refs":[{"ref":"Art. 45 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los servicios y las actividades municipales deben gestionarse de la forma más sostenible y eficiente de entre las que se enumeran a continuación: 1. Gestión directa: a) Gestión indiferenciada. b) Gestión desconcentrada."},{"ref":"Art. 46.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los centros gestores son órganos con autonomía funcional y presupuestaria, sin personalidad jurídica"}]},{"text":"El personal es selecciona i s''ordena segons els principis constitucionals d''igualtat, mèrit i capacitat, i actua amb imparcialitat (art. 51.2). L''integren funcionaris de carrera i interins, personal laboral, personal eventual de confiança i personal directiu; el nomenament i el cessament del personal eventual corresponen a l''alcalde, que n''ha de donar compte al Consell (art. 52).","refs":[{"ref":"Art. 51.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El personal profesional del Ayuntamiento de Barcelona se selecciona y ordena en aplicación de los principios constitucionales de igualdad, mérito y capacidad, y actúa con imparcialidad en el desarrollo de sus funciones."},{"ref":"Art. 52.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El nombramiento y cese del personal eventual corresponden al Alcalde o Alcaldesa, el cual debe dar cuenta de los mismos al Consejo Municipal."}]}]},{"n":"8","title":"Competències en mobilitat","blocks":[{"text":"És competència pròpia de l''Ajuntament l''ordenació del trànsit de persones i vehicles, que inclou la vigilància i la sanció de les infraccions en totes les vies urbanes (art. 93.1). La sanció per infraccions de circulació en vies urbanes correspon a l''alcalde, que la pot desconcentrar o delegar, i els seus actes en aquesta matèria posen fi a la via administrativa (art. 94).","refs":[{"ref":"Art. 93.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Es competencia propia del Ayuntamiento de Barcelona la ordenación del tráfico de personas y vehículos, y ello incluye la vigilancia y sanción de las infracciones en todas las vías urbanas."},{"ref":"Art. 94 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La sanción por infracciones a normas de circulación cometidas en vías urbanas corresponde al Alcalde o Alcaldesa. […] Los actos del Alcalde o Alcaldesa de Barcelona en materia de sanción de infracciones de normas de circulación ponen fin a la vía administrativa."}]},{"text":"L''Ajuntament disposa de personal auxiliar de la Guàrdia Urbana per controlar la utilització adequada dels aparcaments a la via pública i denunciar les conductes contràries a les normes (art. 96). Les ordenances han de controlar l''ús indegut de senyals acústics, fums i sorolls dels vehicles (art. 95). Els vehicles abandonats i fora d''ús tenen el caràcter de residus sòlids i l''Ajuntament els pot desballestar (art. 99).","refs":[{"ref":"Art. 96 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Ayuntamiento de Barcelona dispone de personal auxiliar de la Guardia Urbana para controlar la utilización adecuada de los aparcamientos en la vía pública y denunciar las conductas contrarias a las normas que regulan su utilización."},{"ref":"Art. 99.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los vehículos abandonados y fuera de uso tienen el carácter de residuos sólidos, de acuerdo con la normativa medioambiental, y pueden ser desguazados, competencia que corresponde al Ayuntamiento."}]}]},{"n":"9","title":"Els plans de seguretat viària","blocks":[{"text":"L''Ajuntament ha d''elaborar plans de seguretat viària per a tot el municipi, que aprova el Consell Municipal i que s''han de divulgar àmpliament (art. 100.1). Tenen cinc blocs sistemàtics: a) informació sobre els accidents i investigació de les causes; b) educació viària i divulgació preventiva; c) millores de la via i moderació de la circulació; d) auxili sanitari als ferits; e) protecció escolar. La recaptació de multes no n''és cap.","refs":[{"ref":"Art. 100.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los planes deben ser aprobados por el Consejo Municipal y debe hacerse una amplia divulgación de su contenido, el cual debe tener cinco bloques sistemáticos: a)\tLa información sobre los accidentes y la investigación de sus causas. b)\tLa educación vial y la divulgación preventiva. c)\tLas mejoras de la vía y la moderación de la circulación. d)\tEl auxilio sanitario a los heridos en accidentes. e)\tLa protección escolar."}]}]},{"n":"10","title":"Seguretat ciutadana: competències municipals","blocks":[{"text":"Correspon a l''Ajuntament (art. 128.1): col·laborar en la policia de seguretat ciutadana segons el que estableixi la Junta Local de Seguretat; sancionar per ordenança els actes contraris a l''ordre i la seguretat en l''àmbit de les relacions de veïnatge, respectant els drets fonamentals; i exercir les atribucions en matèria d''espectacles. Aquestes competències les desenvolupa la Guàrdia Urbana, sense perjudici de les d''altres forces i cossos de seguretat (art. 128.2).","refs":[{"ref":"Art. 128.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a)\tColaborar en la función de policía de seguridad ciudadana, de acuerdo con lo que establece la Junta Local de Seguridad."},{"ref":"Art. 128.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Estas competencias y funciones municipales en materia de seguridad son desarrolladas por la Guardia Urbana de Barcelona, sin perjuicio de las que correspondan a otras fuerzas y cuerpos de seguridad."}]},{"text":"L''Ajuntament ha de regular per ordenança com a infraccions greus (art. 129): els desordres i danys greus no constitutius de delicte; els jocs d''atzar no autoritzats a la via pública amb finalitat lucrativa o amb aposta; la tinença sense autorització d''animals que poden causar alarma o danys; els aldarulls per conductes incíviques, vandàliques o per embriaguesa; els comportaments incívics de contingut xenòfob, racista i sexista; el comerç ambulant, la neteja de vidres i altres activitats a la via pública sense permís; i la venda d''alcohol i tabac a menors.","refs":[{"ref":"Art. 129 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tPracticar, en la vía pública, toda clase de juegos de azar no autorizados, con finalidad lucrativa o mediante apuesta."},{"ref":"Art. 129 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"e)\tTener comportamientos incívicos, de contenidos xenófobos, racistas y sexistas. f)\tHacer comercio ambulante, limpieza de cristales y otras actividades en la vía pública sin permiso. g)\tVender productos alcohólicos y tabaco a menores."}]},{"text":"L''Ajuntament emet informe preceptiu sobre el recorregut de les manifestacions, si la normativa ho estableix (art. 130.1). La Junta Local de Seguretat elabora les polítiques i plans de seguretat ciutadana i de prevenció del delicte, els programes de coordinació de les forces i cossos que operen a la ciutat i l''intercanvi d''informació (art. 131.1). L''alcalde, com a president de la Junta, té capacitat executiva per garantir-ne els acords (art. 131.2) i té la condició d''autoritat competent en matèria de seguretat quan exerceix les competències municipals (art. 132.1).","refs":[{"ref":"Art. 131.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a)\tElaborar las políticas y planes de seguridad ciudadana y de prevención del delito, dentro del ámbito municipal."},{"ref":"Art. 132.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Alcalde o Alcaldesa de Barcelona tiene la condición de autoridad competente en materia de seguridad, cuando actúe en ejercicio de las competencias atribuidas al municipio en esta materia."}]}]},{"n":"11","title":"La Guàrdia Urbana a la Carta municipal","blocks":[{"text":"La Guàrdia Urbana actua com a policia d''autoritat, policia de seguretat i assistencial i policia judicial, en els termes de la Carta i de les lleis orgàniques i processals (art. 133). Com a policia d''autoritat vetlla, a partir de les instruccions i ordres de les autoritats municipals, especialment de l''alcalde, pel compliment de les ordenances, bans i altres disposicions municipals (art. 134).","refs":[{"ref":"Art. 133 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La Guardia Urbana de Barcelona actúa como policía de autoridad, policía de seguridad y asistencial y policía judicial, en los términos de la presente Carta y de las leyes orgánicas y procesales aplicables."},{"ref":"Art. 134 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"vela, a partir de las instrucciones generales y las órdenes emanadas de las autoridades municipales, especialmente del Alcalde o Alcaldesa, por el cumplimiento de las ordenanzas, bandos y otras disposiciones municipales."}]},{"text":"Les seves funcions (art. 135) són: protegir les autoritats municipals i els edificis i instal·lacions; ordenar i dirigir la mobilitat i l''ús de la via pública; instruir atestats per accidents de circulació dins el terme municipal; prestar auxili en accidents, catàstrofes o calamitats i participar en els plans de protecció civil; fer diligències de prevenció en el marc de la Junta Local de Seguretat; vigilar els espais públics i col·laborar amb les altres forces en la protecció de manifestacions quan se li requereixi; cooperar en la resolució dels conflictes privats quan se li demani; i captar i analitzar dades d''interès per a la seguretat en els espais públics.","refs":[{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a)\tProteger a las autoridades del Ayuntamiento, así como los edificios e instalaciones municipales. b)\tOrdenar y dirigir la movilidad y uso de la vía pública en el término municipal, de acuerdo con lo establecido en las normas de circulación. c)\tInstruir atestados por accidentes de circulación dentro del término municipal."},{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"g)\tCooperar en la resolución de los conflictos privados cuando se le pida."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Òrgans de govern: Consell Municipal, alcalde, Comissió de Govern, presidents i regidors de districte i consells de districte.","refs":[{"ref":"Art. 9 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"c)\tLa Comisión de Gobierno."}]},{"text":"El Consell Municipal és l''òrgan de màxima representació política i aprova el Codi ètic del personal i l''escut i la bandera.","refs":[{"ref":"Art. 11.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tAprobar el Código Ético de actuación de todo el personal al servicio del municipio."}]},{"text":"L''alcalde té la prefectura de la policia municipal i sanciona les infraccions de circulació en vies urbanes.","refs":[{"ref":"Art. 13.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"la Jefatura de la Policía Municipal"}]},{"text":"Districtes: com a mínim el 15 % dels recursos ordinaris; el president del Consell de Districte el nomena l''alcalde a proposta del Consell.","refs":[{"ref":"Art. 21.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"el 15 por 100 de sus recursos ordinarios"}]},{"text":"Personal auxiliar de la Guàrdia Urbana: per controlar els aparcaments a la via pública.","refs":[{"ref":"Art. 96 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"personal auxiliar de la Guardia Urbana"}]},{"text":"Plans de seguretat viària: els aprova el Consell Municipal i tenen cinc blocs.","refs":[{"ref":"Art. 100.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"cinco bloques sistemáticos"}]},{"text":"Guàrdia Urbana: policia d''autoritat, de seguretat i assistencial i judicial; instrueix atestats de trànsit; coopera en conflictes privats quan se li demana.","refs":[{"ref":"Art. 133 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"policía de autoridad, policía de seguridad y asistencial y policía judicial"}]},{"text":"L''alcalde és autoritat competent en seguretat i presideix la Junta Local de Seguretat, que elabora els plans de seguretat i de prevenció del delicte.","refs":[{"ref":"Art. 131.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"en calidad de Presidente de la Junta Local de Seguridad"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518', null, null, null, null
  from public.topics t where t.slug = 'gub-t09-carta-municipal'
