insert into public.sources (title, url, kind, publisher, published_on) values ('Normes reguladores del funcionament dels districtes de Barcelona (text vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
