insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Els districtes de Barcelona: divisió territorial"},{"n":"2","title":"Normes reguladores del funcionament dels districtes"},{"n":"3","title":"Òrgans de govern del districte"},{"n":"4","title":"Participació ciutadana als districtes"},{"n":"5","title":"Coneixement de la ciutat: barris i districtes"}]'::jsonb, '["Art. 2 Normes reguladores del funcionament dels districtes: «Els districtes de Barcelona són: Ciutat Vella, Eixample, Sants-Montjuïc, Les Corts, Sarrià-Sant Gervasi, Gràcia, Horta-Guinardó, Nou Barris, Sant Andreu i Sant Martí»","Art. 2 Normes reguladores del funcionament dels districtes: «establerts per acord del Consell Plenari de 18 de gener de 1984»","Art. 1 Normes reguladores del funcionament dels districtes: «Els districtes són òrgans territorials per a la desconcentració de la gestió i la descentralització de la participació ciutadana»","Art. 2 Normes reguladores del funcionament dels districtes: «Correspon al Consell Municipal acordar l''establiment de districtes, i també establir-ne el nombre i els límits territorials, l''organització i les funcions.»","Art. 8 Normes reguladores del funcionament dels districtes: «El Consell del Districte és l''òrgan de representació i participació col·lectiva del districte.»","Art. 1 Normes reguladores del funcionament dels districtes: «L''actuació dels districtes s''ha d''ajustar als principis d''unitat de govern, eficàcia, coordinació i solidaritat.»","Art. 5 Normes reguladores del funcionament dels districtes: «El pressupost municipal haurà de garantir que cada any el 15% dels seus recursos ordinaris, com a mínim, siguin gestionats pels districtes.»","Art. 7 Normes reguladores del funcionament dels districtes: «Els districtes constitueixen una estructura orgànica integrada pels òrgans següents: El Consell del Districte. El President/a del Consell del Districte. El Regidor/a del Districte. La Comissió de Govern del Districte.»","Art. 8 Normes reguladores del funcionament dels districtes: «* Fins a 90.000 residents: 15 Consellers/es.»","Art. 8 Normes reguladores del funcionament dels districtes: «* Més de 240.000 residents: 23 Consellers/ es.»","Art. 8 Normes reguladores del funcionament dels districtes: «Els Regidors/res de Districte i els Regidor/ res adscrits actuaran amb veu i sense vot.»","Art. 12 Normes reguladores del funcionament dels districtes: «El President o Presidenta del Consell del Districte només podrà exercir el seu dret a vot en cas d''empat.»","Art. 9 Normes reguladores del funcionament dels districtes: «Els Consells de Districte s''hauran de constituir com a màxim tres mesos després de la constitució del Consistori.»","Art. 8 Normes reguladores del funcionament dels districtes: «El/la cap de la Secretaria del districte actuarà de secretari.»","Art. 13 Normes reguladores del funcionament dels districtes: «Correspon al President/a del Consell de Districte: Representar l''Ajuntament i el districte en la demarcació del districte, sense perjudici de la funció representativa general de l''alcalde.»","Art. 2 Normes reguladores del funcionament dels districtes: «Els límits podran ser modificats pel mateix Consell municipal, a proposta de la Comissió de Govern o dels districtes afectats i amb informe preceptiu dels Consells de Districte respectius.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Els districtes: definició i principis d''actuació","blocks":[{"text":"Per conèixer la ciutat, el primer pas és entendre com s''organitza territorialment. Les Normes reguladores del funcionament dels districtes defineixen els districtes com a òrgans territorials per a la desconcentració de la gestió i la descentralització de la participació ciutadana, i per aplicar una política municipal orientada a corregir desequilibris i representar els interessos dels diversos barris i zones (art. 1 NDIST). La definició reprodueix la de l''article 20 de la Carta municipal.","refs":[{"ref":"Art. 1 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Els districtes són òrgans territorials per a la desconcentració de la gestió i la descentralització de la participació ciutadana i per a l''aplicació d''una política municipal orientada a la correcció dels desequilibris i la representació dels interessos dels diversos barris i zones del municipi."},{"ref":"Art. 20 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los distritos son órganos territoriales para la desconcentración de la gestión y descentralización de la participación ciudadana"}]},{"text":"Els districtes són, a més, àmbits territorials d''exercici de competències, i la seva actuació s''ha d''ajustar als principis d''unitat de govern, eficàcia, coordinació i solidaritat (art. 1 NDIST). Cal no confondre aquests quatre principis amb els del govern municipal en general (eficàcia, jerarquia, descentralització, desconcentració i coordinació).","refs":[{"ref":"Art. 1 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Els districtes són alhora àmbits territorials d''exercici de competències. L''actuació dels districtes s''ha d''ajustar als principis d''unitat de govern, eficàcia, coordinació i solidaritat."}]}]},{"n":"2","title":"Establiment i límits: els deu districtes","blocks":[{"text":"Correspon al Consell Municipal acordar l''establiment de districtes i fixar-ne el nombre, els límits territorials, l''organització i les funcions (art. 2 NDIST; art. 21.1 CMB). Els límits els pot modificar el mateix Consell Municipal, a proposta de la Comissió de Govern o dels districtes afectats i amb informe preceptiu dels consells de districte respectius.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Correspon al Consell Municipal acordar l''establiment de districtes, i també establir-ne el nombre i els límits territorials, l''organització i les funcions."},{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Els límits podran ser modificats pel mateix Consell municipal, a proposta de la Comissió de Govern o dels districtes afectats i amb informe preceptiu dels Consells de Districte respectius."}]},{"text":"Barcelona té deu districtes: Ciutat Vella, Eixample, Sants-Montjuïc, les Corts, Sarrià-Sant Gervasi, Gràcia, Horta-Guinardó, Nou Barris, Sant Andreu i Sant Martí, establerts per acord del Consell Plenari de 18 de gener de 1984. Convé memoritzar-los en aquest ordre (de l''1 al 10), perquè és el mateix que segueix la numeració de les unitats territorials de la Guàrdia Urbana. Noms com el Poblenou, el Raval o Pedralbes són barris, no districtes.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Els districtes de Barcelona són: Ciutat Vella, Eixample, Sants-Montjuïc, Les Corts, Sarrià-Sant Gervasi, Gràcia, Horta-Guinardó, Nou Barris, Sant Andreu i Sant Martí, establerts per acord del Consell Plenari de 18 de gener de 1984."}]},{"text":"Segons la Carta municipal, l''organització en districtes s''estén a tot el terme municipal, tot i que transitòriament el Consell Municipal pot exceptuar zones on per les seves característiques sigui millor que actuïn els òrgans centrals (art. 21.2 CMB).","refs":[{"ref":"Art. 21.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La organización en distritos se extiende a todo el término municipal."}]}]},{"n":"3","title":"Recursos dels districtes","blocks":[{"text":"Els districtes han de disposar de mitjans reals: el pressupost municipal ha de garantir que cada any com a mínim el 15 % dels recursos ordinaris els gestionin els districtes (art. 5 NDIST). És la mateixa xifra que fixa l''article 21.3 de la Carta municipal, i és una pregunta habitual.","refs":[{"ref":"Art. 5 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"El pressupost municipal haurà de garantir que cada any el 15% dels seus recursos ordinaris, com a mínim, siguin gestionats pels districtes."},{"ref":"Art. 21.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"el 15 por 100 de sus recursos ordinarios, como mínimo, sean gestionados por los distritos."}]}]},{"n":"4","title":"Òrgans dels districtes","blocks":[{"text":"Cada districte té una estructura orgànica pròpia integrada per: el Consell del Districte; el president o presidenta del Consell del Districte; el regidor o regidora del districte; la Comissió de Govern del Districte; i les comissions i òrgans consultius i de participació previstos a les Normes (art. 7 NDIST). El Consell Municipal no és un òrgan del districte, sinó de la ciutat.","refs":[{"ref":"Art. 7 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Els districtes constitueixen una estructura orgànica integrada pels òrgans següents: El Consell del Districte. El President/a del Consell del Districte. El Regidor/a del Districte. La Comissió de Govern del Districte. Les comissions i òrgans consultius i de participació previstes en aquestes Normes."}]},{"text":"El funcionament del Consell del Districte s''articula a través de la Junta de Portaveus i dels grups municipals de districte (art. 7 NDIST), de manera paral·lela a com funciona el Consell Municipal a escala de ciutat.","refs":[{"ref":"Art. 7 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"El funcionament del Consell del Districte s''articula a través de la Junta de Portaveus i dels grups municipals de districte."}]}]},{"n":"5","title":"El Consell del Districte: naturalesa, composició i mandat","blocks":[{"text":"El Consell del Districte és l''òrgan de representació i participació col·lectiva del districte (art. 8 NDIST). El regidor o regidora de districte i els regidors adscrits hi actuen amb veu i sense vot, i el cap o la cap de la Secretaria del districte n''actua de secretari.","refs":[{"ref":"Art. 8 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"El Consell del Districte és l''òrgan de representació i participació col·lectiva del districte. Els Regidors/res de Districte i els Regidor/ res adscrits actuaran amb veu i sense vot. El/la cap de la Secretaria del districte actuarà de secretari."}]},{"text":"El nombre de consellers depèn de la població del districte (art. 8 NDIST): fins a 90.000 residents, 15; de 90.001 a 140.000, 17; de 140.001 a 190.000, 19; de 190.001 a 240.000, 21; i més de 240.000 residents, 23. És a dir, l''escala puja de dos en dos.","refs":[{"ref":"Art. 8 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"* Fins a 90.000 residents: 15 Consellers/es. * De 90.001 a 140.000: 17 Consellers/es. * De 140.001 a 190.000: 19 Consellers/es. * De 190.001 a 240.000: 21 Consellers/es. * Més de 240.000 residents: 23 Consellers/ es."}]},{"text":"El mandat dels membres del Consell de Districte dura el mateix que el del Consistori, i els consells s''han de constituir com a màxim tres mesos després de la constitució del Consistori (art. 9 NDIST). La Carta municipal remet al Reglament orgànic la composició dels consells i l''elecció dels seus membres (art. 23.1 CMB).","refs":[{"ref":"Art. 9 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"El mandat dels membres del Consell de Districte tindrà la mateixa durada que la del Consistori. Els Consells de Districte s''hauran de constituir com a màxim tres mesos després de la constitució del Consistori."},{"ref":"Art. 23.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Reglamento orgánico municipal debe regular la composición de los consejos de distrito y la elección de sus miembros."}]}]},{"n":"6","title":"Atribucions del Consell del Districte","blocks":[{"text":"Correspon al Consell del Districte aprovar el Reglament intern d''organització i funcionament del districte i aprovar el Programa d''actuació del districte i sotmetre''l al Consell Municipal (art. 10 NDIST). La Carta municipal hi afegeix, entre d''altres, proposar assumptes als òrgans de govern, elaborar estudis sobre les necessitats del districte, emetre informe preceptiu sobre equipaments, planejament urbanístic o pressupostos, i controlar els òrgans que actuen en el seu territori (art. 23.2 CMB).","refs":[{"ref":"Art. 10 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Correspon al Consell del Districte: Aprovar el Reglament intern d''organització i funcionament del districte. Aprovar el Programa d''actuació del districte i sotmetre''l al Consell Municipal."},{"ref":"Art. 23.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"d)\tElaborar estudios sobre las necesidades del distrito."},{"ref":"Art. 23.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"g)\tEl control y fiscalización de los órganos cuando el ámbito territorial de actuación sea el del distrito."}]},{"text":"Pel que fa al règim jurídic, els acords dels òrgans col·legiats del districte s''adopten per majoria simple dels membres, i contra els actes definitius dels òrgans del districte (o els de tràmit que decideixen el fons, impedeixen continuar el procediment o causen indefensió) es pot recórrer davant l''alcalde o alcaldessa (art. 25 CMB). Així, el districte té autonomia de gestió, però sempre sota la unitat de govern de la ciutat.","refs":[{"ref":"Art. 25 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los acuerdos de los órganos colegiados del distrito deben adoptarse por mayoría simple de sus miembros […] Se puede recurrir ante el Alcalde o Alcaldesa contra los actos de los órganos del distrito que sean definitivos"}]}]},{"n":"7","title":"El president o presidenta i el regidor o regidora del districte","blocks":[{"text":"El president o presidenta del Consell del Districte el nomena i el separa l''alcalde o alcaldessa d''entre els regidors, a proposta del Consell del Districte reunit en sessió extraordinària amb aquest efecte; només pot votar en cas d''empat (art. 12 NDIST). Li correspon representar l''Ajuntament i el districte en la demarcació del districte, sense perjudici de la funció representativa general de l''alcalde (art. 13 NDIST).","refs":[{"ref":"Art. 12 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"El President o Presidenta del Consell del Districte és nomenat i separat per l''Alcalde o Alcaldessa d''entre els Regidors/es, a proposta del Consell del Districte, reunit en sessió extraordinària i amb aquest efecte. El President o Presidenta del Consell del Districte només podrà exercir el seu dret a vot en cas d''empat."},{"ref":"Art. 13 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Representar l''Ajuntament i el districte en la demarcació del districte, sense perjudici de la funció representativa general de l''alcalde."}]},{"text":"La Carta municipal li atribueix també convocar i presidir les sessions del Consell de Districte i fixar-ne l''ordre del dia, sotmetre al Consell el projecte de reglament intern i la proposta de Pla i Programa d''actuació, elevar les propostes del Consell als altres òrgans municipals i fomentar les relacions de l''Ajuntament amb les entitats cíviques i culturals del districte (art. 22.2 CMB).","refs":[{"ref":"Art. 22.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tConvocar y presidir las sesiones del Consejo de Distrito y establecer su orden del día."},{"ref":"Art. 22.2 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"f)\tFomentar las relaciones del Ayuntamiento con las entidades cívicas y culturales del distrito"}]},{"text":"El regidor o regidora de districte rep per delegació de l''alcalde les atribucions que s''exerceixen en el districte: dirigeix l''administració i el personal, impulsa i inspecciona els serveis i obres, i vetlla per la protecció ciutadana, adoptant en cas d''emergència les mesures urgents per a la seguretat de persones i béns d''acord amb les directrius de la Junta Local de Seguretat (art. 24 CMB).","refs":[{"ref":"Art. 24 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a)\tDirigir la administración del distrito y ejercer la dirección del personal adscrito. b) Impulsar e inspeccionar los servicios y obras del distrito."},{"ref":"Art. 24 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"de acuerdo con las directrices establecidas por la Junta Local de Seguridad."}]}]},{"n":"8","title":"Participació ciutadana a la ciutat i als districtes","blocks":[{"text":"L''Ajuntament garanteix la participació ciutadana, especialment en les matèries que afecten més directament la qualitat de vida (art. 30.1 CMB). L''audiència pública és la forma de participació oral, en unitat d''acte, amb què els ciutadans proposen acords o reben informació, i pot ser de ciutat o de districte (art. 31).","refs":[{"ref":"Art. 30.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Ayuntamiento de Barcelona garantiza la participación ciudadana, especialmente en las materias que afectan más directamente la calidad de vida de los ciudadanos."},{"ref":"Art. 31 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Se realiza de forma oral, en unidad de acto y con la asistencia de los ciudadanos que lo deseen. 2.\tEl ámbito de la audiencia pública puede ser de ciudad o distrito."}]},{"text":"L''Ajuntament i cada districte poden fer consultes ciutadanes, que han de respectar el dret de tots els empadronats a ser consultats (art. 35 CMB). El Consell de Ciutat, format per representants de les entitats econòmiques, socials, culturals, professionals i veïnals més representatives, debat el Programa d''actuació, els pressupostos i els grans projectes de ciutat (art. 36). En les matèries de competència dels districtes, el dret de petició pot demanar un debat públic previ (art. 40).","refs":[{"ref":"Art. 35 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"El Ayuntamiento y cada uno de sus distritos pueden pedir la opinión de los ciudadanos en materia de su competencia por medio de la consulta ciudadana"},{"ref":"Art. 36.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Se crea el Consejo de Ciudad, integrado por los representantes de las entidades económicas, sociales, culturales, profesionales y de vecinos más representativas"},{"ref":"Art. 40 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tEn ejercicio de este derecho sobre las materias que sean competencia de los distritos puede solicitarse que se celebre un debate público previo a su resolución."}]}]},{"n":"9","title":"Visió global de la ciutat: els districtes i els seus barris","blocks":[{"text":"Ciutat Vella és el primer districte, l''embrió de la ciutat, delimitat pel perímetre de la muralla antiga; té quatre barris: la Barceloneta, el Raval, el Gòtic i Sant Pere, Santa Caterina i la Ribera. L''Eixample, la ciutat moderna dissenyada per Ildefons Cerdà, en té sis: la Dreta de l''Eixample, l''Antiga Esquerra, la Nova Esquerra, el Fort Pienc, la Sagrada Família i Sant Antoni.","refs":[{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"Ciutat Vella és el primer districte de Barcelona, l’embrió de la ciutat."},{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"Al sud hi trobem la Barceloneta; a ponent, el Raval; al centre, el Gòtic, i a llevant, Sant Pere, Santa Caterina i la Ribera."},{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"L’Eixample està format per sis barris: la Dreta de l’Eixample, l’Antiga Esquerra de l’Eixample, la Nova Esquerra de l’Eixample, el Fort Pienc, la Sagrada Família i Sant Antoni."}]},{"text":"Sants-Montjuïc té vuit barris (entre ells el Poble-sec, Hostafrancs, Sants i la Marina). Les Corts en té tres: les Corts, Pedralbes i la Maternitat i Sant Ramon. Sarrià-Sant Gervasi, el cinquè districte, agrupa Sarrià, les Tres Torres, Sant Gervasi-la Bonanova, Sant Gervasi-Galvany, Vallvidrera, el Tibidabo i les Planes, i el Putxet i el Farró.","refs":[{"ref":"BCN_SM","law":"Districte de Sants-Montjuïc","url":"https://ajuntament.barcelona.cat/sants-montjuic/ca/el-districte-i-els-seus-barris","quote":"Sants-Montjuïc està format per vuit barris: el Poble-sec, Hostafrancs, la Bordeta, la Font de la Guatlla, la Marina de Port, la Marina del Prat Vermell, Sants i Sants-Badal."},{"ref":"BCN_LC","law":"Districte de Les Corts","url":"https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris","quote":"Les Corts és un dels deu districtes de Barcelona i està format pels barris de les Corts, Pedralbes i la Maternitat i Sant Ramon."},{"ref":"BCN_SSG","law":"Districte de Sarrià - Sant Gervasi","url":"https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris","quote":"Sarrià - Sant Gervasi és el cinquè districte de Barcelona."}]},{"text":"Gràcia, antic municipi independent agregat el 1897, té com a nucli la Vila de Gràcia, a més del Camp d''en Grassot i Gràcia Nova i la Salut. Horta-Guinardó és al nord-est, entre Gràcia i Nou Barris; Nou Barris és a l''extrem nord, entre Collserola i Sant Andreu; i Sant Martí té deu barris lligats a la industrialització, entre els quals el Poblenou.","refs":[{"ref":"BCN_GR","law":"Districte de Gràcia","url":"https://ajuntament.barcelona.cat/gracia/ca/el-districte-i-els-seus-barris","quote":"va ser agregat a la ciutat el 1897"},{"ref":"BCN_HG","law":"Districte de Horta-Guinardó","url":"https://ajuntament.barcelona.cat/horta-guinardo/ca/el-districte-i-els-seus-barris","quote":"Està situat al sector nord-est de la ciutat, entre els districtes de Gràcia i Nou Barris."},{"ref":"BCN_NB","law":"Districte de Nou Barris","url":"https://ajuntament.barcelona.cat/noubarris/ca/el-districte-i-els-seus-barris","quote":"Nou Barris és un districte situat a l''extrem nord de la ciutat, entre la serra de Collserola i el districte de Sant Andreu."},{"ref":"BCN_STM","law":"Districte de Sant Martí","url":"https://ajuntament.barcelona.cat/santmarti/ca/el-districte-i-els-seus-barris","quote":"amb deu barris que tenen com a nexe comú el fet de ser primordials en la industrialització i el creixement econòmic de la ciutat."}]},{"text":"Nota: l''epígraf oficial també demana cultura, festes, tradicions, equipaments, carrers i punts d''interès. Aquests continguts es desenvolupen al tema T39 (Mercè, Festa Major de Gràcia, ou com balla, Fossar de les Moreres, mercats, platges, L9 Sud), però la carpeta no té fonts oficials per a la resta (museus, grans equipaments, carrers emblemàtics), ni tampoc una pàgina pròpia de Sant Andreu; per a Sant Andreu només consta el nom a la llista oficial de districtes.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Nou Barris, Sant Andreu i Sant Martí"}]}]},{"n":"10","title":"Els districtes i la Guàrdia Urbana: les unitats territorials","blocks":[{"text":"La Guàrdia Urbana adapta els seus recursos a la realitat de cada barri i districte, i la seva Divisió Territorial s''organitza en unitats territorials (UT) que segueixen la numeració dels districtes: UT01 Ciutat Vella, UT02 Eixample, UT03 Sants-Montjuïc, UT04 les Corts, UT05 Sarrià-Sant Gervasi, UT06 Gràcia, UT07 Horta-Guinardó, UT08 Nou Barris, UT09 Sant Andreu i UT10 Sant Martí (organigrama de novembre de 2025).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Territori Adaptació dels recursos a la realitat de cada barri i districte."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT03 – Sants-Montj. UT05 – Sarrià-S. G. UT04 – Les Corts SSD – Secció de Suport Diürn UT01 – C. Vella UT10 – Sant Martí UT06 – Gràcia UT02 – Eixample UT09 – S. Andreu UT07 – Horta-G."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT08 – Nou Barris"}]},{"text":"L''organigrama preveu també agrupacions de districtes: una de les Corts, Sarrià-Sant Gervasi i Gràcia, i una altra d''Horta-Guinardó, Nou Barris i Sant Andreu. Nota: aquestes dades provenen de l''organigrama publicat al web (novembre de 2025); no s''ha consultat el text del decret de 30 de maig de 2024 que cita el temari.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(3) Agrupació de les Corts, Sarrià-Sant Gervasi, Gràcia. (4) Agrupació d’Horta-Guinardó, Nou Barris, Sant Andreu."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Deu districtes, establerts pel Consell Plenari el 18 de gener de 1984; el Poblenou és un barri de Sant Martí, no un districte.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"establerts per acord del Consell Plenari de 18 de gener de 1984"}]},{"text":"El Consell Municipal estableix els districtes i els seus límits; els límits es modifiquen a proposta de la Comissió de Govern o dels districtes afectats.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"a proposta de la Comissió de Govern o dels districtes afectats"}]},{"text":"Principis dels districtes: unitat de govern, eficàcia, coordinació i solidaritat.","refs":[{"ref":"Art. 1 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"unitat de govern, eficàcia, coordinació i solidaritat"}]},{"text":"Com a mínim, el 15 % dels recursos ordinaris els gestionen els districtes.","refs":[{"ref":"Art. 5 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"el 15% dels seus recursos ordinaris"}]},{"text":"Consell del Districte: òrgan de representació i participació col·lectiva; té de 15 a 23 consellers segons la població; es constitueix en un màxim de tres mesos.","refs":[{"ref":"Art. 9 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"com a màxim tres mesos després de la constitució del Consistori"}]},{"text":"Els regidors hi tenen veu però no vot; fa de secretari el cap de la Secretaria del districte; el president només vota en cas d''empat.","refs":[{"ref":"Art. 12 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"només podrà exercir el seu dret a vot en cas d''empat."}]},{"text":"Numeració de la Guàrdia Urbana: UT01 Ciutat Vella … UT05 Sarrià-Sant Gervasi … UT10 Sant Martí.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT10 – Sant Martí"}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020', null, null, null, null
