insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Guàrdia Urbana de Barcelona: missió i funcions"},{"n":"2","title":"Estructura: comandament i divisions"},{"n":"3","title":"Unitats territorials i unitats centrals"},{"n":"4","title":"Especialitats i serveis de suport"},{"n":"5","title":"Principis d''actuació: proximitat i adaptació al territori"}]'::jsonb, '["Organització Organigrama de la GUB (nov. 2025): «La Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència»","Organització Organigrama de la GUB (nov. 2025): «Divisió Territorial Divisió de Coordinació Divisió de Recursos Operatius i Suport Divisió de Trànsit Divisió d’Estratègia i Suport Logístic»","Organització Organigrama de la GUB (nov. 2025): «Divisió Territorial Divisió de Coordinació Divisió de Recursos Operatius i Suport Divisió de Trànsit»","Missió Organigrama de la GUB (nov. 2025): «Té prop de 3.400 professionals que vetllen per la seguretat, la convivència i el civisme»","Organigrama Organigrama de la GUB (nov. 2025): «UCAT – Unitat Central d’Atestats de Trànsit»","Organigrama Organigrama de la GUB (nov. 2025): «SGO – SCC Servei de Gestió Operativa – Sala Conjunta de Comandament»","Organigrama Organigrama de la GUB (nov. 2025): «UDAI Unitat de Deontologia i Afers Interns (1)»","Organigrama Organigrama de la GUB (nov. 2025): «(1) Unitats que depenen funcionalment de la Gerència de Seguretat i Prevenció i orgànicament del cap del Cos.»","Organigrama Organigrama de la GUB (nov. 2025): «SICD – Secció Instrucció Central Detinguts»","Organigrama Organigrama de la GUB (nov. 2025): «SAV – Servei d’Atenció a la Víctima»","Organigrama Organigrama de la GUB (nov. 2025): «OASV – Oficina d’Anàlisi Seguretat viària»","Organigrama Organigrama de la GUB (nov. 2025): «(5) Unitats que depenen del Servei de Coordinació Nocturna (SCN)»","Organigrama Organigrama de la GUB (nov. 2025): «(3) Agrupació de les Corts, Sarrià-Sant Gervasi, Gràcia.»","Organigrama Organigrama de la GUB (nov. 2025): «OCIG – Oficina Central d’Imatges Gravades»","Organigrama Organigrama de la GUB (nov. 2025): «UREP – Unitat Reforç Emerg. i Prox.»","Missió Organigrama de la GUB (nov. 2025): «Prioritats Proximitat Implicació amb la ciutadania per la convivència i la seguretat: coresponsabilitat i coparticipació.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La Guàrdia Urbana: naturalesa i marc legal","blocks":[{"text":"La Guàrdia Urbana de Barcelona és el cos de policia local de la ciutat. La Llei 16/1991, de les policies locals, disposa que la policia local de cada municipi s''integra en un cos únic, sense perjudici de l''organització interna que s''adopti per reglament (art. 4.1 LPL). Aquesta organització interna és justament el que recull l''organigrama que estudiem en aquest tema.","refs":[{"ref":"Art. 4.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La Policía local de cada Municipio se integrará en un Cuerpo único, sin perjuicio de la organización interna que se adopte por Reglamento."}]},{"text":"La Carta municipal defineix el triple caràcter del cos: actua com a policia d''autoritat, policia de seguretat i assistencial i policia judicial (art. 133 CMB). Els seus membres tenen a tots els efectes, en l''exercici de les funcions, la condició d''agents de l''autoritat (art. 7.1 LPL), i com a integrants d''un institut armat porten l''armament reglamentari (art. 8.1 LPL).","refs":[{"ref":"Art. 133 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La Guardia Urbana de Barcelona actúa como policía de autoridad, policía de seguridad y asistencial y policía judicial"},{"ref":"Art. 7.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los policías locales gozan a todos los efectos, en el ejercicio de sus funciones, de la condición de agentes de la autoridad."},{"ref":"Art. 8.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales, como integrantes de un instituto armado, llevarán el armamento reglamentario que se les asigne."}]},{"text":"Com a policia d''autoritat, vetlla pel compliment de les ordenances, bans i altres disposicions municipals, a partir de les instruccions de les autoritats municipals i especialment de l''alcalde (art. 134 CMB). Entre les seves funcions (art. 135 CMB) hi ha prestar auxili en accidents, catàstrofes o calamitats i participar en els plans de protecció civil, fer diligències de prevenció en el marc de la Junta Local de Seguretat, vigilar els espais públics i captar i analitzar les dades d''interès per a la seguretat. Moltes de les unitats de l''organigrama responen directament a aquestes funcions.","refs":[{"ref":"Art. 134 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"por el cumplimiento de las ordenanzas, bandos y otras disposiciones municipales."},{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"d)\tPrestar auxilio en los supuestos de accidente, catástrofe o calamidad pública, y participar, en la forma establecida en las leyes, en la ejecución de los planes de protección civil."},{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"h)\tCaptar, recibir y analizar todos los datos que tengan interés para el orden y seguridad en los espacios públicos"}]}]},{"n":"2","title":"La cadena de comandament: alcalde, gerència i cap del cos","blocks":[{"text":"El comandament de la policia local l''exerceix l''alcalde, que pot delegar-ne les atribucions; el comandament immediat correspon al cap del cos (art. 4.2 i 4.3 LPL). A Barcelona, la Carta municipal atribueix a l''alcalde la prefectura de la policia municipal (art. 13.1.h CMB).","refs":[{"ref":"Art. 4.2 i 4.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El mando de la Policía local es ejercido por el Alcalde, que puede delegar las correspondientes atribuciones, de acuerdo con la normativa vigente. 3. El mando inmediato de la Policía local corresponde al Jefe del Cuerpo."},{"ref":"Art. 13.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"la Jefatura de la Policía Municipal."}]},{"text":"Segons la informació oficial del cos, la Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència. A l''organigrama, per damunt de l''estructura policial, hi figura el gerent de Seguretat, Prevenció i Convivència.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"La Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"GERENT DE SEGURETAT, PREVENCIÓ I CONVIVÈNCIA"}]},{"text":"El cap del cos, sota el comandament de l''alcalde o de qui aquest delegui, exerceix el comandament immediat; és cap del cos el membre de la plantilla de més graduació (art. 26 LPL). Li correspon dirigir, coordinar i supervisar les operacions i les activitats administratives, avaluar les necessitats de recursos, transformar en ordres concretes les directrius de l''alcalde i informar-lo del funcionament del servei (art. 27 LPL).","refs":[{"ref":"Art. 26.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Es jefe del cuerpo el miembro de la plantilla de mayor graduación"},{"ref":"Art. 27 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Dirigir, coordinar y supervisar las operaciones del Cuerpo, así como las actividades administrativas, para asegurar su eficacia."},{"ref":"Art. 27 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"c) Transformar en órdenes concretas las directrices de los objetivos a conseguir, recibidas del Alcalde o del cargo en quien éste delegue."}]}]},{"n":"3","title":"Escales i categories","blocks":[{"text":"Els cossos de policia local s''estructuren en quatre escales (art. 24.1 LPL): escala superior (superintendent, intendent major i intendent); escala executiva (inspector); escala intermèdia (sotsinspector i sergent); i escala bàsica (caporal i agent). Les escales superior i executiva corresponen al grup A (subgrups A1 i A2), i la intermèdia i la bàsica, al subgrup C1 (art. 24.2).","refs":[{"ref":"Art. 24.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Escala superior, que comprende las categorías de Superintendente, de Intendente Mayor y de Intendente. b) Escala ejecutiva, que comprende la categoría de Inspector. c) Escala intermedia, que comprende las categorías de Subinspector y de Sargento. d) Escala básica, que comprende las categorías de Cabo y de Agente."},{"ref":"Art. 24.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"d) A la escala básica, el grupo C, subgrupo C1."}]},{"text":"La categoria de superintendent només es pot crear en municipis de més de 200.000 habitants, i les d''intendent major i intendent, en els de més de 100.000 (art. 25.3 LPL). Barcelona supera de llarg tots dos llindars.","refs":[{"ref":"Art. 25.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La categoría de Superintendente solamente puede crearse en los Municipios que tienen más de 200.000 habitantes y las categorías de Intendente Mayor y de Intendente solamente pueden crearse en los Municipios que tienen más de 100.000 habitantes."},{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"se situa en 1.729.963 persones"}]}]},{"n":"4","title":"Les cinc divisions operatives","blocks":[{"text":"Per a l''operativa, la Guàrdia Urbana s''organitza en cinc divisions: la Divisió Territorial (DT), la Divisió de Coordinació (DC), la Divisió de Recursos Operatius i Suport (DROS), la Divisió de Trànsit (DTR) i la Divisió d''Estratègia i Suport Logístic (DESL). No hi ha, per exemple, cap «divisió d''investigació criminal».","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"La Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència i s’organitza en les següents divisions operatives: Divisió Territorial Divisió de Coordinació Divisió de Recursos Operatius i Suport Divisió de Trànsit Divisió d’Estratègia i Suport Logístic"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"DC – Divisió Coordinació DT – Divisió Territorial DROS – Recursos Operatius i Suport DTR Divisió de Trànsit"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"DESL – Divisió d’Estratègia i Suport Logístic"}]},{"text":"Convé memoritzar les sigles, que són les que surten a l''examen: DROS vol dir Recursos Operatius i Suport, i DESL, Estratègia i Suport Logístic. L''extracte de l''organigrama és una transcripció del PDF i no permet saber amb seguretat de quina divisió depèn cada unitat; per això, a continuació s''estudien les unitats agrupades per la seva funció, segons el seu nom.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"DROS – Recursos Operatius i Suport"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Organigrama (PDF, novembre 2025)"}]}]},{"n":"5","title":"La Divisió Territorial: les deu unitats territorials","blocks":[{"text":"El desplegament territorial es fa amb deu unitats territorials (UT), una per districte i amb la mateixa numeració: UT01 Ciutat Vella, UT02 Eixample, UT03 Sants-Montjuïc, UT04 les Corts, UT05 Sarrià-Sant Gervasi, UT06 Gràcia, UT07 Horta-Guinardó, UT08 Nou Barris, UT09 Sant Andreu i UT10 Sant Martí.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT03 – Sants-Montj. UT05 – Sarrià-S. G. UT04 – Les Corts SSD – Secció de Suport Diürn UT01 – C. Vella UT10 – Sant Martí UT06 – Gràcia UT02 – Eixample UT09 – S. Andreu UT07 – Horta-G."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT08 – Nou Barris"}]},{"text":"Les notes de l''organigrama preveuen dues agrupacions de districtes: la nota (3), que agrupa les Corts, Sarrià-Sant Gervasi i Gràcia, i la nota (4), que agrupa Horta-Guinardó, Nou Barris i Sant Andreu. Al costat de les UT hi figura també la Secció de Suport Diürn (SSD).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(3) Agrupació de les Corts, Sarrià-Sant Gervasi, Gràcia. (4) Agrupació d’Horta-Guinardó, Nou Barris, Sant Andreu."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SSD – Secció de Suport Diürn"}]}]},{"n":"6","title":"Unitats de coordinació, suport operatiu i servei nocturn","blocks":[{"text":"La coordinació de l''operativa es fa des del SGO-SCC, Servei de Gestió Operativa-Sala Conjunta de Comandament, i el SPD, Servei de Planificació de Dispositius. Entre les unitats de suport operatiu hi ha la UO (Unitat d''Obres), la SM (Secció Muntada), la USTO (Unitat de Suport Tècnic Operatiu) i la UREP (Unitat de Reforç d''Emergències i Proximitat).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SGO – SCC Servei de Gestió Operativa – Sala Conjunta de Comandament SPD – Servei de Planificació de Dispositius UO – Unitat d’Obres SM – Secció Muntada USTO – Unitat de Suport Tècnic Operatiu UREP – Unitat Reforç Emerg. i Prox."}]},{"text":"L''organigrama recull també el SCN, Servei de Coordinació Nocturna: la nota (5) indica les unitats que en depenen. La SP, Secció de Platges, porta la nota (2), que la qualifica d''unitat temporal.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SCN – Servei de Coordinació Nocturna (5) SP – Secció de Platges (2 )"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(2) Unitat temporal."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(5) Unitats que depenen del Servei de Coordinació Nocturna (SCN)"}]}]},{"n":"7","title":"Unitats de trànsit i seguretat viària","blocks":[{"text":"La mobilitat és una funció central del cos: la Carta municipal li encarrega ordenar i dirigir la mobilitat i l''ús de la via pública i instruir atestats per accidents de circulació dins el terme municipal (art. 135 CMB). Per això l''organigrama compta, a més de la Divisió de Trànsit, amb la UCT (Unitat Central de Trànsit), la UCAT (Unitat Central d''Atestats de Trànsit) i l''OCIG (Oficina Central d''Imatges Gravades).","refs":[{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tOrdenar y dirigir la movilidad y uso de la vía pública en el término municipal, de acuerdo con lo establecido en las normas de circulación. c)\tInstruir atestados por accidentes de circulación dentro del término municipal."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UCT – Unitat Central de Trànsit UCAT – Unitat Central d’Atestats de Trànsit OCIG – Oficina Central d’Imatges Gravades"}]},{"text":"En l''àmbit de la prevenció, hi ha l''OASV (Oficina d''Anàlisi de Seguretat Viària), l''OCP (Oficina Central de Proximitat) i l''OEP (Oficina d''Educació en la Prevenció).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"OASV – Oficina d’Anàlisi Seguretat viària OCP – Oficina Central Proximitat OEP – Oficina d’Educació en la Prevenció"}]}]},{"n":"8","title":"Unitats vinculades a la Prefectura i a la protecció","blocks":[{"text":"La UDAI, Unitat de Deontologia i Afers Interns, porta la nota (1): les unitats així marcades depenen funcionalment de la Gerència de Seguretat i Prevenció i orgànicament del cap del cos.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UDAI Unitat de Deontologia i Afers Interns (1)"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(1) Unitats que depenen funcionalment de la Gerència de Seguretat i Prevenció i orgànicament del cap del Cos."}]},{"text":"Altres unitats de l''estructura de comandament són la USP (Unitat de Suport a la Prefectura), la UGR (Unitat de Gestió de Recursos), l''ORIC (Oficina de Relacions Institucionals i Comunicació), l''OGAR (Oficina de Gestió i Avaluació de Recursos) i l''OGO (Oficina de Gestió Organitzativa); l''organigrama també hi assenyala la figura d''adjunt a la Prefectura. En protecció hi ha l''EPA (Equip de Protecció d''Autoritats), l''EPSA (Equip de Protecció de Seguretat de l''Ajuntament) i la UP (Unitat de Protecció), en coherència amb la funció de protegir les autoritats municipals i els edificis (art. 135.a CMB).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"USP – Unitat Suport Prefectura UGR – Unitat Gestió Recursos EPA – Equip Protecció Autoritats Adjunt a Prefectura ORIC – Oficina de Relacions Institucionals i Comunicació OGAR – Oficina de Gestió i Avaluació de Recursos"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"OGO – Oficina de Gestió Organitzativa EPSA – Equip Protecció Seguretat Ajuntament UP – Unitat de Protecció"},{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"a)\tProteger a las autoridades del Ayuntamiento, así como los edificios e instalaciones municipales."}]}]},{"n":"9","title":"Investigació, atenció a la víctima, dades i formació","blocks":[{"text":"En l''àmbit judicial i d''investigació hi ha la SICD (Secció d''Instrucció Central de Detinguts), la UI (Unitat d''Investigació) i la SSJ (Secció de Suport Judicial); l''atenció a les persones afectades per delictes la fa el SAV (Servei d''Atenció a la Víctima).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SICD – Secció Instrucció Central Detinguts"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SAV – Servei d’Atenció a la Víctima UI – Unitat d’Investigació"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SSJ – Secció de Suport Judicial"}]},{"text":"La gestió de la informació es reparteix entre el SGD (Servei de Gestió de Dades), el SID (Servei d''Informació i Documentació) i el SIV (Servei d''Innovació i Videovigilància). La SFAR és la Secció de Formació i Armes, la SAS la Secció d''Avaluació de Serveis, la USL la Unitat de Suport Logístic i l''OPC l''Oficina Permanent de Coordinació.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SID – Servei d’Informació i Documentació SFAR – Secció de Formació i Armes SIV – Servei d’Innovació i Videovigilància SAS – Secció d’Avaluació de Serveis USL – Unitat de Suport Logístic SSJ – Secció de Suport Judicial OPC – Oficina Permanent de Coordinació"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"SGD – Servei de Gestió de Dades"}]}]},{"n":"10","title":"Missió i prioritats del cos","blocks":[{"text":"Segons la seva pàgina de missió, les polítiques de prevenció i seguretat volen erradicar els problemes delictius i vetllar per la convivència com a pilar de la seguretat, i la Guàrdia Urbana hi té un paper clau. El cos té prop de 3.400 professionals que vetllen per la seguretat, la convivència i el civisme, i és reconegut per la vocació de servei públic, la funció de proximitat i el treball en xarxa.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Les polítiques públiques de prevenció i seguretat tenen com a objectiu erradicar els problemes delictius, així com vetllar per la convivència i garantir-la com a pilar de la seguretat."},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Té prop de 3.400 professionals que vetllen per la seguretat, la convivència i el civisme"},{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"La Guàrdia Urbana és reconeguda per: La seva vocació de servei públic La seva funció de proximitat El seu treball en xarxa"}]},{"text":"Les prioritats són cinc: proximitat (implicació amb la ciutadania, coresponsabilitat i coparticipació); territori (adaptació dels recursos a cada barri i districte); transparència (comunicació amb la ciutadania); prevenció (anticipació a les problemàtiques); i transversalitat (implicació amb tots els agents). La «recaptació», per exemple, no hi figura.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Proximitat Implicació amb la ciutadania per la convivència i la seguretat: coresponsabilitat i coparticipació. Territori Adaptació dels recursos a la realitat de cada barri i districte. Transparència Comunicació amb la ciutadania. Prevenció Anticipació a les problemàtiques, per fer un pas més en la prevenció. Transversalitat Implicació transversal amb tots els agents per resoldre les problemàtiques."}]}]},{"n":"11","title":"Principis bàsics d''actuació","blocks":[{"text":"Tota l''estructura treballa sota els principis bàsics d''actuació de la Llei de policies locals (art. 10 LPL): respecte absolut a la Constitució, a l''Estatut i a la resta de l''ordenament; neutralitat política i imparcialitat, sense discriminació; integritat i dignitat; i jerarquia i subordinació, tenint en compte que l''obediència deguda no empara mai ordres que comportin actes manifestament delictius o contraris a la Constitució o a les lleis.","refs":[{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Ejercer sus funciones con absoluto respeto a la Constitución, al Estatuto de Autonomía y al resto del ordenamiento jurídico. b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad"},{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"en ningún caso la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución, al Estatuto o a las leyes."}]},{"text":"En la relació amb la comunitat, els agents han de tractar correctament la ciutadania, actuar amb decisió i sense demora quan calgui evitar un dany greu, immediat i irreparable, regint-se pels principis de congruència, oportunitat i proporcionalitat, i usar les armes només en situacions de risc racionalment greu. També han de mantenir el secret professional i intervenir sempre, de servei o no, en defensa de la llei i de la seguretat ciutadana.","refs":[{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"rigiéndose al hacerlo por los principios de congruencia,oportunidad y proporcionalidad en la utilización de los medios a su alcance."},{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"debiendo intervenir siempre, en cualquier momento y lugar, se hallen o no de servicio, en defensa de la ley y de la seguridad ciudadana."}]}]},{"n":"12","title":"Vigència de l''organigrama","blocks":[{"text":"Nota: el temari cita el Decret de la Comissió de Govern de 30 de maig de 2024, que modifica l''organigrama de la Gerència d''Àrea de Seguretat, Prevenció i Convivència en l''àmbit de la Guàrdia Urbana. Aquest decret no és a la carpeta de fonts; aquests apunts segueixen l''organigrama publicat al web del cos amb data de novembre de 2025, que pot incloure canvis posteriors al decret. Cal contrastar-ho amb el text oficial abans de l''examen.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"PDF de l''organigrama enllaçat (https://ajuntament.barcelona.cat/guardiaurbana/sites/default/files/2026-01/219263_Organigrama_novembre%2025-ca-ES_0.pdf, «Novembre 2025»)"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència; l''alcalde té la prefectura i el cap del cos, el comandament immediat.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"La Guàrdia Urbana depèn de la Gerència de Seguretat, Prevenció i Convivència"}]},{"text":"Cinc divisions: Territorial, Coordinació, Recursos Operatius i Suport (DROS), Trànsit i Estratègia i Suport Logístic.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Divisió de Recursos Operatius i Suport"}]},{"text":"UT01 Ciutat Vella … UT05 Sarrià-Sant Gervasi … UT10 Sant Martí; agrupació (3): les Corts, Sarrià-Sant Gervasi i Gràcia.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UT01 – C. Vella"}]},{"text":"Trànsit: UCT, UCAT (atestats), OCIG (imatges gravades) i OASV (anàlisi de seguretat viària).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UCAT – Unitat Central d’Atestats de Trànsit"}]},{"text":"UDAI (deontologia i afers interns), nota (1): dependència funcional de la Gerència i orgànica del cap del cos.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UDAI Unitat de Deontologia i Afers Interns (1)"}]},{"text":"SICD (instrucció central de detinguts), SAV (atenció a la víctima), SFAR (formació i armes), UREP (reforç d''emergències i proximitat), SGO-SCC (Sala Conjunta de Comandament).","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"UREP – Unitat Reforç Emerg. i Prox."}]},{"text":"Nota (2): la Secció de Platges és una unitat temporal; nota (5): unitats que depenen del Servei de Coordinació Nocturna.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"(2) Unitat temporal."}]},{"text":"Prop de 3.400 professionals; prioritats: proximitat, territori, transparència, prevenció i transversalitat.","refs":[{"ref":"ORG_GUB","law":"Organigrama de la GUB (nov. 2025)","url":"https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio","quote":"Té prop de 3.400 professionals"}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio'), 'https://ajuntament.barcelona.cat/guardiaurbana/ca/qui-som/organitzacio', null, null, null, null
  from public.topics t where t.slug = 'gub-t12-organigrama-guardia-urbana'
