insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança de modificació de l''Ordenança de mesures per fomentar i garantir la convivència ciutadana a l''espai públic de Barcelona (aprovada pel Consell Municipal el 19/12/2025, en vigor el 15/02/2026). Extracte literal dels articles modificats', 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Portal de Transparència', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t14-ordenanca-convivencia', 'Tema 14. Ordenança de mesures per fomentar i garantir la convivència ciutadana a l''espai públic') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t14-ordenanca-convivencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i principis de l''Ordenança de convivència"},{"n":"2","title":"Normes de conducta a l''espai públic"},{"n":"3","title":"Degradació visual: grafits i pintades"},{"n":"4","title":"Usos impropis de l''espai públic i consum de begudes"},{"n":"5","title":"Règim sancionador i mesures de policia"}]'::jsonb, '["Art. 4.1 Ordenança de convivència: «Aquesta Ordenança s''aplica a totes les persones que són a la ciutat de Barcelona.»","Art. 21 Ordenança de convivència: «la realització de les conductes descrites en l''article 20 té la consideració d''infracció lleu i és sancionada amb multa de 100 EUR fins a 600 EUR»","Art. 23.1 Ordenança de convivència: «es prohibeix llençar o abandonar a l''espai públic qualsevol deixalla sòlida de format petit, com ara papers, embolcalls, mocadors, xiclets, vasos, envasos»","Art. 8 Ordenança de convivència: «correspon a l''alcalde o alcaldessa establir i dirigir l''organització municipal executiva en matèria de convivència»","Art. 7 Ordenança de convivència: «El català és la llengua d''ús normal i oficial de l''Ajuntament de Barcelona i ha de ser emprat en les campanyes informatives de comunicació»","Art. 6 bis Ordenança de convivència: «Tothom ha de tenir una conducta responsable en l''ús de l''espai públic i ha de contribuir a què el seu ús comú general sigui amable, accessible i respectuós amb els drets de la ciutadania de Barcelona.»","Art. 23.2 Ordenança de convivència: «llevat que es faci entre les 22:00 hores i les 07:00 hores de l''endemà»","Art. 24 Ordenança de convivència: «els fets descrits en l''article 23 són constitutius d''una infracció lleu, sancionats amb una multa de fins a 750 EUR»","Art. 16 bis Ordenança de convivència: «c) Realitzar tocaments o fregaments amb connotacions sexuals a d''altres persones, inclosos els simuladament accidentals.»","Art. 17.3 Ordenança de convivència: «la realització de les conductes descrites a l''article 16 bis té la consideració d''infracció lleu, sancionada amb una multa de 100 EUR fins a 600 EUR»","Art. 17.2 Ordenança de convivència: «tenen la consideració d''infraccions molt greus, sancionades amb multa de 1.500,01 EUR fins a 3.000 EUR, les conductes descrites en els apartats 2 i 3 de l''article 16»","Art. 17.4 Ordenança de convivència: «la comissió de la infracció s''ha d''imputar a totes les persones membres d''aquests grups que es trobin al lloc dels fets i participin activament en la seva realització»","Art. 46.2 Ordenança de convivència: «c) Es realitzi en grups de com a mínim tres persones»","Art. 47.1 Ordenança de convivència: «La conducta descrita a l''apartat 2 de l''article 46 és constitutiva d''una infracció lleu, sancionada amb multa de 100 EUR fins a 600 EUR.»","Art. 44.1 Ordenança de convivència: «La conducta descrita en l''apartat 1 de l''article 43 constitueix una infracció lleu, sancionada amb multa de fins a 300 EUR»","Art. 43.2 Ordenança de convivència: «c) Quan es realitzi en carrers de 4 metres o menys d''amplada.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Àmbit d''aplicació de l''Ordenança de convivència","blocks":[{"text":"L''Ordenança de mesures per fomentar i garantir la convivència ciutadana a l''espai públic de Barcelona és de 23 de desembre de 2005, i la va modificar una ordenança aprovada definitivament pel Consell Municipal el 19 de desembre de 2025, en vigor des del 15 de febrer de 2026. Aquests apunts segueixen la redacció vigent.","refs":[{"ref":"ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"aprovació definitiva pel Consell Municipal de 19 de desembre de 2025; entrada en vigor el 15 de febrer de 2026"}]},{"text":"Àmbit subjectiu: l''Ordenança s''aplica a totes les persones que són a la ciutat de Barcelona, i també a les conductes de les persones menors d''edat, en els termes de l''article 84 (art. 4). Àmbit objectiu: tots els espais públics de la ciutat (carrers, places, parcs, ponts, túnels, aparcaments, fonts, edificis públics, mobiliari urbà…) i també els espais privats de lliure accés i sense restriccions a l''ús públic (art. 3.2). S''aplica igualment a les platges i zones de bany, inclosa la Zona de Banys del Fòrum, i a la zona portuària en les matèries de competència municipal (art. 3.4).","refs":[{"ref":"Art. 4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"1. Aquesta Ordenança s''aplica a totes les persones que són a la ciutat de Barcelona. 2. Aquesta Ordenança és aplicable a les conductes realitzades per les persones menors d''edat, en els termes i amb les conseqüències previstes a l''article 84"},{"ref":"Art. 3.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"L''Ordenança també és d''aplicació als espais de titularitat privada que siguin de lliure accés i sense restriccions a l''ús públic"},{"ref":"Art. 3.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"l''Ordenança s''aplica a les platges de Barcelona i a les seves zones de bany inclosa la Zona de Banys del Fòrum"}]},{"text":"Nota: la carpeta només conté els articles modificats el 2025 i un extracte del text consolidat (arts. 27-29, 42-43, 74 bis-ter, 76 i 88); la resta de l''articulat (per exemple, el règim de menors de l''article 84 o les mesures de policia) no s''ha pogut consultar.","refs":[{"ref":"ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"Text consolidat vigent (ja incorpora la modificació en vigor el 15/02/2026)"}]}]},{"n":"2","title":"Corresponsabilitat, foment del civisme i governança","blocks":[{"text":"Tothom ha de tenir una conducta responsable en l''ús de l''espai públic i contribuir que el seu ús comú general sigui amable, accessible i respectuós amb els drets de la ciutadania (art. 6 bis, col·laboració i corresponsabilitat).","refs":[{"ref":"Art. 6 bis ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Tothom ha de tenir una conducta responsable en l''ús de l''espai públic i ha de contribuir a què el seu ús comú general sigui amable, accessible i respectuós amb els drets de la ciutadania de Barcelona."}]},{"text":"En el foment de la convivència (art. 7), el català és la llengua d''ús normal i oficial de l''Ajuntament i s''ha d''emprar en les campanyes informatives, sense perjudici d''altres llengües que garanteixin una millor comprensió. L''Ajuntament ha d''impulsar programes específics per a infants, adolescents i joves als centres docents, coordinat amb el Consorci d''Educació, i el govern municipal ha d''informar la comissió competent del Consell Municipal de les campanyes, abans i després de fer-les.","refs":[{"ref":"Art. 7 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"El català és la llengua d''ús normal i oficial de l''Ajuntament de Barcelona i ha de ser emprat en les campanyes informatives de comunicació"},{"ref":"Art. 7 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"sense perjudici que també es poden efectuar en aquelles altres llengües que garanteixin una millor comprensió per a totes les persones."}]},{"text":"Governança de la convivència (art. 8): en virtut de l''article 13.1 de la Carta municipal, correspon a l''alcalde o alcaldessa establir i dirigir l''organització municipal executiva en matèria de convivència.","refs":[{"ref":"Art. 8 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"correspon a l''alcalde o alcaldessa establir i dirigir l''organització municipal executiva en matèria de convivència."}]}]},{"n":"3","title":"Atemptats contra la dignitat de les persones","blocks":[{"text":"El capítol primer del títol II porta ara el títol «Atemptats contra la dignitat, la llibertat i la indemnitat sexual de les persones». Les conductes de l''article 16 estan especialment prohibides quan es dirigeixen contra persones menors d''edat, gent gran, persones amb discapacitat, col·lectiu LGBTI+ o persones sense llar, i es prohibeixen les actituds d''assetjament entre menors a l''espai públic, especialment les agressions o setges a menors fets per grups (art. 16.2 i 16.3).","refs":[{"ref":"ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Atemptats contra la dignitat, la llibertat i la indemnitat sexual de les persones"},{"ref":"Art. 16.2 i 16.3 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Resten especialment prohibides les conductes anteriorment descrites quan tinguin com a objecte o s''adrecin contra persones menors d''edat, gent gran, persones amb discapacitat, col·lectiu LGBTI+ o persones sense llar. 3. En concret, es prohibeixen les actituds d''assetjament entre persones menors d''edat en l''espai públic."}]},{"text":"Els organitzadors d''actes públics han de vetllar perquè no es produeixin aquestes conductes i, si es produeixen, comunicar-ho immediatament als agents de l''autoritat i expulsar o impedir l''accés a qui les faci (art. 16.4). Sancions (art. 17): les conductes de l''article 16.1, si no són delicte, són infracció greu (750,01 a 1.500 €); les dels apartats 2 i 3, infracció molt greu (1.500,01 a 3.000 €).","refs":[{"ref":"Art. 16.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"les persones organitzadores ho han de comunicar immediatament als o a les agents de l''autoritat"},{"ref":"Art. 17.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"té la consideració d''infracció greu, sancionada amb multa de 750,01 EUR fins a 1.500 EUR"},{"ref":"Art. 17.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"tenen la consideració d''infraccions molt greus, sancionades amb multa de 1.500,01 EUR fins a 3.000 EUR, les conductes descrites en els apartats 2 i 3 de l''article 16."}]}]},{"n":"4","title":"Actes contra la llibertat i la indemnitat sexual","blocks":[{"text":"El nou article 16 bis prohibeix fer o incitar a fer a l''espai públic actes que atemptin contra la llibertat i la indemnitat sexual, és a dir, pràctiques amb connotacions sexuals sense el consentiment de les persones destinatàries. Sempre que no siguin infracció penal, es prohibeixen: a) actes d''exhibició obscena o masturbar-se davant persones adultes; b) expressions verbals amb connotacions sexuals degradants o humiliants; c) tocaments o fregaments amb connotacions sexuals, inclosos els simuladament accidentals; d) seguiments per mantenir contacte o fer comentaris sexuals, sense amenaces ni coaccions; e) insistir a tocar, abraçar o fer altres conductes no consentides.","refs":[{"ref":"Art. 16 bis ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"s''entén que són actes que atempten contra la llibertat sexual les pràctiques amb connotacions sexuals sense el consentiment de les persones a les quals van destinades."},{"ref":"Art. 16 bis ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"c) Realitzar tocaments o fregaments amb connotacions sexuals a d''altres persones, inclosos els simuladament accidentals."}]},{"text":"Aquestes conductes són infracció lleu, amb multa de 100 a 600 € (art. 17.3). Si les conductes dels articles 16 i 16 bis les fa un grup, la infracció s''imputa a tots els membres del grup que siguin al lloc dels fets i hi participin activament (art. 17.4). A més, l''Ajuntament ha de fer actuacions preventives, com ara itineraris segurs i punts lila.","refs":[{"ref":"Art. 17.3 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"la realització de les conductes descrites a l''article 16 bis té la consideració d''infracció lleu, sancionada amb una multa de 100 EUR fins a 600 EUR."},{"ref":"Art. 17.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"la comissió de la infracció s''ha d''imputar a totes les persones membres d''aquests grups que es trobin al lloc dels fets i participin activament en la seva realització."},{"ref":"ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"tals com la promoció d''itineraris segurs i l''establiment de punts lila."}]}]},{"n":"5","title":"Degradació visual: grafits i pintades","blocks":[{"text":"Llevat dels espais autoritzats, també és prohibida qualsevol conducta que afavoreixi, promogui o col·labori en les pintades i grafits; per exemple, programar activitats que prevegin fer-ne sense autorització (art. 20.4). Fer les pintades o grafits prohibits per l''article 20 és, sense perjudici de la legislació penal, infracció lleu amb multa de 100 a 600 € (art. 21). Cal estudiar la redacció introduïda per la modificació en vigor des del febrer de 2026.","refs":[{"ref":"Art. 20.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"es consideren constitutives d''aquesta infracció la programació d''activitats que prevegi la realització de pintades i/o grafits en els espais mencionats, sense comptar amb l''autorització corresponent."},{"ref":"Art. 21 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Sens perjudici de la legislació penal, la realització de les conductes descrites en l''article 20 té la consideració d''infracció lleu i és sancionada amb multa de 100 EUR fins a 600 EUR."}]},{"text":"L''Ajuntament pot netejar o reparar subsidiàriament els danys a càrrec dels responsables, que n''assumeixen les despeses; i, d''acord amb l''article 93, la sanció econòmica només es pot substituir per treballs o prestacions en benefici de la comunitat (art. 22.3). Si el grafit pot ser delicte, els agents ho han de comunicar a l''autoritat judicial, sense perjudici de continuar l''expedient sancionador (art. 22.4).","refs":[{"ref":"Art. 22.3 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"només es pot substituir la sanció econòmica derivada de la infracció per treballs o prestacions en benefici de la comunitat."},{"ref":"Art. 22.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Quan el grafit o la pintada puguin ser constitutius d''infracció penal, els i les agents de l''autoritat ho han de posar en coneixement de l''autoritat judicial competent"}]}]},{"n":"6","title":"Embrutar l''espai públic","blocks":[{"text":"Es prohibeix llençar, abandonar o embrutar l''espai públic amb qualsevol producte, i en particular les deixalles sòlides petites com papers, embolcalls, mocadors, xiclets, vasos o envasos (art. 23.1). També es prohibeix regar plantes des de finestres, terrasses o balcons, llevat que es faci entre les 22:00 i les 07:00 h de l''endemà i amb precaucions, i espolsar roba o estores si pot embrutar l''espai públic (art. 23.2).","refs":[{"ref":"Art. 23.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"es prohibeix llençar o abandonar a l''espai públic qualsevol deixalla sòlida de format petit, com ara papers, embolcalls, mocadors, xiclets, vasos, envasos"},{"ref":"Art. 23.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"a) Regar plantes des de finestres, terrasses, terrats, balcons o llocs similars, llevat que es faci entre les 22:00 hores i les 07:00 hores de l''endemà"}]},{"text":"Tret que siguin una infracció més greu segons l''Ordenança del medi ambient, aquestes conductes són infracció lleu amb multa de fins a 750 € (art. 24). L''article 25 s''ha suprimit.","refs":[{"ref":"Art. 24 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Tret que els fets constitueixin una infracció més greu d''acord amb l''Ordenança del medi ambient, els fets descrits en l''article 23 són constitutius d''una infracció lleu, sancionats amb una multa de fins a 750 EUR."},{"ref":"ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Se suprimeix l''article 25."}]}]},{"n":"7","title":"Juguesques i triler","blocks":[{"text":"És prohibit oferir a l''espai públic juguesques que comportin apostes amb diners o béns, llevat d''autorització específica (art. 27). Oferir juguesques amb apostes és infracció greu (750,01 a 1.500 €); són molt greus (1.500,01 a 3.000 €) les que comporten un risc de pèrdua més enllà del que és habitual en el joc d''atzar i, en qualsevol cas, el joc del triler (art. 28). Els agents fan la intervenció cautelar dels mitjans emprats i dels fruits de la conducta (art. 29).","refs":[{"ref":"Art. 27 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"És prohibit a l''espai públic l''oferiment de juguesques que comportin apostes amb diners o béns, llevat d''autorització específica."},{"ref":"Art. 28 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"Tindran la consideració d''infraccions molt greus, i seran sancionades amb multa de 1.500,01 a 3.000 EUR, l''oferiment de juguesques que comportin un risc de pèrdua més enllà del que és habitual en tot joc d''atzar, i, en qualsevol cas, el joc de triler."},{"ref":"Art. 29 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"els agents de l''autoritat procediran a la intervenció cautelar dels mitjans emprats, així com dels fruits de la conducta infractora."}]}]},{"n":"8","title":"Altres usos impropis: acrobàcies i serveis sexuals","blocks":[{"text":"Sense perjudici de l''Ordenança de circulació, no es permeten acrobàcies i jocs d''habilitat amb bicicletes, patins o monopatins fora de les àrees destinades a l''efecte, ni utilitzar escales, baranes, bancs o altre mobiliari urbà per a acrobàcies amb patins i monopatins (art. 31.3).","refs":[{"ref":"Art. 31.3 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"no és permesa la pràctica d''acrobàcies i jocs d''habilitat amb bicicletes, patins o monopatins fora de les àrees destinades a l''efecte."}]},{"text":"Es prohibeix que el demandant sol·liciti o accepti serveis sexuals retribuïts en zones de trànsit públic a prop de llocs destinats a menors (centres educatius, parcs infantils, espais d''oci) o quan pugui generar un risc per a la seguretat viària (art. 39.2). Aquestes conductes del primer paràgraf de l''article 39.2 són greus, amb multa de 601 a 30.000 € (art. 40.1). Cal informar les persones que ofereixen aquests serveis dels programes de l''Agència per a l''Abordatge Integral del Treball Sexual (ABITS).","refs":[{"ref":"Art. 39.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Es prohibeix la sol·licitud o l''acceptació per part del demandant de serveis sexuals retribuïts en zones de trànsit públic en les proximitats de llocs destinats a l''ús per part de persones menors"},{"ref":"Art. 40.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Les conductes recollides al primer paràgraf de l''article 39.2 tenen la consideració de greus i són sancionades amb multa de 601 EUR a 30.000 EUR."},{"ref":"ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Agència per a l''Abordatge Integral del Treball Sexual (ABITS)"}]}]},{"n":"9","title":"Necessitats fisiològiques","blocks":[{"text":"La regulació es fonamenta en la protecció de la salut pública i la salubritat, el dret a un espai públic net i el respecte a les pautes de civisme (art. 42). És prohibit fer necessitats fisiològiques (defecar, orinar, escopir) a l''espai públic, llevat de les instal·lacions destinades especialment a aquesta finalitat (art. 43.1).","refs":[{"ref":"Art. 42 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"la protecció de la salut pública i la salubritat, el dret de gaudir d''un espai públic net i no degradat"},{"ref":"Art. 43 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"És prohibit fer necessitats fisiològiques, com ara defecar, orinar, escopir, en qualsevol dels espais definits a l''article 3 d''aquesta Ordenança com a àmbit d''aplicació objectiva, llevat de les instal·lacions o elements que estiguin destinats especialment a la realització d''aquelles necessitats."}]},{"text":"La prohibició s''agreuja (art. 43.2): a) a prop de lavabos públics o de lliure accés oberts; b) a prop d''establiments de concurrència pública, com locals musicals o de restauració; c) en carrers de 4 metres o menys d''amplada; d) en espais de concorreguda afluència o freqüentats per menors, o en monuments o edificis catalogats o protegits.","refs":[{"ref":"Art. 43.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"a) Quan es realitzi en les immediacions de lavabos públics o de lliure accés públic si es troben en horari obert, tant d''estructura fixa com desmuntable. b) Quan es realitzi en les immediacions d''establiments de concurrència pública, tals com establiments musicals o de restauració. c) Quan es realitzi en carrers de 4 metres o menys d''amplada."},{"ref":"Art. 43.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"d) Quan es realitzi en espais de concorreguda afluència de persones o que siguin freqüentats per persones menors d''edat, o en monuments o edificis catalogats o protegits."}]},{"text":"Sancions (art. 44): la conducta bàsica és lleu, amb multa de fins a 300 €; en els casos a), b) i c), lleu amb multa de 300 a 750 €; i en els espais de la lletra d), greu, de 750,01 a 1.500 €. Si la persona necessita atenció social o mèdica, els agents han d''atendre-la i, si cal per salut, acompanyar-la al servei adient (art. 44 bis).","refs":[{"ref":"Art. 44.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"La conducta descrita en l''apartat 1 de l''article 43 constitueix una infracció lleu, sancionada amb multa de fins a 300 EUR"},{"ref":"Art. 44.3 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"Quan l''esmentada conducta es realitzi en els espais descrits a la lletra d) de l''article 43.2 es considera una infracció greu, sancionada amb multa de 750,01 EUR a 1.500 EUR."},{"ref":"Art. 44 bis ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"les han d''acompanyar a l''establiment o servei públic adient, amb la finalitat de socórrer-les o ajudar-les"}]}]},{"n":"10","title":"Consum de begudes alcohòliques","blocks":[{"text":"L''Ajuntament ha de vetllar perquè no es consumeixin begudes alcohòliques als espais públics, i el consum es prohibeix quan pertorba greument la tranquil·litat ciutadana (art. 46.1 i 46.2). Això passa quan: a) pertorba el descans veïnal; b) es fa en zones amb mesures contra el soroll de l''oci nocturn; c) es fa en grups de com a mínim tres persones o en espais amb risc real de consum massiu o aglomeració; d) causa molèsties greus als usuaris de l''espai públic.","refs":[{"ref":"Art. 46.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"a) Pertorbi el descans veïnal. b) Es realitzi en espais públics inclosos en zones en les quals s''estiguin aplicant mesures destinades a la reducció de soroll causat per l''oci nocturn. c) Es realitzi en grups de com a mínim tres persones"}]},{"text":"Està especialment prohibit el consum en llocs amb afluència de menors o de manera que pugui incitar-los (art. 46.3), i organitzar o vendre circuïts per diversos locals perquè els participants consumeixin alcohol de manera continuada (art. 46.4). Les prohibicions dels apartats 2 i 3 no s''apliquen a establiments i espais reservats, com terrasses i vetlladors, ni als consums amb autorització puntual (art. 46.5). El consum de l''article 46.2 és infracció lleu, amb multa de 100 a 600 € (art. 47.1).","refs":[{"ref":"Art. 46.4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"organitzar, vendre o realitzar circuïts o itineraris per diversos establiments de pública concurrència o locals d''oci de la ciutat"},{"ref":"Art. 46.5 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"no són d''aplicació quan el consum de begudes alcohòliques tingui lloc en establiments i altres espais reservats expressament per a aquesta finalitat, com ara terrasses i vetlladors"},{"ref":"Art. 47.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"La conducta descrita a l''apartat 2 de l''article 46 és constitutiva d''una infracció lleu, sancionada amb multa de 100 EUR fins a 600 EUR."}]}]},{"n":"11","title":"Nuesa i vestimenta a l''espai públic","blocks":[{"text":"Es prohibeix transitar o romandre a l''espai públic totalment despullat, llevat d''autorització expressa per decret d''Alcaldia per a esdeveniments o llocs concrets. No es pot anar amb vestimenta de bany fora de platges, piscines i zones habilitades, tot i que no s''aplica als passejos marítims ni als carrers adjacents a les platges. Tampoc es pot anar sense samarreta o peça que cobreixi el tors, llevat que s''estigui fent activitat física o esportiva, ni amb objectes que representin explícitament genitals (art. 74 bis).","refs":[{"ref":"Art. 74 bis ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"Es prohibeix transitar o romandre als espais públics totalment despullat o despullada, excepte en aquells casos en què s’hagi concedit una autorització expressa mitjançant Decret d’Alcaldia"},{"ref":"Art. 74 bis ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"Aquesta restricció no és aplicable als passejos marítims ni als carrers o vies immediatament adjacents a les platges o a la resta del litoral."},{"ref":"Art. 74 bis ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"Resta prohibit transitar o romandre als espais públics sense samarreta, camisa o una altra peça de roba que cobreixi el tors, llevat que s’estigui practicant alguna activitat física o esportiva."}]},{"text":"La nuesa total és infracció lleu amb multa de 300 a 500 €; les altres conductes, lleus amb multa de 120 a 300 € (art. 74 ter). En tots els casos, els agents primer han de recordar a la persona que la conducta és prohibida.","refs":[{"ref":"Art. 74 ter ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"La realització de la conducta descrita en el primer apartat de l’article anterior serà considerada infracció lleu, i serà sancionada amb una multa de 300 a 500 euros."},{"ref":"Art. 74 ter ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"els o les agents de l’autoritat han de recordar en primer lloc a les persones infractores que la seva conducta és prohibida"}]}]},{"n":"12","title":"Funcions policials i graduació de les sancions","blocks":[{"text":"Com a policia administrativa, la Guàrdia Urbana és l''encarregada de vetllar pel compliment de l''Ordenança, denunciar les conductes contràries i adoptar les altres mesures (art. 76). D''acord amb els convenis de col·laboració entre la Generalitat i l''Ajuntament, la recepció i formulació de denúncies per incompliments de la normativa municipal és un servei d''actuació conjunta en què també col·labora la Policia de la Generalitat-Mossos d''Esquadra; l''Ajuntament fixa els criteris generals per a tots dos cossos.","refs":[{"ref":"Art. 76 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"En la seva condició de policia administrativa, la Guàrdia Urbana"},{"ref":"Art. 76 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"també col·labora en aquestes funcions en els termes establerts en els convenis esmentats la Policia de la Generalitat-Mossos d’Esquadra."}]},{"text":"La imposició de sancions es guia pel principi de proporcionalitat (art. 88), tenint en compte la gravetat, la culpabilitat i la intencionalitat, els perjudicis, la reincidència, la persistència i la capacitat econòmica de l''infractor. Hi ha reincidència quan es comet en el termini d''un any més d''una infracció de l''Ordenança declarada per resolució ferma en via administrativa.","refs":[{"ref":"Art. 88 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"La imposició de les sancions previstes en aquesta Ordenança s’ha de guiar per l’aplicació del principi de proporcionalitat."},{"ref":"Art. 88 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"S’entén que hi ha reincidència quan s’ha comès en el termini d’un any més d’una infracció d’aquesta Ordenança i ha estat declarat per resolució ferma en via administrativa."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Redacció vigent des del 15/02/2026; s''aplica a totes les persones que són a Barcelona.","refs":[{"ref":"Art. 4 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"s''aplica a totes les persones que són a la ciutat de Barcelona"}]},{"text":"Grafits: infracció lleu de 100 a 600 €; la multa només es pot substituir per treballs en benefici de la comunitat.","refs":[{"ref":"Art. 21 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"infracció lleu i és sancionada amb multa de 100 EUR fins a 600 EUR"}]},{"text":"Article 16 bis (tocaments, exhibicionisme, comentaris sexuals): lleu, de 100 a 600 €; article 16.2 i 16.3 (víctimes vulnerables, assetjament entre menors): molt greu, de 1.500,01 a 3.000 €.","refs":[{"ref":"Art. 17.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"1.500,01 EUR fins a 3.000 EUR"}]},{"text":"Embrutar: lleu, fins a 750 €; regar plantes només de 22:00 a 07:00 h.","refs":[{"ref":"Art. 24 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"fins a 750 EUR"}]},{"text":"Alcohol: pertorbació greu en grups de 3 persones o més; lleu, de 100 a 600 €; no afecta terrasses i vetlladors.","refs":[{"ref":"Art. 46.2 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"grups de com a mínim tres persones"}]},{"text":"Necessitats fisiològiques: fins a 300 €; de 300 a 750 € en carrers de 4 m o menys; greu en monuments (de 750,01 a 1.500 €).","refs":[{"ref":"Art. 44.1 ORD_CONV","law":"Ordenança de convivència","url":"https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia","quote":"fins a 300 EUR"}]},{"text":"Triler: molt greu (de 1.500,01 a 3.000 €), amb intervenció cautelar dels mitjans i dels fruits.","refs":[{"ref":"Art. 28 ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"el joc de triler"}]},{"text":"Nuesa total: de 300 a 500 €; sense samarreta: permès si es fa esport. Serveis sexuals a prop de menors: greu, de 601 a 30.000 €.","refs":[{"ref":"Art. 74 ter ORD_CONVC","law":"Ordenança de convivència (text consolidat)","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952049","quote":"multa de 300 a 500 euros"}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia'), 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia', null, null, null, null
