       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança de circulació de vianants i de vehicles de Barcelona (text consolidat vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t16-ordenanca-circulacio', 'Tema 16. Ordenança de circulació de vianants i de vehicles') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t16-ordenanca-circulacio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Prioritat de pas i velocitats al nucli urbà"},{"n":"2","title":"Circulació de vehicles de motor, cicles i bicicletes"},{"n":"3","title":"Grups turístics i transport de mercaderies en bicicleta"},{"n":"4","title":"Vehicles de mobilitat personal (VMP)"},{"n":"5","title":"Retirada de vehicles i concurrència d''infraccions"}]'::jsonb, '["Art. 10 Ordenança de circulació: «Els i les vianants tenen prioritat sobre tot tipus de vehicles tal com queda regulat a la llei de trànsit i els seus reglaments de desenvolupament.»","Art. 11 Ordenança de circulació: «En els carrers on es circuli només per un carril, per sentit, i sense comptabilitzar els carrils reservats, els vehicles no poden circular a més de 30 km/h.»","Art. 13 Ordenança de circulació: «Els vehicles de motor i ciclomotors no poden circular per voreres, andanes, passeigs i carril-bici.»","VMP Ordenança de circulació: «L''edat mínima permesa per circular amb un vehicle de mobilitat personal és de 16 anys.»","VMP Ordenança de circulació: «Els vehicles de mobilitat personal per a transport personal o de mercaderies són vehicles d''una única plaça i no poden anar ocupats per més d''una persona.»","Art. 11 Ordenança de circulació: «En cas de pluja, d''obres, paviment deficient cal adaptar la velocitat com a mesura de precaució.»","Art. 11 Ordenança de circulació: «En els carrers que disposin de plataforma única de calçada i vorera, els vehicles no poden circular a més de 20 km/h, excepte senyalització específica.»","Art. 11 Ordenança de circulació: «En els carrers sense un espai destinat exclusivament al trànsit de vianants la velocitat màxima s''estableix en 10 km/h»","Art. 11 Ordenança de circulació: «a aquests efectes els carrils reservats per a la circulació de determinats usuaris o ús exclusiu de transport públic no es comptabilitzen»","Art. 10 Ordenança de circulació: «gaudeixen de prioritat sobre la resta de vehicles, però no sobre els i les vianants»","Art. 14 Ordenança de circulació: «ha de desenvolupar-se preferentment pel carril més proper a la vorera»","Art. 14 Ordenança de circulació: «Han d''evitar circular a menys d''1 metre de les façanes»","Art. 14 Ordenança de circulació: «quan el conductor sigui major d''edat, podrà transportar un menor, amb casc homologat, en seient addicional que haurà d''ésser igualment homologat»","VMP Ordenança de circulació: «Les persones conductores d''un vehicle de mobilitat personal estan obligades a fer servir un casc de protecció que compleixi alguna certificació apta per a bicicleta, skate o ciclomotor, o casc homologat per a motocicletes.»","VMP Ordenança de circulació: «En cap cas les persones conductores menors d''edat poden circular per les vies urbanes amb una taxa d''alcohol en sang superior a 0 grams per litre»","Concurrència Ordenança de circulació: «Cada dia que un vehicle romangui estacionat en lloc prohibit causa una infracció independent.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"L''Ordenança de circulació i la competència municipal","blocks":[{"text":"L''Ordenança de circulació de vianants i de vehicles de Barcelona es va aprovar el 27 de novembre de 1998 i va entrar en vigor el 16 de gener de 1999; el text consolidat està al corrent de les darreres modificacions. Desenvolupa a escala urbana la legislació estatal de trànsit, que atribueix als municipis la regulació, l''ordenació, la gestió, la vigilància i la disciplina, amb agents propis, del trànsit a les vies urbanes, i la regulació per ordenança dels usos d''aquestes vies (art. 7 LTSV).","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Aprovació 27 novembre 1998. Entrada en Vigor 16 gener 1999."},{"ref":"Art. 7 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) La regulación, ordenación, gestión, vigilancia y disciplina, por medio de agentes propios, del tráfico en las vías urbanas de su titularidad"},{"ref":"Art. 7 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"b) La regulación mediante ordenanza municipal de circulación, de los usos de las vías urbanas"}]},{"text":"A Barcelona, la Carta municipal reconeix com a competència pròpia de l''Ajuntament l''ordenació del trànsit de persones i vehicles, inclosa la vigilància i la sanció de les infraccions a totes les vies urbanes, i atribueix la sanció a l''alcalde (arts. 93.1 i 94.1 CMB).","refs":[{"ref":"Art. 93.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Es competencia propia del Ayuntamiento de Barcelona la ordenación del tráfico de personas y vehículos, y ello incluye la vigilancia y sanción de las infracciones en todas las vías urbanas."},{"ref":"Art. 94.1 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"La sanción por infracciones a normas de circulación cometidas en vías urbanas corresponde al Alcalde o Alcaldesa."}]},{"text":"Sobre el terreny, la Guàrdia Urbana és la que ordena i dirigeix la mobilitat i l''ús de la via pública d''acord amb les normes de circulació, i la que instrueix els atestats per accidents de circulació dins el terme municipal (art. 135 CMB). Els actes de l''alcalde en matèria de sancions de circulació posen fi a la via administrativa (art. 94.3 CMB).","refs":[{"ref":"Art. 135 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"b)\tOrdenar y dirigir la movilidad y uso de la vía pública en el término municipal, de acuerdo con lo establecido en las normas de circulación. c)\tInstruir atestados por accidentes de circulación dentro del término municipal."},{"ref":"Art. 94.3 CMB","law":"Carta municipal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518","quote":"Los actos del Alcalde o Alcaldesa de Barcelona en materia de sanción de infracciones de normas de circulación ponen fin a la vía administrativa."}]}]},{"n":"2","title":"Prioritat de vianants i vehicles","blocks":[{"text":"Els vianants tenen prioritat sobre tot tipus de vehicles, tal com regulen la llei de trànsit i els seus reglaments (art. 10). L''Alcaldia pot establir zones on la circulació de vehicles queda restringida a favor dels vianants.","refs":[{"ref":"Art. 10 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els i les vianants tenen prioritat sobre tot tipus de vehicles tal com queda regulat a la llei de trànsit i els seus reglaments de desenvolupament."},{"ref":"Art. 10 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"L''Alcaldia pot establir zones on les condicions de circulació de vehicles queden restringides a favor de la circulació de vianants."}]},{"text":"En aquestes zones s''estableix una escala de prioritats: les bicicletes, els cicles de més de dues rodes, els vehicles moguts per força muscular i els vehicles de mobilitat personal tenen prioritat sobre la resta de vehicles, però no sobre els vianants (art. 10). El vianant, doncs, sempre queda al capdamunt.","refs":[{"ref":"Art. 10 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"les bicicletes, els cicles de més de dues rodes, els vehicles moguts per força muscular i els vehicles de mobilitat personal gaudeixen de prioritat sobre la resta de vehicles, però no sobre els i les vianants."}]}]},{"n":"3","title":"Velocitats al nucli urbà","blocks":[{"text":"L''article 11 fixa una escala de límits segons el tipus de carrer. A les vies de dos o més carrils per sentit, el màxim és de 50 km/h per a vehicles de tota categoria, i per comptar els carrils no es tenen en compte els reservats a determinats usuaris o al transport públic. Als carrers d''un sol carril per sentit (sense comptar els reservats), el màxim és de 30 km/h.","refs":[{"ref":"Art. 11 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"a aquests efectes els carrils reservats per a la circulació de determinats usuaris o ús exclusiu de transport públic no es comptabilitzen, la velocitat dels vehicles de tota categoria no pot superar els 50 quilòmetres per hora"},{"ref":"Art. 11 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En els carrers on es circuli només per un carril, per sentit, i sense comptabilitzar els carrils reservats, els vehicles no poden circular a més de 30 km/h."}]},{"text":"Als carrers amb plataforma única de calçada i vorera, el límit és de 20 km/h, llevat de senyalització específica. Als carrers sense un espai destinat exclusivament als vianants, el màxim és de 10 km/h i cal prendre precaucions per donar-los preferència. En cas de pluja, obres o paviment deficient, cal adaptar la velocitat com a mesura de precaució (art. 11).","refs":[{"ref":"Art. 11 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En els carrers que disposin de plataforma única de calçada i vorera, els vehicles no poden circular a més de 20 km/h, excepte senyalització específica."},{"ref":"Art. 11 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En els carrers sense un espai destinat exclusivament al trànsit de vianants la velocitat màxima s''estableix en 10 km/h, i els vehicles han de prendre les precaucions necessàries per donar preferència als vianants. En cas de pluja, d''obres, paviment deficient cal adaptar la velocitat com a mesura de precaució."}]},{"text":"Els tres primers límits (50, 30 i 20 km/h) coincideixen amb els límits genèrics en via urbana del Reglament general de circulació, que també exclou del còmput els carrils reservats (art. 50.1 RGC). El de 10 km/h és específic de l''Ordenança.","refs":[{"ref":"Art. 50.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) 20 km/h en vías que dispongan de plataforma única de calzada y acera. b) 30 km/h en vías de un único carril por sentido de circulación. c) 50 km/h en vías de dos o más carriles por sentido de circulación."}]},{"text":"El mateix reglament permet que l''autoritat municipal rebaixi aquests límits genèrics amb senyalització específica i, excepcionalment, que augmenti fins a 50 km/h el de les vies d''un sol carril per sentit, també amb senyalització (art. 50.2 i 50.3 RGC). Per això l''Ordenança parla sempre de límits «llevat de senyalització específica»: el senyal concret preval sobre la regla general.","refs":[{"ref":"Art. 50.2 i 50.3 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Las velocidades genéricas establecidas podrán ser rebajadas previa señalización específica, por la Autoridad municipal. 3. Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica."}]}]},{"n":"4","title":"Sorolls i circulació de vehicles de motor","blocks":[{"text":"Els motors dels vehicles que circulen per les vies urbanes no poden superar els límits de soroll i d''emissió de gasos que fixen les ordenances municipals (art. 12). Els vehicles de motor i els ciclomotors no poden circular per voreres, andanes, passeigs ni pel carril bici (art. 13).","refs":[{"ref":"Art. 12 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els motors dels vehicles que circulen per les vies urbanes no poden superar els límits de soroll i emissió de gasos determinats a les Ordenances municipals."},{"ref":"Art. 13 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els vehicles de motor i ciclomotors no poden circular per voreres, andanes, passeigs i carril-bici."}]},{"text":"La llei de trànsit també permet als municipis restringir la circulació de determinats vehicles a les vies urbanes per motius mediambientals, i tancar vies urbanes quan sigui necessari (art. 7 LTSV).","refs":[{"ref":"Art. 7 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"f) El cierre de vías urbanas cuando sea necesario. g) La restricción de la circulación a determinados vehículos en vías urbanas por motivos medioambientales."}]}]},{"n":"5","title":"Bicicletes i cicles: calçada i vorera","blocks":[{"text":"Les bicicletes, els cicles i les bicicletes amb pedaleig assistit que circulen per la calçada ho han de fer preferentment pel carril més proper a la vorera, i gaudeixen de les prioritats de pas de les normes de trànsit (art. 14).","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"La circulació de bicicletes, cicles i també bicicletes de pedals amb pedaleig assistit per la calçada ha de desenvolupar-se preferentment pel carril més proper a la vorera"}]},{"text":"Per la vorera només poden circular en casos concrets: persones adultes que acompanyen ciclistes menors de 12 anys i zones especialment habilitades. Als carrers sense carril bici ni zona habilitada, també hi poden anar els ciclistes menors de 14 anys (art. 14).","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"persones adultes que acompanyin a ciclistes menors de 12 anys zones especialment habilitades."},{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En el cas de carrers sense carril bici o zona especialment habilitada, les bicicletes, els cicles i les bicicletes de pedals amb pedaleig assistit poden circular per les voreres en els següents casos: ciclistes menors de 14 anys"}]},{"text":"Quan circulen per zones excepcionalment habilitades, han de respectar la preferència dels vianants, evitar circular a menys d''1 metre de les façanes i extremar l''atenció amb les persones que surten dels immobles (art. 14).","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Han de respectar la preferència dels vianants. Han d''evitar circular a menys d''1 metre de les façanes i extremar l''atenció respecte la incorporació de ciutadans/es dels immobles a la vorera."}]}]},{"n":"6","title":"Ocupació de la bicicleta i transport de mercaderies","blocks":[{"text":"Els cicles i les bicicletes no poden anar ocupats per més persones de les que poden transportar per construcció. Tanmateix, si el conductor és major d''edat, pot transportar un menor amb casc homologat en un seient addicional també homologat (art. 14).","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"quan el conductor sigui major d''edat, podrà transportar un menor, amb casc homologat, en seient addicional que haurà d''ésser igualment homologat."}]},{"text":"El transport de mercaderies en bicicleta o cicle només es pot fer per accedir als locals i botigues per a operacions de càrrega i descàrrega o distribució urbana, sense superar els 10 km/h i respectant les restriccions horàries de cada zona i la senyalització (art. 14).","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"El transport de mercaderies es pot realitzar només per accedir als locals i a les botigues per efectuar les operacions de càrrega i de descàrrega o distribució urbana de mercaderies, no superant la velocitat màxima de 10 km/h"}]}]},{"n":"7","title":"Grups de bicicletes d''activitat turística o d''oci","blocks":[{"text":"Quan les bicicletes provenen d''un arrendament amb ànim de lucre per a activitats turístiques o d''oci, els grups tenen límits (art. 14): als carrers d''amplada inferior a 10 metres, màxim 9 persones, que pot acompanyar 1 ciclista acreditat com a assistent per l''empresa; a la resta de carrers, màxim 15 persones, amb fins a 3 assistents acreditats. En tots dos casos els grups no poden fer parades als carrils bici.","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"9 persones als carrers d''amplada inferior als 10 metres. Aquest grup pot ser acompanyat per 1 ciclista acreditat com assistent per la prestadora de l''activitat. Els grups no poden efectuar parades als carrils bici."},{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"15 persones a la resta de carrers del municipi. Aquest grup pot ser acompanyat per 3 ciclistes acreditats com assistents per la prestadora de l''activitat."}]},{"text":"Aquests grups han de circular segons la normativa de bicicletes i cicles i mantenir entre si una distància de més de 50 metres (art. 14). Regla mnemotècnica: 9+1 en carrers estrets, 15+3 en la resta i 50 metres entre grups.","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En les dues situacions anteriors han de circular segons la normativa de les bicicletes i cicles i han de mantenir una distància entre grups de més de 50 metres."}]}]},{"n":"8","title":"Vehicles de mobilitat personal: condicions de la persona conductora","blocks":[{"text":"No es pot circular amb un VMP amb taxes d''alcohol superiors a les reglamentàries ni amb presència de drogues; els conductors menors d''edat no poden superar en cap cas 0 grams per litre d''alcohol en sang ni 0 mil·ligrams per litre en aire espirat. Tampoc es pot circular amb auriculars o cascs connectats a aparells de so.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En cap cas les persones conductores menors d''edat poden circular per les vies urbanes amb una taxa d''alcohol en sang superior a 0 grams per litre o d''alcohol en aire espirat superior a 0 mil·ligrams per litre."},{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"No es permès circular amb auriculars o cascs connectats a aparells receptors o reproductors de so."}]},{"text":"L''edat mínima per circular amb un VMP és de 16 anys. Els menors de 16 anys només poden fer servir vehicles considerats joguines, fora de les zones de circulació i acompanyats i sota la responsabilitat de pares, tutors o altres persones responsables. Nota: l''edat de 16 anys és la de la redacció consolidada vigent consultada el novembre de 2026; cal revisar-ne la vigència abans de l''examen.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"L''edat mínima permesa per circular amb un vehicle de mobilitat personal és de 16 anys. Les persones menors de 16 anys només poden fer ús de vehicles considerats joguines fora de les zones de circulació"}]},{"text":"Els VMP, de transport personal o de mercaderies, són vehicles d''una sola plaça i no poden portar més d''una persona. La persona conductora ha de portar un casc que compleixi alguna certificació apta per a bicicleta, skate o ciclomotor, o un casc homologat per a motocicletes.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els vehicles de mobilitat personal per a transport personal o de mercaderies són vehicles d''una única plaça i no poden anar ocupats per més d''una persona."},{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Les persones conductores d''un vehicle de mobilitat personal estan obligades a fer servir un casc de protecció que compleixi alguna certificació apta per a bicicleta, skate o ciclomotor, o casc homologat per a motocicletes."}]}]},{"n":"9","title":"Vehicles de mobilitat personal: per on poden circular","blocks":[{"text":"Els VMP no poden circular per voreres, zones de vianants ni túnels urbans, llevat dels túnels amb infraestructura específica, com un carril segregat per a VMP, cicles i bicicletes. En canvi, poden circular pel carril de la marxa als carrers de vianants, als carrers sense espai exclusiu per a vianants, als carrers residencials de 20 km/h i als de plataforma única, excepte si una senyalització específica ho prohibeix.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els vehicles de mobilitat personal no poden circular per les voreres, zones de vianants, ni túnels urbans, excepte en els túnels urbans que tinguin una infraestructura especifica com un carril segregat per a VMP, cicles i bicicletes."},{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Els VMP poden circular pel carril de la marxa als carrers de vianants, carrers sense espai destinat exclusivament al trànsit de vianants, carrers residencials de velocitat màxima de 20 km/h i quan tingui plataforma única, excepte senyalització específica que ho prohibeixi."}]}]},{"n":"10","title":"Retirada de vehicles","blocks":[{"text":"L''Ordenança preveu, entre altres supòsits, la retirada del vehicle quan està estacionat en lloc prohibit en una via declarada d''atenció preferent; quan està estacionat a la calçada fora dels llocs permesos; i quan està estacionat en una àrea de vianants fora de les hores permeses, llevat d''estacionaments autoritzats.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Quan estigui estacionat en lloc prohibit en via declarada com d''atenció preferent o, sota altra denominació, d''igual caràcter. Quan estigui estacionat a la calçada, fora dels llocs permesos. Quan estigui estacionat en una àrea de vianants fora de les hores permeses"}]},{"text":"La llei estatal empara aquesta retirada quan el vehicle és un perill, causa pertorbacions greus a la circulació o deteriora un servei públic, quan ocupa carrils reservats o zones de càrrega i descàrrega, o quan obstaculitza la circulació (art. 105.1 LTSV). Les despeses van a càrrec del titular, l''arrendatari o el conductor habitual, i l''Administració ha de comunicar la retirada al titular en vint-i-quatre hores (art. 105.2 i 105.3 LTSV).","refs":[{"ref":"Art. 105.1 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) Siempre que constituya peligro, cause graves perturbaciones a la circulación de vehículos o peatones o deteriore algún servicio o patrimonio público."},{"ref":"Art. 105.3 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"La Administración deberá comunicar la retirada y depósito del vehículo al titular en el plazo de veinticuatro horas."}]},{"text":"Les bicicletes només es poden retirar i portar al dipòsit si estan abandonades o si, lligades, dificulten la circulació de vehicles o persones o danyen el mobiliari urbà (art. 7.c LTSV).","refs":[{"ref":"Art. 7 LTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Las bicicletas sólo podrán ser retiradas y llevadas al correspondiente depósito si están abandonadas o si, estando amarradas, dificultan la circulación de vehículos o personas o dañan el mobiliario urbano."}]}]},{"n":"11","title":"Concurrència d''infraccions","blocks":[{"text":"Fora dels casos que l''Ordenança regula específicament, a qui comet dues o més infraccions se li imposen les sancions corresponents a cadascuna. Cada dia que un vehicle roman estacionat en lloc prohibit constitueix una infracció independent: tres dies, tres infraccions.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"En la resta de casos, als responsables de dues o més infraccions, se''ls imposaran les sancions corresponents a cadascuna de les infraccions comeses. Cada dia que un vehicle romangui estacionat en lloc prohibit causa una infracció independent."}]},{"text":"Nota: la carpeta només conté un extracte de l''Ordenança (arts. 10 a 14, VMP, part de la retirada i de la concurrència d''infraccions); no s''hi poden consultar la resta d''articles (estacionament, càrrega i descàrrega, immobilització o quadre de sancions).","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"Retirada de vehicles (extracte)"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Vianants: prioritat sobre tots els vehicles; a les zones restringides, bicicletes i VMP passen davant de la resta de vehicles, però no dels vianants.","refs":[{"ref":"Art. 10 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"però no sobre els i les vianants"}]},{"text":"Velocitats: 50 km/h (dos o més carrils per sentit, sense comptar els reservats), 30 km/h (un carril), 20 km/h (plataforma única) i 10 km/h (sense espai exclusiu per a vianants).","refs":[{"ref":"Art. 11 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"la velocitat màxima s''estableix en 10 km/h"}]},{"text":"Motos i ciclomotors: mai per voreres, andanes, passeigs ni carril bici.","refs":[{"ref":"Art. 13 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"no poden circular per voreres, andanes, passeigs i carril-bici."}]},{"text":"Bicicleta: carril més proper a la vorera; per la vorera, adults que acompanyen menors de 12 anys i menors de 14 anys sense carril bici; a 1 metre de les façanes com a mínim.","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"ciclistes menors de 14 anys"}]},{"text":"Grups turístics: 9 + 1 assistent (carrers de menys de 10 m), 15 + 3 (la resta) i més de 50 m entre grups.","refs":[{"ref":"Art. 14 ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"més de 50 metres"}]},{"text":"VMP: 16 anys; una plaça; casc; 0,0 d''alcohol per als menors; no per voreres, zones de vianants ni túnels sense carril segregat.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"és de 16 anys"}]},{"text":"Cada dia d''estacionament en lloc prohibit és una infracció independent.","refs":[{"ref":"ORD_CIRC","law":"Ordenança de circulació","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923","quote":"causa una infracció independent"}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923', null, null, null, null
