insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança per la qual es fixen els criteris d''accés, circulació i estacionament de vehicles en la Zona de Baixes Emissions de Barcelona i es promou una mobilitat sense emissions (text vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t19-ordenanca-zbe', 'Tema 19. Ordenança de la Zona de Baixes Emissions de Barcelona') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t19-ordenanca-zbe' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte, finalitat i àmbit de la Zona de Baixes Emissions"},{"n":"2","title":"Restricció d''accés i horari"},{"n":"3","title":"Excepcions, exempcions i autoritzacions"},{"n":"4","title":"Control, senyalització i seguiment"},{"n":"5","title":"Procediment sancionador i sancions"}]'::jsonb, '["Art. 10 Ordenança ZBE: «La mesura establerta a l’apartat 1 és d’aplicació de dilluns a divendres feiners, en horari de 07:00 hores a 20:00 hores.»","Art. 20 Ordenança ZBE: «constitueix una infracció greu, sancionable amb multa de 200 euros, incomplir la prohibició establerta a l’article 10»","Art. 4 Ordenança ZBE: «Aquesta Ordenança s’aplica al terme municipal de Barcelona i als vehicles que hi accedeixin, hi circulin o hi estacionin.»","Art. 3 Ordenança ZBE: «La responsabilitat d’assolir els objectius establerts a l’article 2 correspon tant a l’Ajuntament de Barcelona com a la ciutadania en el seu conjunt.»","Art. 16 Ordenança ZBE: «El control del compliment de les disposicions d’aquesta Ordenança es realitza mitjançant un sistema de lectura de matrícules i la plataforma tecnològica de l’Ajuntament amb mitjans automàtics»","Art. 17 Ordenança ZBE: «mitjançant la senyalització aprovada a l’efecte per la Direcció General de Trànsit»","Art. 20 Ordenança ZBE: «l’import de la multa és de 260 euros»","Art. 19 Ordenança ZBE: «El procediment sancionador d’aquesta Ordenança és l’establert al Text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat vial»","Art. 14 Ordenança ZBE: «Vehicles de serveis d’emergència i essencials.»","Art. 12 Ordenança ZBE: «Amb caràcter excepcional, per raons d’interès general, pot autoritzar-se l’accés a la ZBE, mitjançant resolució motivada de l’alcalde o alcaldessa.»","Art. 13 Ordenança ZBE: «L’Àrea Metropolitana de Barcelona gestiona el Registre metropolità de vehicles estrangers i altres vehicles autoritzats a les zones de baixes emissions»","Art. 15 Ordenança ZBE: «com a màxim 24 hores després del moment que efectivament hagi accedit a la ZBE»","Art. 12 Ordenança ZBE: «comporta l’activació simultània per part de l’òrgan municipal competent del Protocol d’actuació davant d’episodis d’alta contaminació atmosfèrica previst en el Pla bàsic d’emergències municipal»","Art. 11 Ordenança ZBE: «s’estableixen a través de l’Ordenança fiscal relativa a les taxes per estacionament regulat de vehicles a la via pública (AREA)»","Art. 9 Ordenança ZBE: «s’aplica l’Ordenança de circulació de vianants i de vehicles, de 27 de novembre de 1998»","Art. 15 Ordenança ZBE: «en el qual cas es pot tramitar en el termini de tres dies, comptats a partir del mateix dia en què hagi tingut lloc»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte i finalitat de l''Ordenança ZBE","blocks":[{"text":"L''Ordenança per la qual es fixen els criteris d''accés, circulació i estacionament de vehicles en la Zona de Baixes Emissions de Barcelona té per objecte establir aquests criteris a la ZBE definida a l''article 5 i a l''annex 1 (art. 1). També serveix per complir l''article 14 de la Llei 7/2021, de 20 de maig, de canvi climàtic i transició energètica, i la normativa que el desplega. És, per tant, una ordenança de mobilitat amb un fonament ambiental i climàtic.","refs":[{"ref":"Art. 1 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’objecte d’aquesta Ordenança és establir els criteris d’accés, circulació i estacionament de vehicles en la Zona de Baixes Emissions (ZBE) de Barcelona definida a l’article 5 i a l’annex 1."},{"ref":"Art. 1 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L''Ordenança té també per objecte donar compliment a l’article 14 de la Llei 7/2021, de 20 de maig, de canvi climàtic i transició energètica i la normativa que el desenvolupa."}]},{"text":"La finalitat (art. 2) és múltiple: reduir la contaminació ambiental causada per la mobilitat, preservar i millorar la qualitat de l''aire i la salut pública, apropar els nivells de contaminació als que recomana l''Organització Mundial de la Salut (OMS), complir els valors límit legals de qualitat de l''aire, mitigar els impactes del canvi climàtic i vetllar per un millor medi ambient sonor. Observa que també hi apareix el soroll, no només la contaminació atmosfèrica.","refs":[{"ref":"Art. 2 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Aquesta Ordenança té la finalitat de reduir la contaminació ambiental deguda a la mobilitat, preservar i millorar la qualitat de l’aire i la salut pública, apropar els nivells de contaminació de la ciutat als recomanats per l’Organització Mundial de la Salut (OMS), complir els valors límit de qualitat de l’aire legalment establerts, mitigar els impactes del canvi climàtic i vetllar per un millor medi ambient sonor."}]}]},{"n":"2","title":"Corresponsabilitat i qualitat de l''aire com a bé jurídic","blocks":[{"text":"L''article 3 estableix el principi de corresponsabilitat: la responsabilitat d''assolir els objectius de l''article 2 correspon tant a l''Ajuntament de Barcelona com a la ciutadania en el seu conjunt. No és una tasca exclusiva de l''administració.","refs":[{"ref":"Art. 3 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"La responsabilitat d’assolir els objectius establerts a l’article 2 correspon tant a l’Ajuntament de Barcelona com a la ciutadania en el seu conjunt."}]},{"text":"L''Ordenança qualifica la qualitat de l''aire com a bé jurídic protegit (art. 6). L''atmosfera és un bé comú indispensable per a la vida, i totes les persones tenen dret a l''ús i gaudi d''una bona qualitat de l''aire i, alhora, el deure de col·laborar a conservar-la. Drets i deures, doncs, van junts.","refs":[{"ref":"Art. 6 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’atmosfera és un bé comú indispensable per a la vida. Totes les persones tenen el dret a l’ús i gaudi d’una bona qualitat de l’aire, a la vegada que tenen el deure de col·laborar a conservar-la."}]}]},{"n":"3","title":"Àmbit d''aplicació i definicions","blocks":[{"text":"L''àmbit general de l''Ordenança és el terme municipal de Barcelona i els vehicles que hi accedeixen, hi circulen o hi estacionen (art. 4). Però l''àmbit de les mesures de restricció d''accés i circulació és més reduït: la Zona de Baixes Emissions delimitada a l''annex 1 i els vehicles més contaminants que hi accedeixen, hi circulen o hi estacionen. L''àmbit de les restriccions d''estacionament es determina a l''article 11.","refs":[{"ref":"Art. 4 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Aquesta Ordenança s’aplica al terme municipal de Barcelona i als vehicles que hi accedeixin, hi circulin o hi estacionin."},{"ref":"Art. 4 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’àmbit de les mesures relatives a la restricció d’accés i circulació previstes en aquesta Ordenança és la Zona de Baixes Emissions, delimitada a l’annex 1, i als vehicles més contaminants que hi accedeixin, circulin o estacionin."}]},{"text":"L''article 5 defineix la ZBE com l''àmbit territorial delimitat on s''apliquen restriccions d''accés, circulació i estacionament als vehicles més contaminants per millorar la qualitat de l''aire i mitigar els gasos d''efecte hivernacle, d''acord amb la classificació de vehicles pel seu nivell d''emissions del Reglament general de vehicles. Els «vehicles més contaminants» són els que compleixen els requisits de l''annex 2. Els vehicles històrics són els que ho són segons el Reial decret 1247/1995 (Reglament de vehicles històrics), i els clàssics, els que tenen aquesta consideració segons l''article 45 de la Llei 16/2017, de canvi climàtic.","refs":[{"ref":"Art. 5 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"«Zona de Baixes Emissions» o «ZBE»: àmbit territorial delimitat en el qual s’apliquen restriccions d’accés, circulació i estacionament dels vehicles més contaminants per millorar la qualitat de l’aire i mitigar les emissions de gasos d’efecte hivernacle"},{"ref":"Art. 5 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"«Vehicles més contaminants»: els vehicles que compleixen els requisits que es detallen a l’annex 2. «Vehicles històrics»: els vehicles que siguin considerats com a històrics, d’acord amb l’establert al Reial decret 1247/1995, de 14 de juliol"},{"ref":"Art. 5 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"«Vehicles clàssics»: els vehicles que tinguin aquesta consideració de conformitat amb l’article 45 de la Llei 16/2017, de 1 d’agost, de canvi climàtic."}]},{"text":"Nota: la font de la carpeta és un extracte dels articles 1-20 i de les disposicions; no inclou el text dels annexos (delimitació de la ZBE, requisits dels vehicles més contaminants i nombre màxim d''autoritzacions diàries), que s''han de consultar a l''Ordenança completa.","refs":[{"ref":"Encapçalament ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Extracte literal (articles 1-20 i disposicions)."}]}]},{"n":"4","title":"Vigilància de la contaminació i normes de circulació aplicables","blocks":[{"text":"L''Ajuntament, mitjançant la seva participació a l''Agència de Salut Pública de Barcelona, col·labora com a Centre d''Anàlisi en la gestió de la Xarxa de Vigilància i Previsió de la Contaminació Atmosfèrica (XVPCA), adscrita al departament de la Generalitat competent en medi ambient (art. 8). A més, a través de l''Agència d''Energia de Barcelona, fa el seguiment dels nivells d''emissió dels gasos d''efecte hivernacle, de les fonts que hi contribueixen i de la seva evolució.","refs":[{"ref":"Art. 8 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’Ajuntament de Barcelona, mitjançant la seva participació en l’Agència de Salut Pública de Barcelona, col·labora com a Centre d’Anàlisi en la gestió de la Xarxa de Vigilància i Previsió de la Contaminació Atmosfèrica (XVPCA)"},{"ref":"Art. 8 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’Ajuntament de Barcelona, mitjançant l’Agència d’Energia de Barcelona, porta a terme el seguiment i anàlisis dels nivells d’emissió dels diferents gasos d’efecte hivernacle"}]},{"text":"En tot allò que l''Ordenança no reguli sobre mesures generals de circulació, s''aplica l''Ordenança de circulació de vianants i de vehicles, de 27 de novembre de 1998 (tema 16), i la normativa específica corresponent (art. 9).","refs":[{"ref":"Art. 9 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"En tot allò no regulat per aquesta Ordenança, pel que fa a les mesures generals de circulació, s’aplica l’Ordenança de circulació de vianants i de vehicles, de 27 de novembre de 1998, i la normativa específica corresponent."}]}]},{"n":"5","title":"La restricció d''accés i circulació: horari","blocks":[{"text":"La mesura central és la prohibició d''accés i circulació a la ZBE dels vehicles més contaminants, amb l''objectiu de millorar la qualitat de l''aire, mitigar les emissions d''efecte hivernacle i els impactes del canvi climàtic i protegir la salut pública (art. 10). La prohibició s''aplica de dilluns a divendres feiners, de 07:00 a 20:00 hores. Fora d''aquest horari (nits, caps de setmana i festius) la restricció no s''aplica amb caràcter general.","refs":[{"ref":"Art. 10 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"es prohibeix als vehicles més contaminants l’accés i la circulació a la ZBE de Barcelona."},{"ref":"Art. 10 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"La mesura establerta a l’apartat 1 és d’aplicació de dilluns a divendres feiners, en horari de 07:00 hores a 20:00 hores."}]},{"text":"A més, d''acord amb el text refós de la Llei reguladora de les hisendes locals (Reial decret legislatiu 2/2004), l''accés i la circulació a la ZBE es poden subjectar a una taxa en els termes que fixi l''ordenança fiscal corresponent (art. 10).","refs":[{"ref":"Art. 10 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"es podrà subjectar a una taxa l’accés i la circulació de vehicles a la ZBE en els termes que estableixi l’ordenança fiscal corresponent."}]}]},{"n":"6","title":"La restricció de l''estacionament","blocks":[{"text":"Les mesures de restricció de l''estacionament a la ZBE no es regulen directament a l''Ordenança ZBE, sinó a través de l''Ordenança fiscal relativa a les taxes per estacionament regulat de vehicles a la via pública, l''anomenada AREA (art. 11). La finalitat és la mateixa que la de la restricció de circulació: qualitat de l''aire, gasos d''efecte hivernacle, canvi climàtic i salut pública.","refs":[{"ref":"Art. 11 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Les mesures de restricció de l’estacionament a la Zona de Baixes Emissions per a millorar la qualitat de l’aire i mitigar les emissions de gasos d’efecte hivernacle, així com també per mitigar els impactes del canvi climàtic i de protegir la salut pública, s’estableixen a través de l’Ordenança fiscal relativa a les taxes per estacionament regulat de vehicles a la via pública (AREA)"}]}]},{"n":"7","title":"Casos d''excepcionalitat i Registre metropolità","blocks":[{"text":"Quan l''òrgan competent de la Generalitat declara un episodi ambiental de contaminació de l''aire, es produeixen dos efectes simultanis (art. 12): l''òrgan municipal competent activa el Protocol d''actuació davant d''episodis d''alta contaminació atmosfèrica del Pla bàsic d''emergències municipal, i s''adopten les restriccions de trànsit dels vehicles més contaminants fixades per decret d''Alcaldia. Qui declara l''episodi és la Generalitat; qui activa el protocol és l''Ajuntament.","refs":[{"ref":"Art. 12 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"La declaració d’episodi ambiental de contaminació de l’aire per part de l’òrgan competent de la Generalitat de Catalunya comporta l’activació simultània per part de l’òrgan municipal competent del Protocol d’actuació davant d’episodis d’alta contaminació atmosfèrica previst en el Pla bàsic d’emergències municipal, així com també l’adopció de les mesures de restricció del trànsit de vehicles més contaminants establertes per decret d’Alcaldia."}]},{"text":"De manera excepcional i per raons d''interès general, l''alcalde o alcaldessa pot autoritzar l''accés a la ZBE mitjançant resolució motivada (art. 12). El Registre metropolità de vehicles estrangers i altres vehicles autoritzats a les zones de baixes emissions el gestiona l''Àrea Metropolitana de Barcelona (AMB), d''acord amb el reglament aprovat el 21 de maig de 2019 i modificat el 29 de setembre de 2020 (art. 13). No el gestiona ni l''Ajuntament ni la DGT.","refs":[{"ref":"Art. 12 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Amb caràcter excepcional, per raons d’interès general, pot autoritzar-se l’accés a la ZBE, mitjançant resolució motivada de l’alcalde o alcaldessa."},{"ref":"Art. 13 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’Àrea Metropolitana de Barcelona gestiona el Registre metropolità de vehicles estrangers i altres vehicles autoritzats a les zones de baixes emissions, d’acord amb el Reglament aprovat el 21 de maig de 2019, modificat el 29 de setembre de 2020."}]}]},{"n":"8","title":"Exempcions","blocks":[{"text":"D''acord amb l''article 4 del Reglament del Registre metropolità, no queden afectats per la restricció de l''article 10 els vehicles més contaminants que pertanyin a alguna d''aquestes categories (art. 14): vehicles dedicats al transport de persones amb mobilitat reduïda (VPMR); vehicles de serveis d''emergència i essencials; vehicles que transporten persones amb malalties o discapacitats que els condicionen l''ús del transport públic; i vehicles amb matrícula estrangera que compleixen requisits tecnològics i d''emissions equivalents als distintius ambientals que permeten l''accés i que no estan identificats a la base de dades de la DGT.","refs":[{"ref":"Art. 14 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Vehicles dedicats al transport de Persones amb Mobilitat Reduïda (VPMR). Vehicles de serveis d’emergència i essencials. Vehicles dedicats al transport de persones amb malalties o discapacitats que els condicionen l’ús del transport públic."},{"ref":"Art. 14 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Vehicles amb matrícula estrangera que compleixen els requisits tecnològics i d’emissions equivalents als distintius ambientals que emparen l’accés a la ZBE i que no estiguin identificats a la base de dades de la Direcció General de Trànsit."}]},{"text":"La llista és tancada: no hi figuren, per exemple, els vehicles de lloguer turístic ni els de repartiment en general. Les exempcions s''apliquen de manera automàtica per pertànyer a la categoria; les autoritzacions de l''article 15, en canvi, s''han de sol·licitar.","refs":[{"ref":"Art. 14 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"no estan afectats per la restricció d’accés i circulació establerta a l’article 10 els vehicles més contaminants que pertanyin a alguna de les categories següents:"}]}]},{"n":"9","title":"Autoritzacions d''accés i circulació","blocks":[{"text":"L''article 15 regula diverses autoritzacions. Es pot obtenir una autorització diària per accedir i circular de forma esporàdica dins la ZBE, que inclou l''accés esporàdic dels vehicles clàssics i històrics; l''annex 3 fixa el nombre màxim anual d''autoritzacions diàries. També es preveuen autoritzacions per als vehicles que transporten persones diagnosticades de malalties que requereixen tractaments mèdics periòdics, i per a qui li falten com a màxim 5 anys de cotització per arribar a l''edat legal de jubilació.","refs":[{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Poden obtenir una autorització diària per accedir i circular de forma esporàdica dins la ZBE: (i) Vehicles que accedeixin o circulin esporàdicament dins la ZBE. En aquesta categoria s’hi inclouen l’accés i circulació esporàdica a la ZBE dels vehicles considerats com a clàssics i històrics."},{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"(iii) Vehicles que transportin persones diagnosticades de malalties que requereixin realitzar tractaments mèdics de forma periòdica."},{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Que li manquen com a màxim 5 anys de cotització en el Règim Especial de Treballadors Autònoms (RETA), en el Règim General de la Seguretat Social, o en un altre règim alternatiu, per assolir l''edat legal de jubilació"}]},{"text":"Hi ha una autorització per ingressos: per als vehicles els titulars dels quals acreditin ingressos anuals globals inferiors a dues vegades l''IPREM, incrementat segons els membres de la unitat familiar. La taula és: 1 persona, 2 vegades; 2 persones, 2,5; 3 persones, 2,9; 4 persones, 3,3; 5 persones, 3,7; 6 o més, 4. La unitat familiar la formen la persona sol·licitant, el cònjuge o la persona amb qui mantingui una relació anàloga d''afectivitat, i les persones menors de 25 anys. Aquesta autorització dura 1 any des de la comunicació i es pot renovar anualment.","refs":[{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"inferiors a dues vegades l’indicador Públic de Renda d’Efectes Múltiples (IPREM), incrementat segons el nombre de membres de la unitat familiar"},{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Unitat familiar IPREM: 1 persona 2; 2 persones 2,5; 3 persones 2,9; 4 persones 3,3; 5 persones 3,7; 6 persones o més 4"},{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"s’entén per unitat familiar la formada per la persona sol·licitant, el cònjuge o la persona amb la qual mantingui una relació anàloga d’afectivitat i les persones menors de 25 anys. Aquesta autorització té una vigència d’1 any a comptar des del moment de la seva data de comunicació, i es pot renovar anualment."}]},{"text":"Termini de tramitació: la persona titular del vehicle ha de tramitar l''autorització davant el Registre metropolità com a màxim 24 hores després d''haver accedit efectivament a la ZBE. Si l''accés ha estat motivat per una urgència mèdica degudament acreditada, el termini és de tres dies, comptats des del mateix dia de l''accés (art. 15).","refs":[{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"com a màxim 24 hores després del moment que efectivament hagi accedit a la ZBE, llevat que l’accés hagi estat motivat per una urgència mèdica degudament acreditada, en el qual cas es pot tramitar en el termini de tres dies, comptats a partir del mateix dia en què hagi tingut lloc."}]},{"text":"L''autorització vinculada a la proximitat a la jubilació té un règim transitori (DT 1a): el termini de cinc anys comença el 31 de març de 2023; l''autorització dura un any i es pot renovar anualment per un màxim de 5 anys i, com a màxim, fins al 31 de març de 2028. S''extingeix en tot cas quan la persona titular es jubila. Nota: l''extracte de l''article 15 apareix fragmentat a la font i no permet reconstruir tota l''estructura de lletres i números de l''article; convé contrastar-lo amb el text complet.","refs":[{"ref":"DT 1a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"El termini de cinc anys al qual es refereix l’article 15.1.c.i per obtenir l’autorització d’accés i circulació a la Zona de Baixes Emissions, s’inicia a partir del 31 de març de 2023."},{"ref":"DT 1a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"es pot renovar anualment per un període màxim de 5 anys, i com a màxim, fins al 31 de març de 2028. En tot cas, aquesta autorització s’extingeix en el moment en què es produeixi la jubilació de la persona titular del vehicle"}]}]},{"n":"10","title":"Control, senyalització i seguiment","blocks":[{"text":"El compliment es controla mitjançant un sistema de lectura de matrícules i la plataforma tecnològica de l''Ajuntament, amb mitjans automàtics (art. 16). Això s''entén sens perjudici de les facultats assignades a la Guàrdia Urbana i del compliment de la normativa sobre captura i ús d''imatges i protecció de dades personals (vegeu els temes 25 i 26).","refs":[{"ref":"Art. 16 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"El control del compliment de les disposicions d’aquesta Ordenança es realitza mitjançant un sistema de lectura de matrícules i la plataforma tecnològica de l’Ajuntament amb mitjans automàtics, sens perjudici de les facultats que la Guàrdia Urbana tingui assignades i del compliment de la normativa vigent en matèria de captura i ús d’imatges i de protecció de dades de caràcter personal."}]},{"text":"L''accés a la ZBE s''ha de senyalitzar de manera clara i reconeixible amb la senyalització aprovada a l''efecte per la Direcció General de Trànsit (art. 17). El sistema de monitorització i seguiment ha d''incloure, com a mínim, els indicadors del Reial decret 1052/2022, de 27 de desembre, regulador de les zones de baixes emissions, i s''han de publicar anualment al web municipal (art. 18).","refs":[{"ref":"Art. 17 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"L’accés a la Zona de Baixes Emissions de Barcelona s’ha de senyalitzar de manera clara i reconeixible mitjançant la senyalització aprovada a l’efecte per la Direcció General de Trànsit."},{"ref":"Art. 18 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"El sistema de monitorització i seguiment ha d’incloure com a mínim els indicadors definits al Reial decret 1052/2022, de 27 de desembre, regulador de les zones de baixes emissions, i es publicaran anualment a la web municipal."}]}]},{"n":"11","title":"Procediment sancionador, infraccions i sancions","blocks":[{"text":"El procediment sancionador és el del text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat vial, aprovat pel Reial decret legislatiu 6/2015 (art. 19). Per tant, no s''aplica un procediment sancionador municipal propi sinó el de trànsit (tema 34).","refs":[{"ref":"Art. 19 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"El procediment sancionador d’aquesta Ordenança és l’establert al Text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat vial, aprovat pel Reial decret legislatiu 6/2015, de 30 d’octubre."}]},{"text":"D''acord amb els articles 76.z.3 i 80.1 d''aquest text refós, incomplir la prohibició de l''article 10 és infracció greu sancionable amb multa de 200 euros (art. 20). Si la infracció es comet mentre hi ha declarat per la Generalitat un episodi de contaminació de l''aire, la multa és de 260 euros, en aplicació de l''article 81 del text refós, per la major gravetat i transcendència del fet. Els ingressos de les sancions es destinen a finançar actuacions per impulsar la mobilitat sostenible.","refs":[{"ref":"Art. 20 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"constitueix una infracció greu, sancionable amb multa de 200 euros, incomplir la prohibició establerta a l’article 10."},{"ref":"Art. 20 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"l’import de la multa és de 260 euros, en aplicació de l’article 81 del mateix Text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat vial, atesa la major gravetat i transcendència del fet infractor"},{"ref":"Art. 20 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Els ingressos obtinguts per les sancions establertes en aquesta Ordenança es destinen a finançar actuacions orientades a impulsar la mobilitat sostenible."}]}]},{"n":"12","title":"Derogació, modificació dels annexos i entrada en vigor","blocks":[{"text":"L''Ordenança deroga l''Ordenança relativa a la restricció de la circulació de determinats vehicles a la ciutat de Barcelona per preservar i millorar la qualitat de l''aire, aprovada el 20 de desembre de 2019 i publicada al BOPB el 31 de desembre de 2019 (disposició derogatòria única).","refs":[{"ref":"Disposició derogatòria única ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Es deroga l’Ordenança relativa a la restricció de la circulació de determinats vehicles a la ciutat de Barcelona amb l''objectiu de preservar i millorar la qualitat de l''aire, aprovada en data 20 de desembre de 2019"}]},{"text":"Els annexos es poden modificar per decret d''Alcaldia, però aquest decret ha de passar per aprovació inicial, informació pública durant un mínim de trenta dies, aprovació definitiva i publicació al Butlletí Oficial de la Província de Barcelona (DF 2a). L''Ordenança va entrar en vigor l''endemà de la seva publicació al BOPB (DF 3a).","refs":[{"ref":"DF 2a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Els annexos d’aquesta Ordenança poden ser modificats per decret d’Alcaldia."},{"ref":"DF 2a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"ha de ser objecte d’aprovació inicial, d’informació pública per un període mínim de trenta dies, d’aprovació definitiva i de publicació al «Butlletí Oficial de la Província de Barcelona»."},{"ref":"DF 3a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Aquesta Ordenança entra en vigor l’endemà de la seva publicació en el Butlletí Oficial de la Província de Barcelona."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Horari de la restricció: dilluns a divendres feiners, de 07:00 a 20:00 (art. 10).","refs":[{"ref":"Art. 10 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"de dilluns a divendres feiners, en horari de 07:00 hores a 20:00 hores."}]},{"text":"Multa: 200 € (greu); 260 € si hi ha episodi de contaminació declarat per la Generalitat (art. 20).","refs":[{"ref":"Art. 20 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"l’import de la multa és de 260 euros"}]},{"text":"Procediment sancionador: el de l''RDL 6/2015 de trànsit (art. 19).","refs":[{"ref":"Art. 19 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"aprovat pel Reial decret legislatiu 6/2015, de 30 d’octubre."}]},{"text":"Corresponsabilitat: Ajuntament i ciutadania en el seu conjunt (art. 3).","refs":[{"ref":"Art. 3 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"correspon tant a l’Ajuntament de Barcelona com a la ciutadania en el seu conjunt."}]},{"text":"Control per lectura de matrícules i plataforma municipal automàtica; senyalització aprovada per la DGT (arts. 16 i 17).","refs":[{"ref":"Art. 16 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"mitjançant un sistema de lectura de matrícules i la plataforma tecnològica de l’Ajuntament amb mitjans automàtics"}]},{"text":"Registre metropolità: el gestiona l''AMB; tràmit en 24 hores (urgència mèdica: tres dies) (arts. 13 i 15).","refs":[{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"com a màxim 24 hores després del moment que efectivament hagi accedit a la ZBE"}]},{"text":"Autorització excepcional per interès general: resolució motivada de l''alcalde o alcaldessa (art. 12).","refs":[{"ref":"Art. 12 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"mitjançant resolució motivada de l’alcalde o alcaldessa."}]},{"text":"Estacionament: es regula a l''Ordenança fiscal AREA (art. 11).","refs":[{"ref":"Art. 11 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"s’estableixen a través de l’Ordenança fiscal relativa a les taxes per estacionament regulat de vehicles a la via pública (AREA)"}]},{"text":"Autorització per ingressos: menys de 2 vegades l''IPREM per a 1 persona; unitat familiar amb menors de 25 anys (art. 15).","refs":[{"ref":"Art. 15 ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"Unitat familiar IPREM: 1 persona 2; 2 persones 2,5"}]},{"text":"Jubilació: renovable fins al 31 de març de 2028; annexos modificables amb informació pública de 30 dies (DT 1a i DF 2a).","refs":[{"ref":"DT 1a ORD_ZBE","law":"Ordenança ZBE","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402","quote":"i com a màxim, fins al 31 de març de 2028."}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402', null, null, null, null
