insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La seguretat pública com a competència de l''Estat"},{"n":"2","title":"Forces i cossos de seguretat: classes i naturalesa"},{"n":"3","title":"Principis bàsics d''actuació (art. 5)"},{"n":"4","title":"Funcions de les FCSE i policia judicial"},{"n":"5","title":"Policies locals: àmbit, funcions i juntes locals de seguretat"}]'::jsonb, '["Art. 1 LO 2/1986: «La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.»","Art. 2 LO 2/1986: «c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.»","Art. 7 LO 2/1986: «tendrán a todos los efectos legales el carácter de agentes de la autoridad»","Art. 52 LO 2/1986: «Los Cuerpos de Policía Local son Institutos armados, de naturaleza civil con estructura y organización jerarquizada»","Art. 53 LO 2/1986: «c) Instruir atestados por accidentes de circulación dentro del casco urbano.»","Art. 9 LO 2/1986: «El Cuerpo Nacional de Policía, que es un Instituto Armado de naturaleza civil, dependiente del Ministro del Interior.»","Art. 5 LO 2/1986: «Solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas»","Art. 5 LO 2/1986: «rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance»","Art. 5 LO 2/1986: «debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana»","Art. 5 LO 2/1986: «En ningún caso, la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes.»","Art. 51 LO 2/1986: «Dichos cuerpos sólo podrán actuar en el ámbito territorial del municipio respectivo, salvo en situaciones de emergencia y previo requerimiento de las autoridades competentes.»","Art. 53 LO 2/1986: «e) Participar en las funciones de Policía Judicial, en la forma establecida en el artículo 29.2 de esta Ley.»","Art. 54 LO 2/1986: «La presidencia corresponderá al Alcalde, salvo que concurriera a sus sesiones el Gobernador civil de la provincia, en cuyo caso, la presidencia será compartida con éste.»","Art. 53 LO 2/1986: «i) Cooperar en la resolución de los conflictos privados cuando sean requeridos para ello.»","Art. 4 LO 2/1986: «tienen especial obligación de auxiliar o colaborar en todo momento con las Fuerzas y Cuerpos de Seguridad»","Art. 53 LO 2/1986: «Las actuaciones que practiquen los Cuerpos de Policía Local en el ejercicio de las funciones previstas en los apartados c) y g) precedentes deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado competentes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La seguretat pública: competència de l''Estat i participació de les altres administracions","blocks":[{"text":"La Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat (LOFCS) parteix d''una afirmació clara: la seguretat pública és competència exclusiva de l''Estat i el seu manteniment correspon al Govern de la Nació (art. 1.1). Ara bé, no és un monopoli absolut: les comunitats autònomes hi participen en els termes dels seus estatuts i d''aquesta llei, i les corporacions locals, en els termes de la Llei reguladora de les bases del règim local i d''aquesta llei (art. 1.2 i 1.3). El manteniment de la seguretat pública l''exerceixen les diferents administracions a través de les forces i cossos de seguretat (art. 1.4).","refs":[{"ref":"Art. 1.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación."},{"ref":"Art. 1.2 i 1.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las Comunidades Autónomas participarán en el mantenimiento de la Seguridad Pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley. 3. Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local y en el marco de esta Ley."},{"ref":"Art. 1.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"El mantenimiento de la Seguridad Pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad."}]},{"text":"Per a Catalunya, la disposició final segona fixa que la Policia Autonòmica (Mossos d''Esquadra) es regeix pel seu Estatut d''autonomia i les normes que el despleguen, i la LOFCS hi té caràcter supletori. Tanmateix, hi són d''aplicació directa els articles 5, 6, 7 i 8 (principis i disposicions estatutàries comunes) i els articles 38, 43 i 46. La coordinació amb les FCSE a Catalunya es fa a través de la Junta de Seguretat.","refs":[{"ref":"DF 2a.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Policía Autónoma de Cataluña se rige por su Estatuto de Autonomía y normas que lo desarrollen, respecto a las que la presente Ley tendrá carácter supletorio"},{"ref":"DF 2a.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"serán de aplicación directa al régimen de la Policía Autónoma de Cataluña, los artículos 5, 6, 7 y 8 de esta Ley"}]}]},{"n":"2","title":"Forces i cossos de seguretat: classes, cooperació i deure d''auxili","blocks":[{"text":"Són forces i cossos de seguretat (art. 2): a) les Forces i Cossos de Seguretat de l''Estat, que depenen del Govern de la Nació; b) els cossos de policia de les comunitats autònomes; i c) els cossos de policia de les corporacions locals. La Guàrdia Urbana de Barcelona, doncs, és un cos de seguretat del grup c). Els membres de tots aquests cossos han d''ajustar la seva actuació al principi de cooperació recíproca, i la coordinació es fa pels òrgans que crea la llei (art. 3).","refs":[{"ref":"Art. 2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales."},{"ref":"Art. 3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los miembros de las Fuerzas y Cuerpos de Seguridad ajustarán su actuación al principio de cooperación recíproca y su coordinación se efectuará a través de los órganos que a tal efecto establece esta Ley."}]},{"text":"Tothom té el deure de prestar a les forces i cossos de seguretat l''auxili necessari en la investigació i persecució dels delictes en els termes legals (art. 4.1). Però les persones i entitats que exerceixen funcions de vigilància, seguretat o custòdia de persones, béns o serveis, públics o privats (per exemple, la seguretat privada), tenen una obligació especial d''auxiliar-los o col·laborar-hi en tot moment (art. 4.2).","refs":[{"ref":"Art. 4.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Todos tienen el deber de prestar a las Fuerzas y Cuerpos de Seguridad el auxilio necesario en la investigación y persecución de los delitos en los términos previstos legalmente."},{"ref":"Art. 4.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas a personal y bienes o servicios de titularidad pública o privada tienen especial obligación de auxiliar o colaborar en todo momento con las Fuerzas y Cuerpos de Seguridad."}]}]},{"n":"3","title":"Principis bàsics d''actuació (I): adequació a l''ordenament i obediència deguda","blocks":[{"text":"L''article 5 és el més preguntat de la llei. El primer bloc de principis és l''adequació a l''ordenament jurídic: exercir la funció amb absolut respecte a la Constitució i a la resta de l''ordenament; actuar amb absoluta neutralitat política i imparcialitat, sense cap discriminació per raó de raça, religió o opinió; actuar amb integritat i dignitat, abstenint-se de tot acte de corrupció i oposant-s''hi resoltament; subjectar-se als principis de jerarquia i subordinació; i col·laborar amb l''Administració de Justícia.","refs":[{"ref":"Art. 5.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Ejercer su función con absoluto respeto a la Constitución y al resto del ordenamiento jurídico. b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de raza, religión u opinión. c) Actuar con integridad y dignidad. En particular, deberán abstenerse de todo acto de corrupción y oponerse a él resueltamente."},{"ref":"Art. 5.1.e LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"e) Colaborar con la Administración de Justicia y auxiliarla en los términos establecidos en la Ley."}]},{"text":"La jerarquia té un límit: en cap cas l''obediència deguda no pot emparar ordres que impliquin executar actes que manifestament constitueixin delicte o siguin contraris a la Constitució o a les lleis (art. 5.1.d). L''agent no pot escudar-se en una ordre superior per cometre un delicte evident.","refs":[{"ref":"Art. 5.1.d LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"d) Sujetarse en su actuación profesional, a los principios de jerarquía y subordinación. En ningún caso, la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes."}]}]},{"n":"4","title":"Principis bàsics d''actuació (II): relacions amb la comunitat i ús de les armes","blocks":[{"text":"En les relacions amb la comunitat, els agents han d''impedir qualsevol pràctica abusiva, arbitrària o discriminatòria que impliqui violència física o moral; han de tenir un tracte correcte i acurat amb els ciutadans, auxiliar-los i protegir-los quan les circumstàncies ho aconsellin o se''ls requereixi; i en totes les intervencions han de donar informació completa i tan àmplia com sigui possible sobre les causes i la finalitat (art. 5.2.a i b).","refs":[{"ref":"Art. 5.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Impedir, en el ejercicio de su actuación profesional, cualquier práctica abusiva, arbitraria o discriminatoria que entrañe violencia física o moral."},{"ref":"Art. 5.2.b LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En todas sus intervenciones, proporcionarán información cumplida, y tan amplia como sea posible, sobre las causas y finalidad de las mismas."}]},{"text":"Han d''actuar amb la decisió necessària i sense demora quan d''això depengui evitar un dany greu, immediat i irreparable, i ho han de fer d''acord amb els principis de congruència, oportunitat i proporcionalitat en la utilització dels mitjans al seu abast (art. 5.2.c). Només han d''utilitzar les armes quan hi hagi un risc racionalment greu per a la seva vida, la seva integritat física o la de terceres persones, o en circumstàncies que puguin suposar un greu risc per a la seguretat ciutadana, i sempre d''acord amb aquests mateixos principis (art. 5.2.d).","refs":[{"ref":"Art. 5.2.c LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"deberán actuar con la decisión necesaria, y sin demora cuando de ello dependa evitar un daño grave, inmediato e irreparable; rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance."},{"ref":"Art. 5.2.d LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana"}]}]},{"n":"5","title":"Principis bàsics d''actuació (III): detinguts, dedicació, secret i responsabilitat","blocks":[{"text":"Pel que fa al tractament de detinguts (art. 5.3), els agents s''han d''identificar degudament com a tals en el moment de fer una detenció; han de vetllar per la vida i la integritat física de les persones detingudes o sota la seva custòdia i respectar-ne l''honor i la dignitat; i han de complir amb diligència els tràmits, terminis i requisits que exigeix l''ordenament quan detenen una persona.","refs":[{"ref":"Art. 5.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención. b) Velarán por la vida e integridad física de las personas a quienes detuvieren o que se encuentren bajo su custodia y respetarán el honor y la dignidad de las personas."}]},{"text":"Dedicació professional: han d''exercir les funcions amb total dedicació i han d''intervenir sempre, en qualsevol temps i lloc, estiguin o no de servei, en defensa de la llei i de la seguretat ciutadana (art. 5.4). Secret professional: han de guardar rigorós secret de tota la informació que coneguin per raó o amb ocasió de les seves funcions, i no estan obligats a revelar les fonts d''informació, llevat que l''exercici de les funcions o la llei els imposin actuar d''una altra manera (art. 5.5).","refs":[{"ref":"Art. 5.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana."},{"ref":"Art. 5.5 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Deberán guardar riguroso secreto respecto a todas las informaciones que conozcan por razón o con ocasión del desempeño de sus funciones. No estarán obligados a revelar las fuentes de información salvo que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera."}]},{"text":"Responsabilitat: els agents són responsables personalment i directament dels actes que facin en la seva actuació professional infringint les normes legals o reglamentàries o els principis anteriors, sens perjudici de la responsabilitat patrimonial que pugui correspondre a l''administració (art. 5.6).","refs":[{"ref":"Art. 5.6 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Son responsables personal y directamente por los actos que en su actuación profesional llevaren a cabo, infringiendo o vulnerando las normas legales, así como las reglamentarias que rijan su profesión y los principios enunciados anteriormente, sin perjuicio de la responsabilidad patrimonial que pueda corresponder a las Administraciones Públicas por las mismas."}]}]},{"n":"6","title":"Disposicions estatutàries comunes: condició d''agent de l''autoritat i jurisdicció","blocks":[{"text":"L''article 6 recull les disposicions estatutàries comunes: la formació ha de ser professional i permanent; els agents han de jurar o prometre acatament a la Constitució; tenen dret a una remuneració justa; la pertinença al cos és incompatible amb qualsevol altra activitat pública o privada, llevat de les exceptuades; i no poden exercir en cap cas el dret de vaga ni accions substitutives o concertades per alterar el funcionament normal dels serveis.","refs":[{"ref":"Art. 6.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los miembros de las Fuerzas y Cuerpos de Seguridad deberán jurar o prometer acatamiento a la Constitución como norma fundamental del Estado."},{"ref":"Art. 6.8 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los miembros de las Fuerzas y Cuerpos de Seguridad no podrán ejercer en ningún caso el derecho de huelga, ni acciones sustitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios."}]},{"text":"En l''exercici de les funcions, els membres de les forces i cossos de seguretat tenen a tots els efectes legals el caràcter d''agents de l''autoritat (art. 7.1). Però quan es comet un delicte d''atemptat emprant armes de foc, explosius o altres mitjans d''agressió d''anàloga perillositat que puguin posar en perill greu la seva integritat física, tenen la consideració d''autoritat a l''efecte de la seva protecció penal (art. 7.2). La jurisdicció ordinària és la competent per als delictes comesos contra ells i per ells en l''exercici de les funcions (art. 8.1).","refs":[{"ref":"Art. 7.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En el ejercicio de sus funciones, los miembros de las Fuerzas y Cuerpos de Seguridad tendrán a todos los efectos legales el carácter de agentes de la autoridad."},{"ref":"Art. 7.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Cuando se cometa delito de atentado, empleando en su ejecución armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad, que puedan poner en peligro grave la integridad física de los miembros de las Fuerzas y Cuerpos de Seguridad, tendrán al efecto de su protección penal la consideración de autoridad."},{"ref":"Art. 8.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La jurisdicción ordinaria será la competente para conocer de los delitos que se cometan contra miembros de las Fuerzas y Cuerpos de Seguridad, así como de los cometidos por éstos en el ejercicio de sus funciones."}]}]},{"n":"7","title":"Forces i Cossos de Seguretat de l''Estat: composició i funcions","blocks":[{"text":"Les FCSE exerceixen les funcions a tot el territori nacional i les integren (art. 9): el Cos Nacional de Policia, institut armat de naturalesa civil dependent del ministre de l''Interior; i la Guàrdia Civil, institut armat de naturalesa militar, que depèn del ministre de l''Interior en les funcions d''aquesta llei i del de Defensa en les missions militars. En temps de guerra i durant l''estat de setge, la Guàrdia Civil depèn exclusivament del ministre de Defensa.","refs":[{"ref":"Art. 9 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) El Cuerpo Nacional de Policía, que es un Instituto Armado de naturaleza civil, dependiente del Ministro del Interior."},{"ref":"Art. 9 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"b) La Guardia Civil, que es un Instituto Armado de naturaleza militar, dependiente del Ministro del Interior, en el desempeño de las funciones que esta Ley le atribuye, y del Ministro de Defensa en el cumplimiento de las misiones de carácter militar que éste o el Gobierno le encomienden. En tiempo de guerra y durante el estado de sitio, dependerá exclusivamente del Ministro de Defensa."}]},{"text":"La seva missió és protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana (art. 11.1), amb funcions com vetllar pel compliment de les lleis, auxiliar i protegir les persones i els béns, mantenir i restablir l''ordre, prevenir delictes i investigar-los per descobrir i detenir els presumptes culpables. Territorialment, el Cos Nacional de Policia actua a les capitals de província i als municipis i nuclis que determini el Govern, i la Guàrdia Civil a la resta del territori i al mar territorial (art. 11.2).","refs":[{"ref":"Art. 11.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las Fuerzas y Cuerpos de Seguridad del Estado tienen como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana"},{"ref":"Art. 11.1.g LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"g) Investigar los delitos para descubrir y detener a los presuntos culpables, asegurar los instrumentos, efectos y pruebas del delito"},{"ref":"Art. 11.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Corresponde al Cuerpo Nacional de Policía ejercitar dichas funciones en las capitales de provincia y en los términos municipales y núcleos urbanos que el Gobierno determine. b) La Guardia Civil las ejercerá en el resto del territorio nacional y su mar territorial."}]}]},{"n":"8","title":"La policia judicial","blocks":[{"text":"Les funcions de policia judicial de l''article 126 de la Constitució les exerceixen les FCSE a través de les unitats de policia judicial (art. 29.1). Per complir aquesta funció, el personal de les policies autonòmiques i de les corporacions locals té caràcter col·laborador de les FCSE (art. 29.2). Per això, entre les funcions de la policia local figura «participar en les funcions de policia judicial en la forma establerta a l''article 29.2».","refs":[{"ref":"Art. 29.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las funciones de Policía Judicial que se mencionan en el artículo 126 de la Constitución serán ejercidas por las Fuerzas y Cuerpos de Seguridad del Estado, a través de las Unidades que se regulan en el presente capítulo."},{"ref":"Art. 29.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Para el cumplimiento de dicha función tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado el personal de Policía de las Comunidades Autónomas y de las Corporaciones Locales."}]},{"text":"Els funcionaris adscrits a unitats de policia judicial depenen orgànicament del Ministeri de l''Interior i funcionalment dels jutges, tribunals o Ministeri Fiscal que coneguin de l''assumpte (art. 31.1). No poden ser apartats de la investigació encomanada fins que acabi, si no és per decisió o amb autorització del jutge o fiscal competent (art. 34.1).","refs":[{"ref":"Art. 31.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"dependen orgánicamente del Ministerio del Interior y funcionalmente de los Jueces, Tribunales o Ministerio Fiscal que estén conociendo del asunto objeto de su investigación."},{"ref":"Art. 34.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"no podrán ser removidos o apartados de la investigación concreta que se les hubiera encomendado, hasta que finalice la misma o la fase del procedimiento judicial que la originara, si no es por decisión o con la autorización del Juez o Fiscal competente."}]}]},{"n":"9","title":"Policies de les comunitats autònomes i coordinació de les policies locals","blocks":[{"text":"Les policies autonòmiques són instituts armats de naturalesa civil, amb estructura i organització jerarquitzada (art. 41.2), i només poden actuar dins el territori de la seva comunitat, llevat de situacions d''emergència i amb requeriment previ de les autoritats estatals (art. 42). Correspon a les comunitats autònomes coordinar l''actuació de les policies locals al seu territori (art. 39): fixar les normes marc dels reglaments de policia local, homogeneïtzar mitjans tècnics, uniformes i retribucions, fixar els criteris de selecció, formació, promoció i mobilitat, i coordinar-ne la formació professional.","refs":[{"ref":"Art. 41.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los Cuerpos de Policía de las Comunidades Autónomas son Institutos armados de naturaleza civil, con estructura y organización jerarquizada."},{"ref":"Art. 39 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Corresponde a las Comunidades Autónomas, de conformidad con la presente Ley y con la de Bases de Régimen Local, coordinar la actuación de las Policías Locales en el ámbito territorial de la Comunidad"},{"ref":"Art. 39.c LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"c) Fijar los criterios de selección, formación, promoción y movilidad de las Policías Locales, determinando los distintos niveles educativos exigibles para cada categoría, sin que, en ningún caso, el nivel pueda ser inferior a graduado escolar."}]},{"text":"Com a òrgans de coordinació, la llei crea el Consell de Política de Seguretat, presidit pel ministre de l''Interior i integrat pels consellers d''Interior o Governació de les comunitats autònomes i per un nombre igual de representants de l''Estat (art. 48). A les comunitats amb policia pròpia es pot constituir una Junta de Seguretat paritària (art. 50).","refs":[{"ref":"Art. 48.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"se crea el Consejo de Política de Seguridad, que estará presidido por el Ministro del Interior e integrado por los Consejeros de Interior o Gobernación de las Comunidades Autónomas y por un número igual de representantes del Estado designados por el Gobierno de la Nación."},{"ref":"Art. 50.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En las Comunidades Autónomas que dispongan de Cuerpos de Policía propios podrá constituirse una Junta de Seguridad, integrada por igual número de representantes del Estado y de las Comunidades Autónomas"}]}]},{"n":"10","title":"Les policies locals: creació, naturalesa i àmbit territorial","blocks":[{"text":"Els municipis poden crear cossos de policia propis d''acord amb la LOFCS, la LBRL i la legislació autonòmica (art. 51.1). Als municipis on no hi ha policia municipal, les seves comeses les exerceix el personal que fa funcions de custòdia i vigilància de béns, serveis i instal·lacions, amb la denominació de guardes, vigilants, agents, agutzils o anàlogues (art. 51.2).","refs":[{"ref":"Art. 51.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los municipios podrán crear cuerpos de policía propios, de acuerdo con lo previsto en la presente ley, en la Ley de Bases de Régimen Local y en la legislación autonómica."},{"ref":"Art. 51.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En los municipios donde no exista policía municipal, los cometidos de ésta serán ejercidos por el personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones, con la denominación de guardas, vigilantes, agentes, alguaciles o análogos."}]},{"text":"Les policies locals només poden actuar en l''àmbit territorial del seu municipi, llevat de situacions d''emergència i amb requeriment previ de les autoritats competents (art. 51.3). Quan protegeixen autoritats de les corporacions locals poden actuar fora del terme, amb autorització del Ministeri de l''Interior o de l''autoritat de la comunitat autònoma amb policia pròpia. Són instituts armats, de naturalesa civil, amb estructura i organització jerarquitzada (art. 52.1). Si diversos municipis limítrofs no tenen recursos suficients, es poden associar per prestar el servei (DA 5a).","refs":[{"ref":"Art. 51.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Dichos cuerpos sólo podrán actuar en el ámbito territorial del municipio respectivo, salvo en situaciones de emergencia y previo requerimiento de las autoridades competentes."},{"ref":"Art. 52.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los Cuerpos de Policía Local son Institutos armados, de naturaleza civil con estructura y organización jerarquizada"},{"ref":"DA 5a LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En los supuestos en los que dos o más municipios limítrofes, pertenecientes a una misma Comunidad Autónoma, no dispongan separadamente de recursos suficientes para la prestación de los servicios de policía local, podrán asociarse"}]}]},{"n":"11","title":"Funcions de les policies locals i Junta Local de Seguretat","blocks":[{"text":"L''article 53.1 enumera nou funcions: a) protegir les autoritats de les corporacions locals i vigilar o custodiar els seus edificis i instal·lacions; b) ordenar, senyalitzar i dirigir el trànsit al nucli urbà; c) instruir atestats per accidents de circulació dins del nucli urbà; d) policia administrativa respecte a ordenances, bans i disposicions municipals; e) participar en les funcions de policia judicial segons l''article 29.2; f) auxiliar en accidents, catàstrofes o calamitats públiques i participar en els plans de protecció civil; g) fer diligències de prevenció per evitar actes delictius en el marc de les juntes de seguretat; h) vigilar els espais públics i col·laborar en la protecció de manifestacions i en grans concentracions humanes, quan se''ls requereixi; i i) cooperar en la resolució dels conflictes privats quan se''ls requereixi.","refs":[{"ref":"Art. 53.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"b) Ordenar, señalizar y dirigir el tráfico en el casco urbano, de acuerdo con lo establecido en las normas de circulación. c) Instruir atestados por accidentes de circulación dentro del casco urbano. d) Policía Administrativa, en lo relativo a las Ordenanzas, Bandos y demás disposiciones municipales dentro del ámbito de su competencia. e) Participar en las funciones de Policía Judicial, en la forma establecida en el artículo 29.2 de esta Ley."},{"ref":"Art. 53.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"g) Efectuar diligencias de prevención y cuantas actuaciones tiendan a evitar la comisión de actos delictivos en el marco de colaboración establecido en las Juntas de Seguridad."},{"ref":"Art. 53.1.i LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"i) Cooperar en la resolución de los conflictos privados cuando sean requeridos para ello."}]},{"text":"Les actuacions de les lletres c) (atestats de trànsit) i g) (diligències de prevenció) s''han de comunicar a les FCSE competents (art. 53.2). Investigar delictes per descobrir i detenir els culpables és funció de les FCSE (art. 11), no de la llista de la policia local. Als municipis amb policia pròpia es pot constituir una Junta Local de Seguretat, òrgan competent per fixar les formes de col·laboració entre els cossos; la presideix l''alcalde, i si hi assisteix el governador civil, la presidència és compartida (art. 54).","refs":[{"ref":"Art. 53.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las actuaciones que practiquen los Cuerpos de Policía Local en el ejercicio de las funciones previstas en los apartados c) y g) precedentes deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado competentes."},{"ref":"Art. 54 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La presidencia corresponderá al Alcalde, salvo que concurriera a sus sesiones el Gobernador civil de la provincia, en cuyo caso, la presidencia será compartida con éste."}]},{"text":"Nota: la LOFCS encara parla del «Gobernador civil»; la figura ja no existeix amb aquest nom, i les seves funcions les exerceixen avui els delegats i subdelegats del Govern, però això no consta al text de la llei de la carpeta. A l''examen, respon amb la literalitat de l''article.","refs":[{"ref":"Art. 54.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"salvo que concurriera a sus sesiones el Gobernador civil de la provincia"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Seguretat pública: competència exclusiva de l''Estat; el manteniment, del Govern de la Nació (art. 1).","refs":[{"ref":"Art. 1.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Seguridad Pública es competencia exclusiva del Estado."}]},{"text":"Tres classes de cossos: estatals, autonòmics i locals (art. 2).","refs":[{"ref":"Art. 2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"c) Los Cuerpos de Policía dependientes de las Corporaciones Locales."}]},{"text":"Mitjans: congruència, oportunitat i proporcionalitat; armes només amb risc racionalment greu (art. 5.2).","refs":[{"ref":"Art. 5.2.c LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"congruencia, oportunidad y proporcionalidad"}]},{"text":"Obediència deguda: mai no empara actes manifestament delictius o contraris a la Constitució o a les lleis (art. 5.1.d).","refs":[{"ref":"Art. 5.1.d LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En ningún caso, la obediencia debida podrá amparar órdenes"}]},{"text":"Intervenir sempre, en qualsevol temps i lloc, de servei o no (art. 5.4); no cal revelar les fonts (art. 5.5).","refs":[{"ref":"Art. 5.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"se hallaren o no de servicio"}]},{"text":"Agents de l''autoritat; consideració d''autoritat en atemptat amb armes de foc o explosius (art. 7).","refs":[{"ref":"Art. 7.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"tendrán a todos los efectos legales el carácter de agentes de la autoridad."}]},{"text":"CNP: civil, Interior; Guàrdia Civil: militar; en guerra i estat de setge, només Defensa (art. 9).","refs":[{"ref":"Art. 9 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"En tiempo de guerra y durante el estado de sitio, dependerá exclusivamente del Ministro de Defensa."}]},{"text":"Policia local: institut armat de naturalesa civil, jerarquitzat; només al seu municipi, llevat d''emergència i requeriment (arts. 51 i 52).","refs":[{"ref":"Art. 52.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los Cuerpos de Policía Local son Institutos armados, de naturaleza civil"}]},{"text":"Atestats de trànsit (c) i diligències de prevenció (g): comunicar-los a les FCSE (art. 53.2).","refs":[{"ref":"Art. 53.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"en el ejercicio de las funciones previstas en los apartados c) y g) precedentes deberán ser comunicadas"}]},{"text":"Junta Local de Seguretat: presidència de l''alcalde, compartida si hi és el governador civil (art. 54).","refs":[{"ref":"Art. 54 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La presidencia corresponderá al Alcalde"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859', null, null, null, null
  from public.topics t where t.slug = 'gub-t20-forces-cossos-seguretat'
