insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1983-19946', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
