insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t33-menors', 'Tema 33. Llei orgànica 5/2000: responsabilitat penal i detenció de menors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t33-menors' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Àmbit d''aplicació de la LO 5/2000"},{"n":"2","title":"Menors de catorze anys i bases de la responsabilitat"},{"n":"3","title":"Mesures i durada"},{"n":"4","title":"Detenció de menors: drets i terminis"},{"n":"5","title":"Desistiment i drets de les víctimes"}]'::jsonb, '["Art. 1 LO 5/2000: «Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho»","Art. 17 LO 5/2000: «dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal»","Art. 3 LO 5/2000: «no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil»","Art. 17 LO 5/2000: «los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad»","Art. 17 LO 5/2000: «También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal.»","Art. 7 LO 5/2000: «a) Internamiento en régimen cerrado.»","Art. 17 LO 5/2000: «Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor»","Art. 17 LO 5/2000: «En defecto de estos últimos la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por persona distinta del instructor del expediente.»","Art. 17 LO 5/2000: «éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención»","Art. 5 LO 5/2000: «Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos»","Art. 17 LO 5/2000: «El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de la diligencia de toma de declaración.»","Art. 18 LO 5/2000: «cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas»","Art. 18 LO 5/2000: «cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente»","Art. 17 LO 5/2000: «cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales»","Art. 9 LO 5/2000: «sólo se podrán imponer las medidas de libertad vigilada hasta un máximo de seis meses»","Art. 17 LO 5/2000: «El Juez competente para el procedimiento de hábeas corpus en relación a un menor será el Juez de Instrucción del lugar en el que se encuentre el menor privado de libertad»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Àmbit d''aplicació de la Llei orgànica 5/2000","blocks":[{"text":"La Llei orgànica 5/2000, de 12 de gener, reguladora de la responsabilitat penal dels menors, s''aplica per exigir la responsabilitat de les persones majors de catorze anys i menors de divuit per la comissió de fets tipificats com a delictes o faltes al Codi penal o a les lleis penals especials (art. 1.1). Aquestes persones gaudeixen de tots els drets reconeguts a la Constitució i a l''ordenament jurídic, particularment a la Llei orgànica 1/1996, de protecció jurídica del menor, i a la Convenció sobre els drets de l''infant de 1989 (art. 1.2).","refs":[{"ref":"Art. 1.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales."},{"ref":"Art. 1.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"particularmente en la Ley Orgánica 1/1996, de 15 de enero, de Protección Jurídica del Menor, así como en la Convención sobre los Derechos del Niño de 20 de noviembre de 1989"}]},{"text":"Les edats de la llei es refereixen sempre al moment de la comissió dels fets: haver-les superat abans o durant el procediment no afecta la competència dels jutges i fiscals de menors (art. 5.3). Nota: la llei encara parla de «faltes»; al Codi penal vigent les antigues faltes s''han substituït pels delictes lleus, però la font consolidada no ha adaptat aquesta terminologia.","refs":[{"ref":"Art. 5.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos, sin que el haberse rebasado las mismas antes del comienzo del procedimiento o durante la tramitación del mismo tenga incidencia alguna sobre la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores."}]}]},{"n":"2","title":"Competència dels jutges de menors","blocks":[{"text":"Els jutges de menors són competents per conèixer dels fets comesos per les persones de l''article 1 i per fer executar les sentències, i també per resoldre sobre les responsabilitats civils derivades (art. 2.1-2). La competència correspon al jutge de menors del lloc on s''ha comès el fet (art. 2.3).","refs":[{"ref":"Art. 2.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Los Jueces de Menores serán competentes para conocer de los hechos cometidos por las personas mencionadas en el artículo 1 de esta Ley, así como para hacer ejecutar las sentencias"},{"ref":"Art. 2.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo"}]},{"text":"Els delictes de terrorisme (articles 571 a 580 del Codi penal) i els delictes comesos per menors a l''estranger que corresponguin a la jurisdicció espanyola són competència del Jutjat Central de Menors de l''Audiència Nacional (art. 2.4).","refs":[{"ref":"Art. 2.4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La competencia para conocer de los delitos previstos en los artículos 571 a 580 del Código Penal corresponderá al Juzgado Central de Menores de la Audiencia Nacional."}]}]},{"n":"3","title":"Menors de catorze anys","blocks":[{"text":"Quan l''autor dels fets és menor de catorze anys, no se li exigeix responsabilitat d''acord amb aquesta llei, sinó que se li apliquen les normes de protecció de menors del Codi civil i les altres disposicions vigents (art. 3). El Ministeri Fiscal ha de remetre a l''entitat pública de protecció de menors testimoni dels particulars que consideri necessaris, perquè en valori la situació i promogui les mesures de protecció adequades.","refs":[{"ref":"Art. 3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil y demás disposiciones vigentes."},{"ref":"Art. 3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Ministerio Fiscal deberá remitir a la entidad pública de protección de menores testimonio de los particulares que considere precisos respecto al menor, a fin de valorar su situación"}]}]},{"n":"4","title":"Bases de la responsabilitat i paper del Ministeri Fiscal","blocks":[{"text":"Els menors són responsables d''acord amb la llei quan han comès els fets de l''article 1 i no hi concorre cap causa d''exempció o extinció de la responsabilitat criminal del Codi penal (art. 5.1). Si hi concorren les eximents dels números 1r, 2n i 3r de l''article 20 del Codi penal, se''ls poden aplicar mesures terapèutiques (art. 5.2).","refs":[{"ref":"Art. 5.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Los menores serán responsables con arreglo a esta Ley cuando hayan cometido los hechos a los que se refiere el artículo 1 y no concurra en ellos ninguna de las causas de exención o extinción de la responsabilidad criminal previstas en el vigente Código Penal."}]},{"text":"Correspon al Ministeri Fiscal defensar els drets dels menors, vigilar les actuacions en el seu interès i les garanties del procediment; per això dirigeix personalment la investigació i ordena a la policia judicial les actuacions necessàries (art. 6). En la justícia de menors, doncs, la policia actua sota la direcció del fiscal, no del jutge d''instrucció.","refs":[{"ref":"Art. 6 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"para lo cual dirigirá personalmente la investigación de los hechos y ordenará que la policía judicial practique las actuaciones necesarias para la comprobación de aquéllos y de la participación del menor en los mismos"}]}]},{"n":"5","title":"Drets de les víctimes","blocks":[{"text":"El Ministeri Fiscal i el jutge de menors vetllen en tot moment per protegir els drets de les víctimes i perjudicats (art. 4). Se les ha d''informar immediatament de les mesures d''assistència, i les víctimes de violència han de ser derivades a l''Oficina d''Atenció a la Víctima. Les víctimes i perjudicats tenen dret a personar-se i ser part en l''expedient, i si no es personen ni renuncien a les accions civils, el fiscal les exercirà.","refs":[{"ref":"Art. 4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Ministerio Fiscal y el Juez de Menores velarán en todo momento por la protección de los derechos de las víctimas y de las personas perjudicadas"},{"ref":"Art. 4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las víctimas y las personas perjudicadas tendrán derecho a personarse y ser parte en el expediente que se incoe al efecto"}]},{"text":"Les declaracions de les víctimes de violència de gènere, violència sexual o tracta, i de les víctimes menors d''edat o amb discapacitat, es fan preferentment de forma telemàtica, llevat que es consideri necessària la presència física (art. 4).","refs":[{"ref":"Art. 4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando sean víctimas de violencia de género, de violencia sexual, de trata de seres humanos o cuando sean víctimas menores de edad o con discapacidad."}]}]},{"n":"6","title":"Les mesures","blocks":[{"text":"Les mesures que poden imposar els jutges de menors, ordenades de més a menys restricció de drets, són (art. 7.1): internament en règim tancat, semiobert i obert; internament terapèutic; tractament ambulatori; assistència a un centre de dia; permanència de cap de setmana (fins a trenta-sis hores entre divendres i diumenge); llibertat vigilada; prohibició d''aproximar-se o comunicar-se amb la víctima; convivència amb una altra persona, família o grup educatiu; prestacions en benefici de la comunitat (que requereixen el consentiment del menor); tasques socioeducatives; amonestació; privació del permís de conduir o de llicències d''armes; i inhabilitació absoluta.","refs":[{"ref":"Art. 7.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes: a) Internamiento en régimen cerrado."},{"ref":"Art. 7.1.g LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"permanecerán en su domicilio o en un centro hasta un máximo de treinta y seis horas entre la tarde o noche del viernes y la noche del domingo"},{"ref":"Art. 7.1.k LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"k) Prestaciones en beneficio de la comunidad. La persona sometida a esta medida, que no podrá imponerse sin su consentimiento"}]},{"text":"Les mesures d''internament tenen dos períodes: el primer al centre i el segon en llibertat vigilada (art. 7.2). Per triar la mesura s''atén de manera flexible no només als fets, sinó especialment a l''edat, les circumstàncies familiars i socials, la personalitat i l''interès del menor (art. 7.3). En delictes contra la llibertat sexual, el jutge imposa a més programes d''educació sexual i en igualtat (art. 7.5).","refs":[{"ref":"Art. 7.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las medidas de internamiento constarán de dos períodos: el primero se llevará a cabo en el centro correspondiente"},{"ref":"Art. 7.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"sino especialmente a la edad, las circunstancias familiares y sociales, la personalidad y el interés del menor"}]}]},{"n":"7","title":"Durada de les mesures","blocks":[{"text":"Si els fets són falta, només es poden imposar llibertat vigilada fins a sis mesos, amonestació, permanència de cap de setmana fins a quatre caps de setmana, prestacions en benefici de la comunitat fins a cinquanta hores, privació del permís o llicències fins a un any, prohibició d''aproximació fins a sis mesos i tasques socioeducatives fins a sis mesos (art. 9.1). L''internament en règim tancat només és aplicable a delictes greus, a delictes menys greus amb violència, intimidació o greu risc per a la vida, o a delictes comesos en grup o en banda (art. 9.2). Com a regla general, les mesures no poden superar els dos anys (art. 9.3), i els fets imprudents no es poden sancionar amb internament tancat (art. 9.4).","refs":[{"ref":"Art. 9.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando los hechos cometidos sean calificados de falta, sólo se podrán imponer las medidas de libertad vigilada hasta un máximo de seis meses"},{"ref":"Art. 9.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La duración de las medidas no podrá exceder de dos años"},{"ref":"Art. 9.4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las acciones u omisiones imprudentes no podrán ser sancionadas con medidas de internamiento en régimen cerrado."}]},{"text":"Per als fets de l''article 9.2, si el menor tenia catorze o quinze anys, la mesura pot arribar a tres anys; si en tenia setze o disset, a sis anys (art. 10.1). En els delictes més greus (homicidi, assassinat, agressions sexuals agreujades, terrorisme o delictes amb pena igual o superior a quinze anys), l''internament tancat és d''un a cinc anys per als de catorze i quinze anys, i d''un a vuit anys per als de setze i disset (art. 10.2).","refs":[{"ref":"Art. 10.1.a LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad, la medida podrá alcanzar tres años de duración."},{"ref":"Art. 10.1.b LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, la duración máxima de la medida será de seis años"},{"ref":"Art. 10.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"una medida de internamiento en régimen cerrado de uno a cinco años de duración"}]}]},{"n":"8","title":"La detenció del menor: forma, informació i notificacions","blocks":[{"text":"Les autoritats i funcionaris que intervinguin en la detenció d''un menor l''han de practicar de la manera que menys el perjudiqui i l''han d''informar, en un llenguatge clar i comprensible i de forma immediata, dels fets que se li imputen, de les raons de la detenció i dels seus drets, especialment els de l''article 520 de la Llei d''enjudiciament criminal (art. 17.1). També han de notificar immediatament la detenció i el lloc de custòdia als representants legals del menor i al Ministeri Fiscal.","refs":[{"ref":"Art. 17.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"deberán practicarla en la forma que menos perjudique a éste y estarán obligados a informarle, en un lenguaje claro y comprensible y de forma inmediata, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten"},{"ref":"Art. 17.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal."}]},{"text":"Si el menor és estranger, la detenció es notifica a les autoritats consulars quan tingui la residència habitual fora d''Espanya o quan ho demanin ell o els seus representants legals (art. 17.1). La Llei d''enjudiciament criminal hi afegeix que el menor detingut es posa a disposició de les seccions de menors de la Fiscalia (art. 520.4 LECrim).","refs":[{"ref":"Art. 17.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales."},{"ref":"Art. 520.4 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Si se tratare de un menor, será puesto a disposición de las Secciones de Menores de la Fiscalía"}]}]},{"n":"9","title":"Declaració, custòdia i terminis de la detenció","blocks":[{"text":"Tota declaració del menor detingut s''ha de fer en presència del seu lletrat i dels qui n''exerceixen la pàtria potestat, tutela o guarda, de fet o de dret, llevat que les circumstàncies aconsellin el contrari (art. 17.2). A falta d''aquests, la declaració es fa en presència del Ministeri Fiscal, representat per una persona diferent de l''instructor de l''expedient. El menor té dret a una entrevista reservada amb l''advocat abans i en acabar la presa de declaració.","refs":[{"ref":"Art. 17.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor"},{"ref":"Art. 17.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"En defecto de estos últimos la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por persona distinta del instructor del expediente. El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de la diligencia de toma de declaración."}]},{"text":"Mentre dura la detenció, els menors han d''estar custodiats en dependències adequades i separades de les dels majors d''edat, i han de rebre l''assistència social, psicològica, mèdica i física que necessitin (art. 17.3). La detenció policial no pot durar més del temps estrictament necessari i, en tot cas, en un màxim de vint-i-quatre hores el menor ha de ser posat en llibertat o a disposició del Ministeri Fiscal (art. 17.4). El fiscal ha de resoldre dins de les quaranta-vuit hores des de la detenció sobre la llibertat, el desistiment o la incoació de l''expedient (art. 17.5).","refs":[{"ref":"Art. 17.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad"},{"ref":"Art. 17.4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal."},{"ref":"Art. 17.5 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre la puesta en libertad del menor, sobre el desistimiento al que se refiere el artículo siguiente, o sobre la incoación del expediente"}]}]},{"n":"10","title":"Habeas corpus del menor","blocks":[{"text":"El jutge competent per a l''habeas corpus d''un menor és el jutge d''instrucció del lloc on es trobi el menor privat de llibertat; si no consta, el del lloc de la detenció; i, a falta dels anteriors, el del lloc on s''hagin tingut les últimes notícies del seu parador (art. 17.6). Si és el mateix menor qui insta l''habeas corpus, la força pública responsable de la detenció ho ha de notificar immediatament al Ministeri Fiscal, a més de donar curs al procediment d''acord amb la Llei orgànica 6/1984 (tema 29).","refs":[{"ref":"Art. 17.6 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Juez competente para el procedimiento de hábeas corpus en relación a un menor será el Juez de Instrucción del lugar en el que se encuentre el menor privado de libertad"},{"ref":"Art. 17.6 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal, además de dar curso al procedimiento conforme a la ley orgánica reguladora."}]}]},{"n":"11","title":"Desistiment, conciliació i mesures cautelars","blocks":[{"text":"El Ministeri Fiscal pot desistir d''incoar l''expedient quan els fets són delictes menys greus sense violència o intimidació en les persones, o faltes; en aquest cas, trasllada el que s''ha actuat a l''entitat pública de protecció i comunica el desistiment als ofesos (art. 18). Però si consta que el menor ja ha comès abans fets de la mateixa naturalesa, ha d''incoar l''expedient. També pot desistir de continuar-lo si el menor s''ha conciliat amb la víctima o s''ha compromès a reparar el dany, només en delictes menys greus o faltes (art. 19).","refs":[{"ref":"Art. 18 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Ministerio Fiscal podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas"},{"ref":"Art. 18 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente"},{"ref":"Art. 19.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falta."}]},{"text":"El fiscal pot demanar al jutge de menors mesures cautelars (internament, llibertat vigilada, prohibició d''aproximació o convivència amb un grup educatiu) quan hi ha indicis racionals de delicte i risc d''eludir la justícia o d''atemptar contra la víctima (art. 28.1). L''internament cautelar dura com a màxim sis mesos, prorrogables tres mesos més (art. 28.3).","refs":[{"ref":"Art. 28.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El tiempo máximo de la medida cautelar de internamiento será de seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La llei s''aplica a majors de catorze i menors de divuit anys; les edats es comptan en el moment dels fets (art. 1 i 5.3).","refs":[{"ref":"Art. 1.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"mayores de catorce años y menores de dieciocho"}]},{"text":"Menors de catorze: no hi ha responsabilitat per aquesta llei; s''apliquen les normes de protecció del Codi civil (art. 3).","refs":[{"ref":"Art. 3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil"}]},{"text":"Detenció policial d''un menor: màxim vint-i-quatre hores fins a la llibertat o la posada a disposició del Ministeri Fiscal; el fiscal resol en quaranta-vuit hores des de la detenció (art. 17.4-5).","refs":[{"ref":"Art. 17.4 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"dentro del plazo máximo de veinticuatro horas"}]},{"text":"Notificació immediata als representants legals i al fiscal; als cònsols, si el menor resideix fora d''Espanya o ho demana (art. 17.1).","refs":[{"ref":"Art. 17.1 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"a los representantes legales del menor y al Ministerio Fiscal"}]},{"text":"Declaració amb lletrat i pares o tutors; si no n''hi ha, amb el fiscal (persona diferent de l''instructor). Entrevista reservada abans i després de declarar (art. 17.2).","refs":[{"ref":"Art. 17.2 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"representado por persona distinta del instructor del expediente"}]},{"text":"Custòdia en dependències adequades i separades de les dels adults (art. 17.3).","refs":[{"ref":"Art. 17.3 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"separadas de las que se utilicen para los mayores de edad"}]},{"text":"La mesura més restrictiva és l''internament en règim tancat; per faltes, llibertat vigilada màxim sis mesos (art. 7 i 9).","refs":[{"ref":"Art. 7.1.a LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"a) Internamiento en régimen cerrado."}]},{"text":"Desistiment del fiscal: delictes menys greus sense violència ni intimidació o faltes, llevat que el menor sigui reiterant (art. 18).","refs":[{"ref":"Art. 18 LO 5/2000","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"delitos menos graves sin violencia o intimidación en las personas o faltas"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', null, null, null, null
