insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 1428/2003, de 21 de noviembre, Reglamento General de Circulación (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t36-reglament-circulacio', 'Tema 36. Reglament general de circulació') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t36-reglament-circulacio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Taxes d''alcohol"},{"n":"2","title":"Proves de detecció alcohòlica"},{"n":"3","title":"Obligacions del conductor: atenció i dispositius"},{"n":"4","title":"Límits de velocitat en vies urbanes"},{"n":"5","title":"Elements de protecció: casc"},{"n":"6","title":"Prioritat dels vianants i ordre de preferència dels senyals"}]'::jsonb, '["Art. 20 RGC: «con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro»","Art. 50 RGC: «b) 30 km/h en vías de un único carril por sentido de circulación.»","Art. 133 RGC: «a) Señales y órdenes de los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tengan encomendadas.»","Art. 18 RGC: «Queda prohibido conducir utilizando cualquier tipo de casco de audio, auriculares o instrumentos similares conectados a aparatos receptores o reproductores de sonido»","Art. 121 RGC: «gozarán de prioridad de paso y estancia en las vías públicas, en los términos que se regulan en el presente reglamento»","Art. 20 RGC: «Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso»","Art. 20 RGC: «No podrán circular por las vías objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial los conductores de vehículos ni los conductores de bicicletas»","Art. 23 RGC: «que entre la realización de la primera y de la segunda prueba medie un tiempo mínimo de 10 minutos»","Art. 23 RGC: «aún sin alcanzar estos límites, presentara la persona examinada síntomas evidentes de encontrarse bajo la influencia de bebidas alcohólicas»","Art. 22 RGC: «consistirán, normalmente, en la verificación del aire espirado mediante etilómetros que, oficialmente autorizados, determinarán de forma cuantitativa el grado de impregnación alcohólica»","Art. 50 RGC: «los vehículos que transporten mercancías peligrosas circularán como máximo a 40 km/h»","Art. 50 RGC: «Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica.»","Art. 118 RGC: «siendo obligatorio su uso por los menores de dieciséis años en todo tipo de vías»","Art. 118 RGC: «Los conductores que desarrollen su actividad profesional circulando en bicicletas y demás ciclos, están obligados a utilizar adecuadamente abrochado casco de protección homologado o certificado en vías urbanas y travesías.»","Art. 118 RGC: «c) Calzado cerrado, que cubra todo el pie, cuando circulen en todo tipo de vías.»","Art. 20 RGC: «los conductores no podrán hacerlo con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos por litro»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Àmbit d''aplicació del Reglament general de circulació","blocks":[{"text":"El Reglament general de circulació, aprovat pel Reial decret 1428/2003, de 21 de novembre (RGC), desplega la Llei de trànsit. Els seus preceptes s''apliquen a tot el territori i obliguen els titulars i usuaris de les vies i terrenys públics aptes per a la circulació, urbans i interurbans, als de les vies d''ús comú i, a falta d''altres normes, als de les vies privades utilitzades per una col·lectivitat indeterminada d''usuaris (art. 1.1). No s''apliquen als camins, terrenys, garatges o locals dins de finques privades, sostrets a l''ús públic i destinats a l''ús exclusiu dels propietaris (art. 1.2).","refs":[{"ref":"Art. 1.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"obligarán a los titulares y usuarios de las vías y terrenos públicos aptos para la circulación, tanto urbanos como interurbanos, a los de las vías y terrenos que, sin tener tal aptitud, sean de uso común y, en defecto de otras normas, a los de las vías y terrenos privados que sean utilizados por una colectividad indeterminada de usuarios."},{"ref":"Art. 1.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"No serán aplicables los preceptos mencionados a los caminos, terrenos, garajes, cocheras u otros locales de similar naturaleza, construidos dentro de fincas privadas, sustraídos al uso público y destinados al uso exclusivo de los propietarios y sus dependientes."}]},{"text":"Nota: molts articles del Reglament encara remeten al «texto articulado» de la Llei de trànsit de 1990 (per exemple, l''article 65); la llei vigent és el RDL 6/2015 (tema 34), en què les infraccions greus i molt greus són als articles 76 i 77. Les remissions de l''article 50, en canvi, ja estan actualitzades.","refs":[{"ref":"Art. 3.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"de acuerdo con lo dispuesto en el artículo 65.4.a) y 5.c) del texto articulado de la Ley sobre tráfico, circulación de vehículos a motor y seguridad vial"},{"ref":"Art. 50.8 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"conforme se prevé en el artículo 76. a), salvo que tengan la consideración de muy graves, de conformidad con lo dispuesto en el artículo 77.a), ambos del texto refundido"}]}]},{"n":"2","title":"Normes generals de comportament del conductor","blocks":[{"text":"S''ha de conduir amb la diligència i precaució necessàries per evitar qualsevol dany, propi o aliè, sense posar en perill el conductor, els ocupants ni els altres usuaris; està terminantment prohibit conduir de manera negligent o temerària (art. 3.1). La conducció negligent és infracció greu i la temerària, molt greu (art. 3.2).","refs":[{"ref":"Art. 3.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Se deberá conducir con la diligencia y precaución necesarias para evitar todo daño, propio o ajeno, cuidando de no poner en peligro, tanto al mismo conductor como a los demás ocupantes del vehículo y al resto de los usuarios de la vía. Queda terminantemente prohibido conducir de modo negligente o temerario"}]},{"text":"El conductor ha de mantenir la llibertat de moviments, el camp de visió necessari i l''atenció permanent a la conducció, i cuidar la posició adequada dels passatgers i la col·locació dels objectes o animals transportats (art. 18.1). És incompatible amb aquesta atenció usar, amb el vehicle en moviment, pantalles amb accés a internet, monitors de televisió o reproductors de vídeo; s''exceptuen els monitors necessaris per veure l''accés de vianants o la càmera de maniobres i el dispositiu GPS.","refs":[{"ref":"Art. 18.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Se considera incompatible con la obligatoria atención permanente a la conducción el uso por el conductor con el vehículo en movimiento de dispositivos tales como pantallas con acceso a internet, monitores de televisión y reproductores de vídeo o DVD."},{"ref":"Art. 18.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"así como el dispositivo GPS."}]}]},{"n":"3","title":"Auriculars, mòbil i detectors de radar","blocks":[{"text":"Està prohibit conduir amb qualsevol tipus de casc d''àudio, auriculars o instruments similars connectats a aparells de so, o altres dispositius que disminueixin l''atenció, llevat de l''ensenyament i les proves d''aptitud en circuit obert quan ho exigeixi el Reglament general de conductors (art. 18.2). També es prohibeix utilitzar durant la conducció el telèfon mòbil i qualsevol altre sistema de comunicació. S''exceptuen els dispositius sense fil homologats integrats al casc de motocicletes i ciclomotors, només per a intercomunicació o navegació, i la comunicació feta sense fer servir les mans ni auriculars.","refs":[{"ref":"Art. 18.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Queda prohibido conducir utilizando cualquier tipo de casco de audio, auriculares o instrumentos similares conectados a aparatos receptores o reproductores de sonido u otros dispositivos que disminuyan la atención permanente a la conducción, excepto durante la correspondiente enseñanza y la realización de las pruebas de aptitud en circuito abierto"},{"ref":"Art. 18.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"b) cuando el desarrollo de la comunicación tenga lugar sin emplear las manos ni usar cascos, auriculares o instrumentos similares."}]},{"text":"N''estan exempts els agents de l''autoritat en l''exercici de les seves funcions i els conductors de vehicles de les Forces Armades que circulin en comboi (art. 18.2). Es prohibeix instal·lar o portar inhibidors de radars o cinemòmetres i també mecanismes de detecció de radars; en queden exclosos els mecanismes d''avís que informen de la posició dels sistemes de vigilància (art. 18.3).","refs":[{"ref":"Art. 18.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Quedan exentos de estas prohibiciones los agentes de la autoridad en el ejercicio de las funciones que tengan encomendadas"},{"ref":"Art. 18.3 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Quedan excluidos de esta prohibición los mecanismos de aviso que informan de la posición de los sistemas de vigilancia del tráfico."}]}]},{"n":"4","title":"Taxes d''alcohol","blocks":[{"text":"No poden circular els conductors de vehicles ni els conductors de bicicletes amb una taxa d''alcohol en sang superior a 0,5 g/l o en aire espirat superior a 0,25 mg/l (art. 20). La taxa baixa a 0,3 g/l en sang o 0,15 mg/l en aire per als conductors de vehicles de mercaderies de més de 3.500 kg, de viatgers de més de nou places o de servei públic, de transport escolar i de menors, de mercaderies perilloses, de servei d''urgència o de transports especials.","refs":[{"ref":"Art. 20 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"No podrán circular por las vías objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial los conductores de vehículos ni los conductores de bicicletas con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro."},{"ref":"Art. 20 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"al transporte escolar y de menores, al de mercancías peligrosas o de servicio de urgencia o transportes especiales, los conductores no podrán hacerlo con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos por litro."}]},{"text":"Els conductors de qualsevol vehicle tampoc no poden superar 0,3 g/l en sang ni 0,15 mg/l en aire durant els dos anys següents a l''obtenció del permís o llicència (art. 20). A més, la Llei de trànsit estableix que el conductor menor d''edat no pot circular en cap cas amb una taxa superior a 0 (art. 14.1 LTSV).","refs":[{"ref":"Art. 20 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso o licencia que les habilita para conducir."},{"ref":"Art. 14.1 RDL 6/2015","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"En ningún caso el conductor menor de edad podrá circular por las vías con una tasa de alcohol en sangre superior a 0 gramos por litro"}]}]},{"n":"5","title":"Persones obligades a les proves d''alcoholèmia","blocks":[{"text":"Tots els conductors de vehicles i de bicicletes estan obligats a sotmetre''s a les proves de detecció d''alcohol, igual que els altres usuaris de la via implicats en un accident (art. 21). Els agents encarregats de la vigilància del trànsit hi poden sotmetre: a) qualsevol usuari o conductor implicat directament com a possible responsable en un accident; b) qui condueixi amb símptomes evidents o fets que facin presumir raonablement que ho fa sota la influència de l''alcohol; c) els conductors denunciats per qualsevol infracció del Reglament; i d) els requerits dins dels programes de controls preventius ordenats per l''autoritat.","refs":[{"ref":"Art. 21 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Todos los conductores de vehículos y de bicicletas quedan obligados a someterse a las pruebas que se establezcan para la detección de las posibles intoxicaciones por alcohol."},{"ref":"Art. 21 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"d) A los que, con ocasión de conducir un vehículo, sean requeridos al efecto por la autoridad o sus agentes dentro de los programas de controles preventivos de alcoholemia ordenados por dicha autoridad."}]}]},{"n":"6","title":"Pràctica de les proves d''alcohol","blocks":[{"text":"Les proves les practiquen els agents de trànsit i consisteixen, normalment, en la verificació de l''aire espirat amb etilòmetres oficialment autoritzats, que determinen de forma quantitativa el grau d''impregnació alcohòlica (art. 22.1). Si la persona té lesions que n''impedeixen la pràctica, decideix el personal facultatiu del centre mèdic (art. 22.2).","refs":[{"ref":"Art. 22.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"consistirán, normalmente, en la verificación del aire espirado mediante etilómetros que, oficialmente autorizados, determinarán de forma cuantitativa el grado de impregnación alcohólica"}]},{"text":"Si el resultat supera 0,5 g/l o 0,25 mg/l (o la taxa especial que correspongui) o, sense arribar-hi, la persona presenta símptomes evidents d''estar sota la influència de l''alcohol, l''agent fa una segona prova de contrast amb aire espirat, després d''informar-la''n (art. 23.1). L''ha d''advertir del dret a controlar que entre la primera i la segona prova passin com a mínim 10 minuts (art. 23.2), del dret a formular al·legacions i del dret a contrastar els resultats amb anàlisis de sang, orina o similars (art. 23.3). L''import de les anàlisis el diposita l''interessat i el paga si el resultat és positiu; si és negatiu, se li retorna (art. 23.4).","refs":[{"ref":"Art. 23.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"aún sin alcanzar estos límites, presentara la persona examinada síntomas evidentes de encontrarse bajo la influencia de bebidas alcohólicas"},{"ref":"Art. 23.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"que entre la realización de la primera y de la segunda prueba medie un tiempo mínimo de 10 minutos."},{"ref":"Art. 23.4 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"El importe de dichos análisis deberá ser previamente depositado por el interesado y con él se atenderá al pago cuando el resultado de la prueba de contraste sea positivo"}]}]},{"n":"7","title":"Diligències de l''agent i drogues","blocks":[{"text":"Si la segona prova o les anàlisis donen positiu, o el conductor presenta símptomes evidents o està implicat en una conducta presumptament delictiva, l''agent, a més de complir la Llei d''enjudiciament criminal, ha de descriure al butlletí de denúncia o a l''atestat el procediment seguit i els instruments emprats, consignar les advertències fetes i, si els fets són delictius, conduir la persona al jutjat (art. 24).","refs":[{"ref":"Art. 24 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) Describir con precisión, en el boletín de denuncia o en el atestado de las diligencias que practique, el procedimiento seguido para efectuar la prueba o pruebas de detección alcohólica"},{"ref":"Art. 24.c RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"c) Conducir al sometido a examen, o al que se negase a someterse a las pruebas de detección alcohólica, en los supuestos en que los hechos revistan caracteres delictivos"}]},{"text":"No poden circular els conductors de vehicles o bicicletes que hagin incorporat al seu organisme estupefaents, psicotròpics, estimulants o substàncies anàlogues, inclosos els medicaments que alterin l''estat físic o mental (art. 27). Les proves consisteixen normalment en un reconeixement mèdic i anàlisis clíniques, i si la persona s''hi nega l''agent pot immobilitzar immediatament el vehicle (art. 28.1). Nota: la Llei de trànsit vigent preveu per a les drogues una prova salival amb dispositiu autoritzat (art. 14.3 LTSV), més moderna que la redacció del Reglament.","refs":[{"ref":"Art. 28.1.b RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"En los casos de negativa a efectuar dichas pruebas, el agente podrá proceder a la inmediata inmovilización del vehículo en la forma prevista en el artículo 25."},{"ref":"Art. 14.3 RDL 6/2015","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"para la detección de la presencia de drogas en el organismo, en una prueba salival mediante un dispositivo autorizado"}]}]},{"n":"8","title":"Límits de velocitat en vies urbanes i travesseres","blocks":[{"text":"El límit genèric de velocitat en vies urbanes és (art. 50.1): a) 20 km/h en vies amb plataforma única de calçada i vorera; b) 30 km/h en vies d''un únic carril per sentit de circulació; i c) 50 km/h en vies de dos o més carrils per sentit. Els carrils reservats a determinats usuaris o al transport públic no es compten. L''autoritat municipal pot rebaixar aquestes velocitats amb senyalització específica (art. 50.2) i, excepcionalment, augmentar fins a 50 km/h la de les vies d''un únic carril per sentit (art. 50.3).","refs":[{"ref":"Art. 50.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) 20 km/h en vías que dispongan de plataforma única de calzada y acera. b) 30 km/h en vías de un único carril por sentido de circulación. c) 50 km/h en vías de dos o más carriles por sentido de circulación."},{"ref":"Art. 50.3 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica."}]},{"text":"En vies urbanes de dos o més carrils per sentit i en travesseres, els vehicles que transporten mercaderies perilloses circulen com a màxim a 40 km/h (art. 50.4). El límit en travesseres és de 50 km/h (art. 50.5), i en autopistes i autovies dins de poblat, de 80 km/h, ampliable per acord de l''autoritat municipal i el titular de la via (art. 50.6).","refs":[{"ref":"Art. 50.4 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"los vehículos que transporten mercancías peligrosas circularán como máximo a 40 km/h."},{"ref":"Art. 50.6 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"El límite genérico de velocidad en autopistas y autovías que transcurren dentro de poblado será de 80 km/h"}]}]},{"n":"9","title":"Cinturó, sistemes de retenció i casc","blocks":[{"text":"El conductor i els ocupants han d''utilitzar els cinturons de seguretat homologats, en vies urbanes i interurbanes, i els menors d''estatura igual o inferior a 135 centímetres han d''usar sistemes de retenció infantil (art. 117.1). En vehicles de fins a nou places, aquests menors han d''anar als seients del darrere, llevat d''excepcions (art. 117.3).","refs":[{"ref":"Art. 117.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"En todo caso, los menores de edad de estatura igual o inferior a 135 centímetros deberán utilizar sistemas de retención infantil"}]},{"text":"Els conductors i passatgers de motocicletes, tricicles, quadricicles, ciclomotors i quads han de dur casc homologat abrocat en tot tipus de vies, guants en vies interurbanes i calçat tancat que cobreixi tot el peu en tot tipus de vies (art. 118.1). Els ciclistes han de dur casc en vies interurbanes, i els menors de setze anys en tot tipus de vies; els qui treballen circulant en bicicleta, també en vies urbanes i travesseres (art. 118.2). Els conductors de vehicles de mobilitat personal estan obligats a dur casc (art. 118.3).","refs":[{"ref":"Art. 118.1.c RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"c) Calzado cerrado, que cubra todo el pie, cuando circulen en todo tipo de vías."},{"ref":"Art. 118.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"siendo obligatorio su uso por los menores de dieciséis años en todo tipo de vías."},{"ref":"Art. 118.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Los conductores que desarrollen su actividad profesional circulando en bicicletas y demás ciclos, están obligados a utilizar adecuadamente abrochado casco de protección homologado o certificado en vías urbanas y travesías."},{"ref":"Art. 118.3 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Los conductores de vehículos de movilidad personal están obligados a utilizar adecuadamente abrochado casco de protección homologado o certificado."}]}]},{"n":"10","title":"Vianants","blocks":[{"text":"Els vianants, i especialment els que tenen mobilitat reduïda o alguna discapacitat, els infants i la gent gran, gaudeixen de prioritat de pas i d''estada a les vies públiques en els termes del Reglament, i els vehicles han de tenir especial cura de no posar-los en risc (art. 121.1).","refs":[{"ref":"Art. 121.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"gozarán de prioridad de paso y estancia en las vías públicas, en los términos que se regulan en el presente reglamento."}]},{"text":"On hi ha passos de vianants, cal travessar-hi precisament per ells (art. 124.1). Si el pas té semàfor, s''obeeix; si la circulació la regula un agent o un semàfor de vehicles, no s''entra a la calçada mentre permetin el pas de vehicles; i en els passos amb marca vial, tot i tenir preferència, el vianant només hi ha d''entrar quan la distància i la velocitat dels vehicles ho permetin amb seguretat. Cal travessar perpendicularment, sense aturar-se (art. 124.3), i no es poden travessar places i rotondes per la calçada (art. 124.4).","refs":[{"ref":"Art. 124.1.c RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"c) En los restantes pasos para peatones señalizados mediante la correspondiente marca vial, aunque tienen preferencia, sólo deben penetrar en la calzada cuando la distancia y la velocidad de los vehículos que se aproximen permitan hacerlo con seguridad."},{"ref":"Art. 124.4 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Los peatones no podrán atravesar las plazas y glorietas por su calzada, debiendo rodearlas, a no ser que exista un paso para peatones habilitado."}]}]},{"n":"11","title":"Obediència i ordre de preferència dels senyals","blocks":[{"text":"Tots els usuaris han d''obeir els senyals que estableixin una obligació o una prohibició (art. 132.1) i, llevat de circumstàncies especials, les prescripcions dels senyals encara que semblin contradir les normes de comportament (art. 132.2). L''ordre de preferència és (art. 133.1): a) senyals i ordres dels agents de l''autoritat encarregats de la vigilància del trànsit; b) senyalització i abalisament circumstancial; c) semàfors; d) senyals verticals; i e) marques vials.","refs":[{"ref":"Art. 132.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"los usuarios deben obedecer las prescripciones indicadas por las señales, aun cuando parezcan estar en contradicción con las normas de comportamiento en la circulación."},{"ref":"Art. 133.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) Señales y órdenes de los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tengan encomendadas. b) Señalización y balizamiento circunstancial que modifique el régimen normal de utilización de la vía, dispositivos delimitadores y señales de balizamiento. c) Semáforos. d) Señales verticales de circulación. e) Marcas viales."}]},{"text":"Si els senyals semblen contradictoris, preval el preferent segons aquest ordre o, si són del mateix tipus, el més restrictiu (art. 133.2). Els semàfors poden ser per a vianants, circulars per a vehicles, quadrats o de carril, i reservats a determinats vehicles (art. 143).","refs":[{"ref":"Art. 133.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"prevalecerá la preferente, según el orden a que se refiere el apartado anterior, o la más restrictiva, si se trata de señales del mismo tipo."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Alcohol general (també ciclistes): 0,5 g/l en sang o 0,25 mg/l en aire; professionals i novells (dos anys): 0,3 g/l o 0,15 mg/l (art. 20).","refs":[{"ref":"Art. 20 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"superior a 0,25 miligramos por litro"}]},{"text":"Entre la primera i la segona prova d''alcoholèmia: mínim 10 minuts; segona prova també si hi ha símptomes evidents (art. 23).","refs":[{"ref":"Art. 23.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"un tiempo mínimo de 10 minutos"}]},{"text":"Velocitat urbana: 20 km/h plataforma única; 30 km/h un carril per sentit (ampliable a 50); 50 km/h dos o més carrils; mercaderies perilloses 40 km/h; autopistes dins de poblat 80 km/h (art. 50).","refs":[{"ref":"Art. 50.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"b) 30 km/h en vías de un único carril por sentido de circulación."}]},{"text":"Ordre de preferència: agents, senyalització circumstancial, semàfors, senyals verticals i marques vials (les darreres); del mateix tipus, el més restrictiu (art. 133).","refs":[{"ref":"Art. 133.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"e) Marcas viales."}]},{"text":"Auriculars prohibits; el GPS sí que es pot usar; exempts els agents en servei (art. 18).","refs":[{"ref":"Art. 18.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"así como el dispositivo GPS."}]},{"text":"Casc de ciclistes: menors de setze anys en tot tipus de vies; professionals també en vies urbanes (art. 118.2). Motos: calçat tancat en tot tipus de vies (art. 118.1).","refs":[{"ref":"Art. 118.2 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"siendo obligatorio su uso por los menores de dieciséis años en todo tipo de vías."}]},{"text":"Els vianants tenen prioritat de pas i d''estada (art. 121).","refs":[{"ref":"Art. 121.1 RGC","law":"RGC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"gozarán de prioridad de paso y estancia en las vías públicas"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514', null, null, null, null
