insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Els deu districtes i els seus barris"},{"n":"2","title":"Ciutat Vella i l''Eixample: centre històric i Pla Cerdà"},{"n":"3","title":"Districtes de muntanya i de mar: Sarrià - Sant Gervasi, Horta-Guinardó, Sant Martí"},{"n":"4","title":"Població: lectura del padró municipal d''habitants"},{"n":"5","title":"Festes i tradicions: la Mercè, la Festa Major de Gràcia i l''ou com balla"},{"n":"6","title":"Patrimoni i memòria: el Fossar de les Moreres"},{"n":"7","title":"Equipaments i serveis: mercats municipals, platja de gossos i metro L9 Sud"}]'::jsonb, '["Districtes Districte de Les Corts: «Les Corts és un dels deu districtes de Barcelona»","Ciutat Vella Districte de Ciutat Vella: «El districte de Ciutat Vella està delimitat pel perímetre de la muralla de l’antiga ciutat i es correspon geogràficament amb el centre històric de Barcelona.»","Ciutat Vella Districte de Ciutat Vella: «El districte limita a l’oest amb l’Eixample, a l’est amb el mar Mediterrani, al nord amb Sant Martí i al sud amb Sants-Montjuïc.»","Ciutat Vella Districte de Ciutat Vella: «Al sud hi trobem la Barceloneta; a ponent, el Raval; al centre, el Gòtic, i a llevant, Sant Pere, Santa Caterina i la Ribera.»","Eixample Districte de l''Eixample: «La Barcelona moderna va néixer a l''Eixample, ideada per l''enginyer i urbanista a qui deu el seu dibuix màgic i únic: Ildefons Cerdà.»","Eixample Districte de l''Eixample: «La part central, la Dreta de l''Eixample, va ser el barri de la burgesia que va introduir a casa seva un estil propi, el modernisme.»","Eixample Districte de l''Eixample: «L’estació del Nord dona personalitat a un barri situat entre la via del tren i la Gran Via. Allà se situa un dels punts culturals més importants, amb l’Auditori i el Teatre Nacional de Catalunya.»","Eixample Districte de l''Eixample: «L''Eixample es va construir en els anys de la industrialització de Catalunya, a la darreria del segle XIX i començament del XX.»","Sants-Montjuïc Districte de Sants-Montjuïc: «Sants-Montjuïc està format per vuit barris»","Sants-Montjuïc Districte de Sants-Montjuïc: «l''avinguda de Madrid i el carrer de Berlín, que el separen de les Corts»","Sarrià - Sant Gervasi Districte de Sarrià - Sant Gervasi: «És un dels districtes més verds de la ciutat i és, juntament amb Horta-Guinardó, la porta al Parc Natural de la Serra de Collserola, el pulmó més important de Barcelona.»","Gràcia Districte de Gràcia: «el nou mapa de barris l’hi reconeix oficialitzant el topònim Vila de Gràcia per denominar aquesta unitat de gairebé 50.000 habitants»","Horta-Guinardó Districte de Horta-Guinardó: «Amb una superfície de 1.192 hectàrees, Horta-Guinardó és el tercer districte més extens de Barcelona, després de Sants-Montjuïc i Sarrià - Sant Gervasi»","Sant Martí Districte de Sant Martí: «Diagonal Mar i el Front Marítim és el barri més nou de la ciutat, i es troba encara en procés de formació i consolidació.»","Població Padró municipal 2026: «A set dels deu districtes es redueix lleugerament el nombre de residents, mentre que a Ciutat Vella, Nou Barris i Sant Andreu es detecten petits increments.»","Mercè Festes de la Mercè: «el 1687, Barcelona fou atacada per una plaga terrible de llagosta i el poble invocà la protecció a la Mare de Déu de la Mercè.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Els deu districtes: una visió de conjunt","blocks":[{"text":"Barcelona s''organitza en deu districtes, i cadascun agrupa diversos barris amb història i personalitat pròpies. Ho recorda, per exemple, la web del districte de les Corts: «és un dels deu districtes de Barcelona». Per a un agent és bàsic saber ubicar cada barri dins del seu districte i conèixer els límits principals, perquè la Guàrdia Urbana treballa amb una unitat territorial per districte.","refs":[{"ref":"BCN_LC","law":"Districte de Les Corts","url":"https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris","quote":"Les Corts és un dels deu districtes de Barcelona"}]},{"text":"Pel que fa a l''extensió, els tres districtes més grans són Sants-Montjuïc, Sarrià-Sant Gervasi i Horta-Guinardó, que és el tercer, amb 1.192 hectàrees i l''11,9 % del terme municipal. Sarrià-Sant Gervasi té 20,09 km² i 148.172 habitants, i les Corts, unes 600 hectàrees i més de 82.000 persones.","refs":[{"ref":"BCN_HG","law":"Districte de Horta-Guinardó","url":"https://ajuntament.barcelona.cat/horta-guinardo/ca/el-districte-i-els-seus-barris","quote":"Amb una superfície de 1.192 hectàrees, Horta-Guinardó és el tercer districte més extens de Barcelona, després de Sants-Montjuïc i Sarrià - Sant Gervasi, i ocupa l’11,9% de l’extensió total del municipi barceloní."},{"ref":"BCN_SSG","law":"Districte de Sarrià - Sant Gervasi","url":"https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris","quote":"Té una extensió de 20,09 km2 i una població de 148.172 habitants."},{"ref":"BCN_LC","law":"Districte de Les Corts","url":"https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris","quote":"Amb una superfície de 600 hectàrees i una població de més de 82.000 persones, és un territori viu i complex."}]}]},{"n":"2","title":"Ciutat Vella: el centre històric","blocks":[{"text":"Ciutat Vella està delimitada pel perímetre de la muralla de l''antiga ciutat i correspon al centre històric. És el primer districte, l''embrió de Barcelona, i parlar-ne és parlar de la història de la ciutat des dels seus inicis. Limita a l''oest amb l''Eixample, a l''est amb el Mediterrani, al nord amb Sant Martí i al sud amb Sants-Montjuïc.","refs":[{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"El districte de Ciutat Vella està delimitat pel perímetre de la muralla de l’antiga ciutat i es correspon geogràficament amb el centre històric de Barcelona. Ciutat Vella és el primer districte de Barcelona, l’embrió de la ciutat."},{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"El districte limita a l’oest amb l’Eixample, a l’est amb el mar Mediterrani, al nord amb Sant Martí i al sud amb Sants-Montjuïc."}]},{"text":"Té quatre barris, cadascun amb una singularitat pròpia: al sud, la Barceloneta; a ponent, el Raval; al centre, el Gòtic; i a llevant, Sant Pere, Santa Caterina i la Ribera.","refs":[{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"Ciutat Vella està formada per quatre barris, cada un dels quals té una singularitat pròpia. Al sud hi trobem la Barceloneta; a ponent, el Raval; al centre, el Gòtic, i a llevant, Sant Pere, Santa Caterina i la Ribera."}]}]},{"n":"3","title":"L''Eixample i el Pla Cerdà","blocks":[{"text":"La Barcelona moderna va néixer a l''Eixample, ideada per l''enginyer i urbanista Ildefons Cerdà. Amb el seu pla urbanístic va dissenyar una ciutat igualitària, on no es diferencien uns barris dels altres i els serveis públics es reparteixen uniformement. El traçat es basava en una gran xarxa de carrers perpendiculars i travessers, tots uniformes, excepte dues vies esbiaixades superposades, la Diagonal i la Meridiana, i la Gran Via de les Corts Catalanes.","refs":[{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"La Barcelona moderna va néixer a l''Eixample, ideada per l''enginyer i urbanista a qui deu el seu dibuix màgic i únic: Ildefons Cerdà. Amb el seu pla urbanístic, Cerdà va dissenyar una ciutat igualitària, on no es diferencien uns barris dels altres i els serveis públics es reparteixen uniformement per tots els racons."},{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"es basava en una gran xarxa de carrers perpendiculars i travessers, tots ells uniformes, excepte dues vies esbiaixades superposades —la Diagonal i la Meridiana— i la Gran Via de les Corts Catalanes."}]},{"text":"El districte es va construir en els anys de la industrialització, a la darreria del segle XIX i començament del XX, quan la ciutat va enderrocar les muralles i va trencar amb el passat medieval. La part central, la Dreta de l''Eixample, va ser el barri de la burgesia, que hi va introduir el modernisme.","refs":[{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"L''Eixample es va construir en els anys de la industrialització de Catalunya, a la darreria del segle XIX i començament del XX. La part central, la Dreta de l''Eixample, va ser el barri de la burgesia que va introduir a casa seva un estil propi, el modernisme."}]},{"text":"L''Eixample té sis barris: la Dreta de l''Eixample, l''Antiga Esquerra, la Nova Esquerra, el Fort Pienc, la Sagrada Família i Sant Antoni. El Fort Pienc, entre la via del tren i la Gran Via, té l''estació del Nord i dos grans equipaments culturals: l''Auditori i el Teatre Nacional de Catalunya.","refs":[{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"L’Eixample està format per sis barris: la Dreta de l’Eixample, l’Antiga Esquerra de l’Eixample, la Nova Esquerra de l’Eixample, el Fort Pienc, la Sagrada Família i Sant Antoni."},{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"El Fort Pienc: L’estació del Nord dona personalitat a un barri situat entre la via del tren i la Gran Via. Allà se situa un dels punts culturals més importants, amb l’Auditori i el Teatre Nacional de Catalunya."}]}]},{"n":"4","title":"Sants-Montjuïc i les Corts","blocks":[{"text":"Sants-Montjuïc limita amb l''Hospitalet de Llobregat i el Prat de Llobregat; dins de Barcelona, l''avinguda de Madrid i el carrer de Berlín el separen de les Corts, i els carrers de Numància i Tarragona i les avingudes de Josep Tarradellas i el Paral·lel el separen de l''Eixample, Ciutat Vella i el mar. Té vuit barris: el Poble-sec, Hostafrancs, la Bordeta, la Font de la Guatlla, la Marina de Port, la Marina del Prat Vermell, Sants i Sants-Badal.","refs":[{"ref":"BCN_SM","law":"Districte de Sants-Montjuïc","url":"https://ajuntament.barcelona.cat/sants-montjuic/ca/el-districte-i-els-seus-barris","quote":"l''avinguda de Madrid i el carrer de Berlín, que el separen de les Corts, i els carrers de Numància i Tarragona i les avingudes de Josep Tarradellas i el Paral·lel, que el separen de l''Eixample, Ciutat Vella i el mar."},{"ref":"BCN_SM","law":"Districte de Sants-Montjuïc","url":"https://ajuntament.barcelona.cat/sants-montjuic/ca/el-districte-i-els-seus-barris","quote":"Sants-Montjuïc està format per vuit barris: el Poble-sec, Hostafrancs, la Bordeta, la Font de la Guatlla, la Marina de Port, la Marina del Prat Vermell, Sants i Sants-Badal."}]},{"text":"Les Corts té tres barris: les Corts, Pedralbes i la Maternitat i Sant Ramon. Limita amb els municipis de l''Hospitalet de Llobregat, Esplugues de Llobregat i Sant Just Desvern, i amb els districtes de Sants-Montjuïc, Sarrià-Sant Gervasi i l''Eixample.","refs":[{"ref":"BCN_LC","law":"Districte de Les Corts","url":"https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris","quote":"està format pels barris de les Corts, Pedralbes i la Maternitat i Sant Ramon."},{"ref":"BCN_LC","law":"Districte de Les Corts","url":"https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris","quote":"limita amb els termes municipals de l’Hospitalet de Llobregat, Esplugues de Llobregat i Sant Just Desvern i amb els districtes de Sants-Montjuïc, Sarrià-Sant Gervasi i l’Eixample."}]}]},{"n":"5","title":"Sarrià-Sant Gervasi, Gràcia i Horta-Guinardó","blocks":[{"text":"Sarrià-Sant Gervasi és el cinquè districte i un dels més verds; juntament amb Horta-Guinardó, és la porta al Parc Natural de la Serra de Collserola, el pulmó més important de Barcelona. Té regust de poble i el formen Sarrià, les Tres Torres, Sant Gervasi-la Bonanova, Sant Gervasi-Galvany, Vallvidrera, el Tibidabo i les Planes, i el Putxet i el Farró. Sant Gervasi-Galvany ocupa la part baixa de l''antic terme de Sant Gervasi, entre la Diagonal i la ronda del Mig.","refs":[{"ref":"BCN_SSG","law":"Districte de Sarrià - Sant Gervasi","url":"https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris","quote":"És un dels districtes més verds de la ciutat i és, juntament amb Horta-Guinardó, la porta al Parc Natural de la Serra de Collserola, el pulmó més important de Barcelona."},{"ref":"BCN_SSG","law":"Districte de Sarrià - Sant Gervasi","url":"https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris","quote":"compost pels barris de Sarrià, les Tres Torres, Sant Gervasi - la Bonanova, Sant Gervasi - Galvany, Vallvidrera, el Tibidabo i les Planes i el Putxet i el Farró."},{"ref":"BCN_SSG","law":"Districte de Sarrià - Sant Gervasi","url":"https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris","quote":"El barri de Sant Gervasi - Galvany ocupa la part baixa de l’antic terme de Sant Gervasi, entre la Diagonal i la ronda del Mig."}]},{"text":"Gràcia reivindica amb orgull el seu passat de municipi independent: va ser agregada a la ciutat el 1897. El nou mapa de barris oficialitza el topònim Vila de Gràcia per al nucli antic, de gairebé 50.000 habitants, carrers petits i places bulliciosos. Els altres barris són el Camp d''en Grassot i Gràcia Nova, i la Salut.","refs":[{"ref":"BCN_GR","law":"Districte de Gràcia","url":"https://ajuntament.barcelona.cat/gracia/ca/el-districte-i-els-seus-barris","quote":"va ser agregat a la ciutat el 1897), i el nou mapa de barris l’hi reconeix oficialitzant el topònim Vila de Gràcia per denominar aquesta unitat de gairebé 50.000 habitants"},{"ref":"BCN_GR","law":"Districte de Gràcia","url":"https://ajuntament.barcelona.cat/gracia/ca/el-districte-i-els-seus-barris","quote":"Els altres dos barris del districte són el Camp d’en Grassot i Gràcia Nova, un sector més recent i, per aquest motiu, autònom de la Vila, i el de la Salut."}]},{"text":"Horta-Guinardó se situa al sector nord-est de la ciutat, entre els districtes de Gràcia i Nou Barris.","refs":[{"ref":"BCN_HG","law":"Districte de Horta-Guinardó","url":"https://ajuntament.barcelona.cat/horta-guinardo/ca/el-districte-i-els-seus-barris","quote":"Està situat al sector nord-est de la ciutat, entre els districtes de Gràcia i Nou Barris."}]}]},{"n":"6","title":"Nou Barris, Sant Andreu i Sant Martí","blocks":[{"text":"Nou Barris és a l''extrem nord de la ciutat, entre la serra de Collserola i el districte de Sant Andreu. Sant Martí reuneix el passat i el futur de Barcelona en deu barris que van ser primordials en la industrialització i el creixement econòmic. Diagonal Mar i el Front Marítim és el barri més nou de la ciutat, encara en formació, i el Poblenou s''estén des de la Diagonal fins al mar.","refs":[{"ref":"BCN_NB","law":"Districte de Nou Barris","url":"https://ajuntament.barcelona.cat/noubarris/ca/el-districte-i-els-seus-barris","quote":"Nou Barris és un districte situat a l''extrem nord de la ciutat, entre la serra de Collserola i el districte de Sant Andreu."},{"ref":"BCN_STM","law":"Districte de Sant Martí","url":"https://ajuntament.barcelona.cat/santmarti/ca/el-districte-i-els-seus-barris","quote":"amb deu barris que tenen com a nexe comú el fet de ser primordials en la industrialització i el creixement econòmic de la ciutat."},{"ref":"BCN_STM","law":"Districte de Sant Martí","url":"https://ajuntament.barcelona.cat/santmarti/ca/el-districte-i-els-seus-barris","quote":"Diagonal Mar i el Front Marítim és el barri més nou de la ciutat, i es troba encara en procés de formació i consolidació. El Poblenou s''estén des de la Diagonal fins al mar."}]},{"text":"Nota: a la carpeta no hi ha la pàgina oficial del districte de Sant Andreu ni la llista completa de barris d''Horta-Guinardó, Nou Barris i Sant Martí; d''aquests districtes només es poden estudiar les dades que recullen els extractes.","refs":[{"ref":"Art. 2 NDIST","law":"Normes reguladores del funcionament dels districtes","url":"https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020","quote":"Horta-Guinardó, Nou Barris, Sant Andreu i Sant Martí"}]}]},{"n":"7","title":"La població segons el padró de 2026","blocks":[{"text":"Segons la lectura del padró a 1 de gener de 2026, Barcelona té 1.729.963 habitants, el segon valor més alt dels darrers quaranta anys, amb un descens gairebé simbòlic del 0,1 %. Set dels deu districtes perden residents, mentre que Ciutat Vella, Nou Barris i Sant Andreu creixen lleugerament. L''edat mitjana puja fins als 44,6 anys, i les persones centenàries arriben a 1.196, el 82 % dones.","refs":[{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"La població de Barcelona disminueix lleugerament el 2026 i se situa en 1.729.963 persones, el segon valor més elevat dels darrers quaranta anys."},{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"A set dels deu districtes es redueix lleugerament el nombre de residents, mentre que a Ciutat Vella, Nou Barris i Sant Andreu es detecten petits increments. L’edat mitjana de la població repunta lleugerament fins al 44,6 anys."}]},{"text":"Les persones de nacionalitat estrangera són 460.409, el 26,6 % del total, i hi conviuen fins a 181 nacionalitats a més de l''espanyola. En termes relatius destaca Ciutat Vella, amb un 54,8 % de població estrangera. Les nacionalitats més nombroses són la italiana, la colombiana i la pakistanesa, i Argentina és el país amb més nascuts a l''estranger.","refs":[{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"el nombre de persones empadronades de nacionalitat estrangera augmenta fins 460.409, el 26,6% del total."},{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"hi conviuen persones de fins a 181 nacionalitats diferents. En valors relatius, però, Ciutat Vella destaca clarament, amb un 54,8% de la població de nacionalitat estrangera."},{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"Les nacionalitats més abundants continuen sent la italiana, la colombiana i la pakistanesa."}]},{"text":"Hi ha 684.077 domicilis, gairebé un terç unipersonals. Els 11.012 naixements del 2025 són el valor més baix des de 1900 (llevat de 1939), i el saldo natural és negatiu a tots els districtes excepte a Ciutat Vella, on per tercer any hi ha més naixements que defuncions. Nota: són dades vives que canvien cada any; cal comprovar la darrera lectura del padró abans de l''examen.","refs":[{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"El saldo natural negatiu s’escampa a tots els districtes amb l’excepció de Ciutat Vella, on per tercer any consecutiu hi ha més naixements que defuncions."},{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"Lectura del padró municipal d’habitants a 01/01/2026"}]}]},{"n":"8","title":"Les festes de la Mercè","blocks":[{"text":"La Mercè és la patrona de Barcelona i la diada és el 24 de setembre. Segons la tradició, el 24 de setembre de 1218 la Mare de Déu de la Mercè es va aparèixer a Jaume I, a sant Pere Nolasc i a sant Ramon de Penyafort perquè fundessin un orde per rescatar els captius cristians. El 1687, davant una terrible plaga de llagosta, el poble va invocar-ne la protecció i la va proclamar patrona de la diòcesi, tot i que oficialment no ho va ser fins al 1868, amb el papa Pius IX.","refs":[{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"Diada: 24 de setembre"},{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"el 1687, Barcelona fou atacada per una plaga terrible de llagosta i el poble invocà la protecció a la Mare de Déu de la Mercè. Quan se’n sortiren, la proclamaren patrona de la diòcesi, encara que no ho fou de manera oficial fins el 1868, amb el papa Pius IX."}]},{"text":"Les festes comencen amb dos actes simultanis: el pregó, llegit al Saló de Cent de l''Ajuntament, i una desfilada del Seguici Popular de Barcelona, constituït el 1993 i format per l''Àliga de la Ciutat, els Gegants de la Ciutat i altres figures. El moment més simbòlic és quan, amb l''alcalde al balcó, l''Àliga i els Gegants de la Ciutat fan els balls protocol·laris a la plaça de Sant Jaume, amb la Banda Municipal.","refs":[{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"el pregó, llegit al Saló de Cent de l’Ajuntament, i una desfilada solemne del seguici popular de Barcelona"},{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"Es va constituir el 1993 i és format per la imatgeria festiva municipal –l’Àliga de la Ciutat i els Gegants de la Ciutat–"},{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"l’Àliga de la Ciutat i els Gegants de la Ciutat fan els balls protocol·laris respectius, amb la música representada per la Banda Municipal de Barcelona. Aquest moment és considerat el més simbòlic de la festa."}]},{"text":"Altres actes: les galejades de trabucaires, que a les deu del matí de la diada van de la catedral a la plaça de Sant Jaume; la cavalcada, acte central de les festes, organitzada des del 1986 per la Coordinadora de Geganters de Barcelona; l''encesa de la Porta de l''Infern; i el Galop de la Mercè, un ball exclusiu d''aquestes festes.","refs":[{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"A les deu del matí de la diada de la Mercè, una cercavila fa retrunyir els trabucs des de la catedral fins a la plaça de Sant Jaume."},{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"Des del 1986 se n’encarrega la Coordinadora de Geganters de Barcelona"},{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"El «Galop de la Mercè» és un ball exclusiu de les festes de la Mercè."}]}]},{"n":"9","title":"La Festa Major de Gràcia i l''ou com balla","blocks":[{"text":"La Festa Major de Gràcia de 2026 es va fer del 14 al 21 d''agost, vuit dies de cercaviles, gegants, castellers, trabucaires i colles de foc pels carrers de la Vila. Inclou el pregó, la missa a Santa Maria de Gràcia amb el ball de gegants i de l''Àliga de Gràcia, l''homenatge a Sant Roc a la cantonada de Llibertat i Fraternitat i el correfoc. El concurs de carrers guarnits lliura els premis a la plaça de la Vila, i la «Nit tranquil·la» proposa vetllades sense concerts sorollosos, amb activitats de baixa intensitat sonora.","refs":[{"ref":"FM_GRACIA","law":"Festa Major de Gràcia 2026","url":"https://ajuntament.barcelona.cat/gracia/ca/noticies/activitats-de-cultura-popular-per-la-festa-major-de-gracia-2026-40594","quote":"Del 14 al 21 d''agost, les colles de cultura popular tornen a omplir els carrers de la Vila amb una extensa programació festiva."},{"ref":"FM_GRACIA","law":"Festa Major de Gràcia 2026","url":"https://ajuntament.barcelona.cat/gracia/ca/noticies/activitats-de-cultura-popular-per-la-festa-major-de-gracia-2026-40594","quote":"Pilar d’ofrena floral i ball de les colles de cultura popular participants a la capelleta de Sant Roc, a la cantonada dels carrers de Llibertat i Fraternitat."},{"ref":"FM_GRACIA","law":"Festa Major de Gràcia 2026","url":"https://ajuntament.barcelona.cat/gracia/ca/noticies/activitats-de-cultura-popular-per-la-festa-major-de-gracia-2026-40594","quote":"18.00 h – Lliurament de premis del concurs de carrers guarnits A la plaça de la Vila."},{"ref":"FM_GRACIA","law":"Festa Major de Gràcia 2026","url":"https://ajuntament.barcelona.cat/gracia/ca/noticies/activitats-de-cultura-popular-per-la-festa-major-de-gracia-2026-40594","quote":"Vetllades sense concerts sorollosos, amb activitats de baixa intensitat sonora repartides pels carrers i espais de festa."}]},{"text":"L''ou com balla és una manifestació pròpia del Corpus barceloní i símbol de la identitat festiva de la ciutat. Els seus elements són l''ou, l''aigua i l''abundor de flors, amb un simbolisme de fecunditat i regeneració. Està documentat des de 1636, quan els llibres de comptes de la Seu registren la compra d''ous per al brollador. Els indrets tradicionals són el brollador del claustre de la Catedral i la Casa de l''Ardiaca, tot i que avui es pot veure en més patis històrics.","refs":[{"ref":"OU_BALLA","law":"Ou com balla","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/personatges-i-elements-festius/ou-com-balla","quote":"Aquesta manifestació, pròpia de la festa del Corpus barceloní, ha esdevingut amb el pas dels anys un símbol de la identitat festiva de la ciutat."},{"ref":"OU_BALLA","law":"Ou com balla","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/personatges-i-elements-festius/ou-com-balla","quote":"Ben segur que hi és des de 1636, quan es registren, als llibres de comptabilitat de l''obra de la Seu, les compres d''ous per al brollador pel dia de Corpus i l''octava."},{"ref":"OU_BALLA","law":"Ou com balla","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/personatges-i-elements-festius/ou-com-balla","quote":"El brollador del claustre de la Catedral de Barcelona i la Casa de l’Ardiaca són els indrets tradicionals on trobarem l’ou com balla."}]}]},{"n":"10","title":"Patrimoni i equipaments: el Fossar de les Moreres i el Mercat de la Concepció","blocks":[{"text":"El Fossar de les Moreres és un espai molt significatiu per a la història de Catalunya: en aquest antic cementiri de l''església de Santa Maria del Mar hi van ser enterrats els caiguts de l''11 de setembre de 1714. Va desaparèixer per la pressió demogràfica i es va urbanitzar; el 1983 l''Ajuntament el va remodelar amb un projecte de l''arquitecta Carme Fiol, i el 2001 s''hi va col·locar el pebeter, obra d''Alfons Viaplana, sempre encès en homenatge als caiguts.","refs":[{"ref":"FOSSAR","law":"Fossar de les Moreres","url":"https://ajuntament.barcelona.cat/ciutatvella/es/guia-del-distrito/equipamientos-por-temas/listado/fossar-de-les-moreres-99400386857","quote":"en aquest antic cementiri de l''església de Santa Maria del Mar van ser enterrats els caiguts durant l''11 de setembre de 1714."},{"ref":"FOSSAR","law":"Fossar de les Moreres","url":"https://ajuntament.barcelona.cat/ciutatvella/es/guia-del-distrito/equipamientos-por-temas/listado/fossar-de-les-moreres-99400386857","quote":"L''any 1983 l''Ajuntament de la ciutat va endegar un projecte de remodelació del sector a càrrec de l''arquitecta Carme Fiol. Posteriorment, el 2001, es va col·locar el peveter, obra d''Alfons Viaplana, està sempre encès"}]},{"text":"El Mercat de la Concepció és un dels mercats centenaris: es va inaugurar el 1888 en terrenys cedits per Joan Pla i Moreau, amb projecte d''Antoni Rovira i Trias, el mateix arquitecte del Mercat de Sant Antoni. Era la zona més poblada de l''Eixample. Als terrenys sobrants s''hi va fer una escola per a invidents, avui Conservatori Municipal i seu del Districte de l''Eixample. És al carrer d''Aragó, a la Dreta de l''Eixample.","refs":[{"ref":"MERCAT_CONC","law":"Mercat de la Concepció","url":"https://ajuntament.barcelona.cat/mercats/ca/mercat-de-la-concepcio","quote":"Es va construir en uns terrenys cedits per Joan Pla i Moreau, segons un projecte d''Antoni Rovira i Trias, també responsable del Mercat de Sant Antoni."},{"ref":"MERCAT_CONC","law":"Mercat de la Concepció","url":"https://ajuntament.barcelona.cat/mercats/ca/mercat-de-la-concepcio","quote":"el mercat actual es va inaugurar el 1888"},{"ref":"MERCAT_CONC","law":"Mercat de la Concepció","url":"https://ajuntament.barcelona.cat/mercats/ca/mercat-de-la-concepcio","quote":"Districte: Eixample Barri: la Dreta de l''Eixample"}]}]},{"n":"11","title":"Serveis: la platja de gossos i la L9 Sud","blocks":[{"text":"Durant la temporada alta de bany s''habilita a la part nord de la platja de Llevant una àrea delimitada i separada físicament perquè hi accedeixin persones amb gossos, amb horari de 10.30 a 19.30 h. Només hi poden entrar gossos amb microxip, que hi poden anar sense lligar. Durant la temporada de bany està prohibit l''accés de gossos a la resta de platges, lligats o no; la resta de l''any es pot passejar per totes les platges amb el gos deslligat.","refs":[{"ref":"PLATJA_GOS","law":"Platja de gossos de Llevant","url":"https://ajuntament.barcelona.cat/benestaranimal/ca/platges","quote":"A la part nord de la platja de Llevant s’instal·la, durant la temporada alta de bany, una àrea delimitada perquè hi accedeixin ciutadans amb gossos."},{"ref":"PLATJA_GOS","law":"Platja de gossos de Llevant","url":"https://ajuntament.barcelona.cat/benestaranimal/ca/platges","quote":"L’horari és de 10.30 a 19.30 hores. Dins d’aquest espai, on només poden accedir gossos amb microxip, aquests poden anar sense lligar"},{"ref":"PLATJA_GOS","law":"Platja de gossos de Llevant","url":"https://ajuntament.barcelona.cat/benestaranimal/ca/platges","quote":"Durant la temporada de bany queda prohibit l’accés dels gossos a tota la resta de platges, tant lligats com sense lligar. Durant la resta de l’any sí que és permès passejar per totes les platges de la ciutat sense lligar els gossos."}]},{"text":"La L9 Sud del metro es va posar en servei el 12 de febrer de 2016, de Zona Universitària a l''Aeroport (terminal 1); el tram Santa Coloma de Gramenet-la Sagrera passà a dir-se L9 Nord. Passa per Barcelona, l''Hospitalet i el Prat de Llobregat, afegeix uns 20 km i 15 parades accessibles i fa el trajecte en 32 minuts, amb una freqüència de 7 minuts els feiners.","refs":[{"ref":"TMB_L9","law":"TMB, L9 Sud","url":"https://www.tmb.cat/ca/l10-sud","quote":"El 12 de febrer del 2016 es va posar en servei un nou tram de la línia 9 de metro, des de Zona Universitària fins a l’Aeroport de Barcelona-El Prat, amb la denominació L9 Sud."},{"ref":"TMB_L9","law":"TMB, L9 Sud","url":"https://www.tmb.cat/ca/l10-sud","quote":"La L9 Sud passa pels municipis de Barcelona, l’Hospitalet i el Prat de Llobregat."},{"ref":"TMB_L9","law":"TMB, L9 Sud","url":"https://www.tmb.cat/ca/l10-sud","quote":"Un trajecte que s’efectua en 32 minuts, amb una freqüència bàsica de 7 minuts entre els trens en dies feiners."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Ciutat Vella: quatre barris (Barceloneta, Raval, Gòtic i Sant Pere, Santa Caterina i la Ribera); limita al sud amb Sants-Montjuïc.","refs":[{"ref":"BCN_CV","law":"Districte de Ciutat Vella","url":"https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris","quote":"al sud amb Sants-Montjuïc"}]},{"text":"Eixample: Pla Cerdà; sis barris; construït a finals del XIX i inicis del XX; la Dreta és el barri de la burgesia modernista.","refs":[{"ref":"BCN_EIX","law":"Districte de l''Eixample","url":"https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris","quote":"Ildefons Cerdà"}]},{"text":"Sants-Montjuïc té vuit barris; l''avinguda de Madrid i el carrer de Berlín el separen de les Corts.","refs":[{"ref":"BCN_SM","law":"Districte de Sants-Montjuïc","url":"https://ajuntament.barcelona.cat/sants-montjuic/ca/el-districte-i-els-seus-barris","quote":"Sants-Montjuïc està format per vuit barris"}]},{"text":"Gràcia es va agregar el 1897; Horta-Guinardó és el tercer districte més extens.","refs":[{"ref":"BCN_GR","law":"Districte de Gràcia","url":"https://ajuntament.barcelona.cat/gracia/ca/el-districte-i-els-seus-barris","quote":"el 1897"}]},{"text":"Padró 2026: 1.729.963 habitants; edat mitjana de 44,6 anys; 26,6 % d''estrangers; 181 nacionalitats; Ciutat Vella, amb un 54,8 % d''estrangers.","refs":[{"ref":"PADRO26","law":"Padró municipal 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"fins al 44,6 anys"}]},{"text":"Mercè: 24 de setembre; patrona per la plaga de llagosta (1687); pregó al Saló de Cent; Seguici Popular des del 1993.","refs":[{"ref":"MERCE","law":"Festes de la Mercè","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce","quote":"plaga terrible de llagosta"}]},{"text":"Ou com balla: Corpus; documentat des de 1636; al claustre de la Catedral i a la Casa de l''Ardiaca.","refs":[{"ref":"OU_BALLA","law":"Ou com balla","url":"https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/personatges-i-elements-festius/ou-com-balla","quote":"des de 1636"}]},{"text":"Fossar de les Moreres: antic cementiri de Santa Maria del Mar; pebeter d''Alfons Viaplana (2001). Mercat de la Concepció: obra de Rovira i Trias, com el de Sant Antoni.","refs":[{"ref":"FOSSAR","law":"Fossar de les Moreres","url":"https://ajuntament.barcelona.cat/ciutatvella/es/guia-del-distrito/equipamientos-por-temas/listado/fossar-de-les-moreres-99400386857","quote":"obra d''Alfons Viaplana"}]},{"text":"Platja de gossos: Llevant nord, en temporada de bany i amb microxip. L9 Sud: Barcelona, l''Hospitalet i el Prat.","refs":[{"ref":"PLATJA_GOS","law":"Platja de gossos de Llevant","url":"https://ajuntament.barcelona.cat/benestaranimal/ca/platges","quote":"només poden accedir gossos amb microxip"}]}]}]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris'), 'https://ajuntament.barcelona.cat/eixample/ca/el-districte-i-els-seus-barris', null, null, null, 'Otras normas citadas: Districte de Les Corts (https://ajuntament.barcelona.cat/lescorts/ca/el-districte-i-els-seus-barris), Districte de Ciutat Vella (https://ajuntament.barcelona.cat/ciutatvella/ca/el-districte-i-els-seus-barris), Districte de Sants-Montjuïc (https://ajuntament.barcelona.cat/sants-montjuic/ca/el-districte-i-els-seus-barris), Districte de Sarrià - Sant Gervasi (https://ajuntament.barcelona.cat/sarria-santgervasi/ca/el-districte-i-els-seus-barris), Districte de Gràcia (https://ajuntament.barcelona.cat/gracia/ca/el-districte-i-els-seus-barris), Districte de Horta-Guinardó (https://ajuntament.barcelona.cat/horta-guinardo/ca/el-districte-i-els-seus-barris), Districte de Sant Martí (https://ajuntament.barcelona.cat/santmarti/ca/el-districte-i-els-seus-barris), Padró municipal 2026 (https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html), Festes de la Mercè (https://www.barcelona.cat/culturapopular/ca/festes-i-tradicions/festes-de-la-merce)'
  from public.topics t where t.slug = 'gub-t39-coneixement-barcelona-2'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'gub-t%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'guardia-urbana-barcelona',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema, Guardia Urbana)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Guardia Urbana de Barcelona: % fichas con apuntes publicadas', v_n;
end $$;

commit;
